(window.COSMIC_I18N = window.COSMIC_I18N || {}).ko = Object.freeze({"moon":{"aries":"양자리에 있는 달","taurus":"황소자리에 있는 달","gemini":"쌍둥이자리에 있는 달","cancer":"게자리에 있는 달","leo":"사자자리에 있는 달","virgo":"처녀자리에 있는 달","libra":"천칭자리에 있는 달","scorpio":"전갈자리에 있는 달","sagittarius":"사수자리에 있는 달","capricorn":"염소자리에 있는 달","aquarius":"물병자리에 있는 달","pisces":"물고기자리에 있는 달"},"sky":{"classic":{"fire":["{moon}은 앞으로 나아갈 용기를 북돋우며 행동하기 전에 방향을 분명히 정하라고 권합니다.","{moon}은 생기 넘치는 에너지를 불어넣고, 그 에너지는 뚜렷한 목표를 만날 때 더욱 빛납니다.","{moon}은 모든 것이 완벽해질 때까지 기다리지 않고 전진하려는 마음을 깨웁니다.","{moon}은 진심 어린 도전을 응원하며 신중한 추진력의 가치를 일깨웁니다.","{moon}은 서두를 일이 아니라 진정 용기를 낼 만한 일이 무엇인지 비춰 줍니다.","{moon}은 하늘에 강렬한 리듬을 더하며 분별력 있게 그 흐름을 따르라고 권합니다."],"earth":["{moon}은 단순한 기준과 현실적인 행동으로 돌아가라고 권합니다.","{moon}은 인내심과 자기 속도로 나아가는 즐거움을 소중히 여깁니다.","{moon}은 꾸준히 쌓아 올리는 것에 다시 시선을 돌리게 합니다.","{moon}은 평온함과 안정감, 세부 사항을 돌보는 정성을 북돋웁니다.","{moon}은 자신에게 좋은 것을 포기하지 않으면서도 실용적인 선택을 하도록 돕습니다.","{moon}은 눈에 띄지 않는 진전도 아주 튼튼한 바탕이 될 수 있음을 일깨웁니다."],"air":["{moon}은 대화를 활발하게 하고 새로운 생각이 오가게 합니다.","{moon}은 다양한 의견과 예상 밖의 관점을 열린 마음으로 만나게 합니다.","{moon}은 호기심을 북돋우면서도 생각의 중심을 잃지 말라고 권합니다.","{moon}은 오늘의 대화에 특별한 의미를 더합니다.","{moon}은 가벼운 마음과 작은 질문에서 시작되는 발견을 응원합니다.","{moon}은 상상력을 억누르지 않으면서 생각을 정리하라고 권합니다."],"water":["{moon}은 감정을 더욱 선명하게 느끼게 하며 부드럽게 받아들이도록 이끕니다.","{moon}은 현재를 이해하는 데 도움이 될 추억을 깨웁니다.","{moon}은 자신의 내면에 귀 기울이고 가까운 사람들과 진솔한 시간을 보내도록 권합니다.","{moon}은 느낌과 침묵에 한층 깊은 의미를 더합니다.","{moon}은 마음에 여유를 줄 때 직관이 빛나도록 돕습니다.","{moon}은 자신의 필요도 잊지 않으면서 소중한 관계를 돌보라고 권합니다."]},"funny":{"fire":["{moon}은 이미 버스에 타고 있으면서도 버스를 향해 달릴 만큼의 에너지를 드립니다.","{moon}은 아무리 짧은 줄이라도 공인되지 않은 인내력 시험장으로 바꿉니다.","{moon}은 주전자가 물을 끓이기도 전에 프로젝트 다섯 개를 시작하자고 제안합니다.","{moon}은 피자 한 판을 고르는 중대한 결정을 위해 마음속에 거대한 불을 지핍니다.","{moon}은 메시지를 다시 읽기도 전에 보내기 버튼부터 누르라고 속삭입니다.","{moon}은 모두에게 용기를 나눠 주지만 자기 차례를 기다리는 사람만은 예외로 둡니다."],"earth":["{moon}은 포근한 담요와 빽빽한 일정표가 얼마든지 공존할 수 있다고 선언합니다.","{moon}은 장보기 목록을 최고 등급의 전략 문서로 격상합니다.","{moon}은 좋아하는 안락의자에서 일어나지 않고도 야망을 품을 수 있다고 일깨웁니다.","{moon}은 서랍 하나 정리한 일을 위대한 개인적 승리로 치켜세웁니다.","{moon}은 누군가 소파를 옮기겠다고 위협할 때일수록 침착하게 생각하라고 권합니다.","{moon}은 간식 시간을 공식 최우선 일정으로 바꿉니다."],"air":["{moon}은 대화를 열두 개나 시작해 놓고 첫 대화가 왜 시작됐는지 잊어버립니다.","{moon}은 별 의미 없는 알림 두 개 사이에서 천재적인 아이디어 세 개를 터뜨립니다.","{moon}은 결국 지도와 도표까지 필요한 일화를 이야기하게 만듭니다.","{moon}은 단체 채팅방이 따라잡기도 전에 온갖 의견을 쏟아 냅니다.","{moon}은 단순한 안녕하세요 한마디를 인생의 의미에 관한 토론으로 바꿉니다.","{moon}은 적절한 말을 찾아 준 다음 지나치게 많은 말까지 덤으로 드립니다."],"water":["{moon}은 오래된 상자 하나를 정리하는 일에 장엄한 드라마 음악을 깔아 줍니다.","{moon}은 날짜도 기억나지 않는 어린 시절 어느 일요일을 그리워하게 만듭니다.","{moon}은 흐릿한 사진 한 장을 개인 박물관에 전시할 소중한 추억으로 바꿉니다.","{moon}은 찬장에서 잊혔던 컵이 돌아온 일마저 감동적으로 만듭니다.","{moon}은 살짝 기운 화분에게 무슨 일 있느냐고 묻게 만듭니다.","{moon}은 고작 알겠어라고만 적힌 메시지에도 깊은 의미를 부여합니다."]},"piquant":{"fire":["{moon}은 조급함이 시간 관리 문제 따위가 아니라 개성이라고 굳게 믿게 만듭니다.","{moon}은 그냥 지나가려던 사람을 상대로 존재하지도 않는 경기를 시작하게 합니다.","{moon}은 주소도 확인하기 전에 달려 나가라고 부추깁니다.","{moon}은 조용한 대화마다 보이지 않는 초시계를 설치합니다.","{moon}은 세상이 감탄해야 할 재능으로 당신의 조급함을 착각합니다.","{moon}은 다른 사람들이 규칙을 이해하기도 전에 승리를 선언하도록 허락합니다."],"earth":["{moon}은 당신의 안락한 공간을 철통 경비 구역으로 바꿉니다.","{moon}은 쿠션 하나 바꾸려면 주민 공청회가 필요하다고 확신시킵니다.","{moon}은 익숙한 습관을 방해하는 모든 제안에 우주적 거부권을 행사합니다.","{moon}은 안정감만 찾다 보면 좋아하는 가구와 결혼하게 될 수도 있다고 일깨웁니다.","{moon}은 평소 일정을 개정 불가능한 헌법으로 격상합니다.","{moon}은 즉흥적인 행동을 반드시 신고해야 할 사건으로 보게 만듭니다."],"air":["{moon}은 아이디어를 천 개나 주고 그중 하나를 끝내는 일은 남에게 맡깁니다.","{moon}은 토론을 시작한 뒤 애초에 토론할 필요가 있었는지 다시 토론을 엽니다.","{moon}은 휴대전화 화면보다 더 빨리 의견을 바꾸도록 격려합니다.","{moon}은 갈림길을 계속 늘려서 목적지에 도착하는 일을 선택 사항으로 만듭니다.","{moon}은 마지막 한마디를 주고 거기에 마지막 열네 마디를 더 얹어 줍니다.","{moon}은 책임자도 없이 당신의 생각들을 무기한 회의에 소집합니다."],"water":["{moon}은 평범한 침묵을 네 쪽짜리 감정 보고서로 바꿉니다.","{moon}은 모두가 이미 종결 처리한 추억을 다시 회의 안건에 올립니다.","{moon}은 메시지 끝의 마침표 하나를 역사적 사건으로 해석하도록 돕습니다.","{moon}은 오래된 과자 포장지에까지 향수를 불어넣습니다.","{moon}은 멀리서 들린 한숨 하나를 두고 비상대책위원회를 소집합니다.","{moon}은 방에 들어가기도 전에 분위기를 느끼게 하고 그걸 장편소설로 쓰게 만듭니다."]}},"mercury":{"classic":["수성이 역행하는 시기에는 메시지를 보내기 전에 다시 읽어 보세요. 작은 확인이 오해를 줄일 수 있습니다.","수성 역행 아래에서 오래된 대화가 다시 떠오를 수도 있습니다. 그때의 맥락을 차분히 살펴보세요.","수성 역행은 모두가 같은 뜻으로 이해했다고 단정하기보다 세부 사항을 확인하라고 권합니다."],"funny":["수성 역행은 두 번 읽어 보라고 권합니다. 수수께끼 같은 메시지는 사실 단어 하나가 빠진 것일지도 몰라요.","옛 이야기가 다시 나왔나요? 수성 역행이 미완성 대화가 담긴 서랍을 찾아냈나 봅니다.","수성 역행은 의사소통을 시험합니다. 우주를 탓하기 전에 메시지 수신자부터 확인해 보세요."],"piquant":["수성 역행이 애매한 메시지를 보내고 곧장 사라져도 된다는 우주적 허가증은 아닙니다.","수성 역행과 함께 과거가 돌아오기도 합니다. 그렇다고 가져온 모든 파일을 열어야 하는 건 아니죠.","수성 역행은 말을 다시 살펴보라고 합니다. 상대가 마음속 생각의 자막까지 추측할 의무는 없으니까요."]},"signs":{"aries":{"classic":{"career":["당신의 진취적인 태도는 직장에서 새로운 길을 열 수 있어요. 다만 다른 사람을 움직이기 전에 목표를 분명히 해 보세요.","프로젝트가 좀처럼 시작되지 않을 때 당신의 에너지가 빛나요. 혼자 해결할 일과 함께 결정할 일을 구분해 보세요.","업무상의 어려움은 당신의 도전 정신을 자극해요. 다른 사람의 생각에도 귀를 기울이면 영향력이 더욱 커질 수 있어요.","경쟁은 당신의 결의를 깨워요. 자신의 가치를 끊임없이 증명하는 수단보다 성장의 원동력으로 삼아 보세요.","지시가 모호할 때는 일단 행동하고 싶어져요. 핵심 질문 몇 가지만 던져도 불필요한 우회를 줄일 수 있어요.","빠른 성과를 바라는 마음에는 유연한 계획이 필요해요. 큰 목표를 눈에 보이는 단계로 나누고 작은 진전도 인정해 주세요.","회의가 길어질 때 당신의 솔직함이 분위기를 바꿀 수 있어요. 다만 적절한 순간을 골라 의견을 내세요.","먼저 나서는 모습이 당신답습니다. 동료들이 뒤쫓는 대신 함께 나아갈 수 있도록 방법도 공유해 보세요."],"love":["당신의 자발적인 애정 표현은 관계에 활기를 불어넣어요. 상대방에게도 자기만의 속도를 허락해 주세요.","소중한 사람에게 마음을 숨기지 않는 편이군요. 진심 어린 경청도 사랑을 전하는 강한 방법이에요.","너무 빨리 뱉은 말이 본뜻보다 날카롭게 들릴 수 있어요. 의견 차이를 대결로 만들기 전에 다시 표현해 보세요.","당신은 뜨거운 감정을 좋아하지만 조용한 순간도 깊은 친밀감을 키울 수 있어요.","생각이 다를 때에도 솔직함에 여지를 남겨 주세요. 설득하기 전에 이해하려는 노력이 중요해요.","독립심은 당신에게 중요한 균형이에요. 상대방이 알아서 짐작하리라 기대하지 말고 필요한 공간을 말해 주세요.","먼저 다가가려는 마음이 강하면 모든 주도권을 혼자 쥐게 될 수 있어요. 상대방의 뜻밖의 제안도 기다려 보세요.","잘못을 인정한다고 강인함이 줄어들지는 않아요. 소박한 행동 하나가 긴 설명보다 마음을 누그러뜨릴 수 있어요."],"wellbeing":["강한 에너지만큼 회복의 시간도 필요해요. 바쁜 일정 사이에 진짜 휴식을 마련해 보세요.","조급함이 올라올 때 목적지 없는 산책으로 속도를 늦춰 보세요.","도전으로 가득한 하루에는 평범한 피로를 무시하기 쉬워요. 쉬고 싶은 마음을 장애물처럼 여기지 마세요.","행동을 좋아하는 당신에게도 아무것도 이루지 않아도 되는 시간이 필요해요.","예상 밖의 일이 생기면 다시 움직이기 전에 잠시 숨을 고르세요. 그 짧은 틈이 평정을 되찾게 할 수 있어요.","무엇이든 빨리하려는 습관이 식사까지 따라올 수 있어요. 좋아하는 음식을 천천히 음미해 보세요.","기다림을 배운다고 전진을 포기하는 것은 아니에요. 결과보다 과정의 리듬을 즐기는 활동을 해 보세요.","프로젝트 때문에 잠을 뒤로 미루고 있다면 일상에 수면 시간을 다시 마련해 주세요."],"wisdom":["용기는 어떤 싸움을 선택할지 알 때 더 깊어집니다.","강한 추진력도 방향이 분명해야 멀리 나아갑니다.","생각하며 내딛는 한 걸음이 성급한 질주보다 멀리 갈 수 있습니다.","성숙함은 모든 경쟁에 뛰어들지 않을 줄 아는 것입니다.","조급함은 바람을 알려 주고 인내는 그 바람에 길을 열어 줍니다.","함께 나아가려면 첫걸음을 잠시 늦춰야 할 때도 있습니다.","솔직한 말은 경청할 자리를 남길 때 더욱 가치 있습니다.","진정한 출발은 움직이기 전, 의도를 분명히 하는 데서 시작됩니다."],"roast":["당신의 열정이 너무 앞서가면 주변 사람들은 계획을 이해할 시간조차 얻지 못해요.","모든 의견 충돌을 즉시 해결하려 하면 시간을 두고 나올 답을 기다릴 여유가 없어져요.","좋은 아이디어라도 실행 속도까지 강요하면 본래의 힘이 줄어들 수 있어요.","이기려는 욕구가 평범한 대화마저 불필요한 경쟁으로 바꿀 때가 있어요.","솔직함은 적절한 표현과 함께할 때 더욱 빛나요.","당신이 효율성이라 부르는 것은 가끔 질문을 끝까지 듣기도 전에 내린 결정 같아요.","일이 뜻대로 되지 않으면 잠시 쉬는 대신 에너지를 더 쏟아붓곤 해요.","프로젝트를 힘차게 시작하는 데 능하지만 차근차근 마무리하는 일에는 더 많은 인내가 필요해요."]},"funny":{"career":["당신의 서류에는 벌써 '완료' 도장이 찍혔습니다. 상사는 이제야 그 일을 설명할 회의를 열었는데 말이죠.","동료가 짧은 회의라고 말하면 당신은 반사적으로 결승선부터 찾습니다.","긴급이라고 표시된 업무를 보면 기분이 좋아져요. 드디어 자기 삶의 방식을 이해하는 문서가 나왔거든요.","두 사람이 복사기에 먼저 가려고 할 때 이미 경쟁은 시작돼요. 상대는 참가한 줄도 모릅니다.","아이디어 열두 개를 관리하려고 표를 만들었습니다. '시작 전에 읽기' 칸은 장식으로 남았군요.","이 프로젝트는 분명 팀 작업이었어요. 그런데 당신은 이미 역할을 나누고 시작한 뒤 왜 아무도 못 따라오냐고 묻습니다.","상사가 천천히 하라고 하면 당신 귀에는 신기하게도 신기록을 세우라는 말로 들려요.","커피를 마시러 쉬는 건 좋죠. 단, 부서 사람들 중 제일 먼저 도착해야 합니다.","회의는 역할을 나누기 위한 자리였습니다. 그런데 당신은 이미 시작한 프로젝트 세 개와 종료 기념식 초대장을 들고 왔군요.","시범 프로젝트를 좋아하십니다. 특히 일정표에서 조종사, 비행기, 활주로에 전부 당신 이름이 쓰여 있을 때요.","동료가 '더 파고들 아이디어'라고 적었습니다. 당신은 디지털 삽을 주문하고 첫 발표 일정까지 잡았군요.","당신식 팀워크란 동료들이 아직 사무실 신발을 찾는 동안 '출발합시다!'라고 외치는 것입니다."],"love":["당신에게 낭만적인 데이트란 누가 먼저 도착하는지 겨루는 활동이에요. 미니골프마저 올림픽 종목이 됩니다.","상대방이 식당을 고르는 사이 당신은 메뉴 세 개를 보고 머릿속으로 이미 예약까지 마쳤어요.","사랑에 빠지는 모습이 선물 포장을 뜯는 것 같군요. 리본은 찢어졌고 얼굴엔 미소가 가득한데, 포장지는 아직 머리에 걸려 있습니다.","애정은 당신을 대담하게 만들어요. 사랑스러운 문자를 보내자마자 휴대전화를 놓기도 전에 답장을 확인하죠.","나중에 보자는 말에는 당장 날짜와 시간, 서면 확약까지 요청합니다. 물론 웃으면서요.","촛불 아래 저녁 식사는 평화롭다가도 디저트를 고르는 순간 열띤 토론회로 변해요.","서프라이즈가 있다는 말이 끝나기도 전에 찬장에서 단서를 찾습니다. 기다림은 당신의 연애 사전에 없거든요.","누군가 장난을 치면 즉시 반격할 말을 준비해요. 그러고서야 애정 표현이었다는 걸 떠올립니다.","당신의 유혹은 세 단계입니다. 첫눈에 반하기, 거창한 행동, 그리고 식당 이름 알아내기.","로맨틱한 깜짝 선물을 너무 빨리 준비해서 촛불은 포장도 못 벗었군요.","눈빛 한 번 나누자마자 함께할 모험부터 제안하십니다. 상대방은 빵 하나 고르는 중이었는데요.","화해시키는 속도가 워낙 빨라 꽃다발이 대화가 끝나기도 전에 도착합니다."],"wellbeing":["당신이 생각하는 이상적인 휴식은 기록 측정만 없앤 경주예요. 속도는 그대로죠.","명상을 하려고 하면 머릿속 모든 생각에 빨리 조용히 하라고 명령을 내립니다.","느긋한 산책도 계단 하나를 발견하는 순간 탐험대 출정식으로 변해요.","낮잠은 어딘가 수상해요. 재배치할 쿠션이 이렇게 많은데 왜 가만히 있어야 할까요?","조용히 있는 시간은 정확히 8초예요. 그 뒤에는 다른 사람들도 지루하냐고 묻습니다.","물 한 잔은 당신이 금방 끝낼 일 세 가지를 처리하는 동안 기다려요. 물잔도 이런 긴장감엔 동의한 적이 없습니다.","침착하게 호흡하는 건 좋은 생각이에요. 그걸 숨 오래 쉬기 대회로만 만들지 않는다면요.","잠깐 바람 쐬러 간다면 가족에게 미리 알려 주세요. 가벼운 산책이 목표 있는 등산으로 변할 수 있으니까요.","휴식 앱을 설치했습니다. 화면을 바꾸지 않고 1분을 버텼다고 앱에서 '축하합니다'라고 하네요.","가볍게 바람 쐬러 나갔다가 동네 계단들의 순위표를 만들어 돌아오셨군요.","요가 매트는 당신의 발자국만 잘 압니다. 출발선처럼 밟고 지나가시니까요.","오후 내내 아무것도 하지 않으려고 했습니다. 8분 만에 가구를 이동 속도별로 정렬해 놓으셨군요."],"wisdom":["용기는 넘치지만 기다리기 버튼은 아직 발견되지 않았어요.","속도는 문을 열어 주지만 입구와 출구를 혼동하지 않을 때만 그렇습니다.","큰 용기란 때로 울타리를 넘기 전에 안내판부터 읽는 것입니다.","방향을 정하면 모든 우회로를 세계 일주 코스로 만들지 않아도 됩니다.","우주는 당신의 독촉 문자를 읽지 않고도 자기 속도로 움직입니다.","꿈을 향해 달리세요. 다만 문이 열려 있는지 먼저 확인하세요.","지도도 확인하지 않은 대단한 추진력은 여전히 추진력일 뿐입니다.","침묵이 꼭 당신을 향한 도발은 아닙니다.","맨 처음 보이는 문이 늘 정답은 아닙니다. 옆의 벽이 그 사실을 증언할 수 있겠네요.","용기는 떠날 줄 압니다. 분별력은 경로를 확인할 때까지 잠시 기다릴 줄 알죠.","아이디어를 향해 달린다고 그 아이디어의 주소를 안 물어봐도 되는 건 아닙니다.","돌아가는 길이 실패는 아닙니다. 이미 지나친 표지판을 다시 볼 유일한 방법일 수도 있으니까요."],"roast":["당신의 내비게이션은 경로를 다시 계산한다는 말을 두 번 하지 못해요. 당신 성격을 아니까요.","과자 자판기와 말다툼을 벌이셨군요. 재판에서는 동전 투입구가 증인으로 소환됐습니다.","당신이 말하는 건설적인 대화란 모두가 집에 가려고 결국 당신 의견에 동의하는 대화예요.","초인종이 다 울리기도 전에 문 앞에 서 있어요. 택배 기사도 놀라죠.","내비게이션이 우회전하라고 하자 '길은 제가 알아요'라며 자기 차고 앞에 선 탐험가처럼 확신하셨군요.","리모컨이 한 번에 채널을 바꾸지 않자 냅킨 한쪽에 정식 경고장을 써서 보내셨군요.","천천히라는 말은 당신에게 매 층 멈추는 엘리베이터만큼 못 미더워요.","짜증 나는 알림에는 화를 냈다가도 좋은 소식이면 즉시 용서합니다.","알람이 울리자 단호하게 협상하셨군요. 알람은 증인을 부르려고 한 번 더 울립니다.","에스컬레이터에 주도성이 부족하다며 타박하셨군요. 에스컬레이터는 정확히 자기 일을 하고 있었는데요.","자동문이 늦게 열리자 공공 출입구 개혁 계획을 설명하셨군요.","퍼즐이 풀리지 않자 상자가 왼쪽 위 모서리 조각을 일부러 숨겼다고 고발하셨네요."]},"piquant":{"career":["업무 지시도 읽지 않고 프로젝트부터 시작하셨군요. 팀원들은 철거 현장을 보며 설계도를 추측하고 있습니다.","당신의 일정표에는 긴급, 매우 긴급, 어제, '아직 왜 안 끝났지?'라는 네 칸이 있습니다. 월요일은 대화에서 나가 버렸군요.","생각 좀 해 보자는 동료의 말은 당신에게 공격 개시 신호죠. 생각은 책상 밑에 숨었습니다.","장애물을 보면 예절을 가르치겠다며 돌진해요. 그런데 그 장애물은 열려 있는 문이었습니다.","서류 배분을 사내 선수권 대회로 바꾸셨군요. 인턴들은 메달이 아니라 종이를 받으러 온 겁니다.","권고문 여섯 쪽을 무시하고 역사적인 결정을 내리셨군요. 최종 보고서는 '첫 페이지에 명시했듯이'로 시작합니다.","착수 회의도 시작하지 않았는데 결과부터 발표합니다. 사실관계를 존중하느라 회의록은 모두 가정법으로 작성되고 있군요.","타고난 리더십은 프린터에게까지 발휘됩니다. 명령을 내리면 프린터는 외교적 용지 걸림으로 답하죠.","속보입니다. 존재 이유도 모르는 프로젝트를 벌써 끝내셨군요. 고객은 포스터를 원했는데 당신은 고속도로 개통식을 열었습니다.","사내 공지입니다. 읽지 않은 지시는 이제 파일 장식으로 간주됩니다. 당신은 이미 서명하셨군요.","당신의 사무실은 지도 없는 지휘본부 같습니다. 명령은 끊이지 않는데 부대가 어디로 가는지는 아무도 모르죠.","'즉각적인 성과'를 회의 안건으로 올리셨군요. 회의록에는 간단히 '현실 불참'이라고 적혔습니다."],"love":["당신의 로맨틱한 솔직함은 정지 버튼 없는 경보기처럼 울려요. 섬세함은 발언 기회도 얻지 못했습니다.","둘이 볼 영화를 고르는 일도 당신에겐 논쟁 대회예요. 휴전 전에 엔딩 크레딧이 올라갑니다.","조금만 의견이 달라도 역사적인 연설처럼 자기주장을 펼칩니다. 쟁점은 머그컵 색깔이었는데요.","서프라이즈를 기다려 달라는 말에 이미 포장을 뜯었어요. 신비감은 사직서를 냈습니다.","당신의 다정한 고백은 로켓 발사만큼 정확합니다. 상대방은 아직 외투를 어디에 둘지도 못 정했는데요.","당신의 거창한 고백 뒤에서는 즉각적인 답변을 요구하는 작은 목소리가 들려요. 달력의 심장도 그런 마감은 못 맞춥니다.","답장이 늦으면 가설 네 개와 대응책 세 개를 세웁니다. 휴대전화는 중재자를 요청했어요.","낭만적인 주말을 번개 원정처럼 계획합니다. 가장 큰 깜짝 선물은 상대와 한 번도 상의하지 않았다는 사실이군요.","당신의 적극적인 구애는 영화 예고편처럼 전개됩니다. 대화 두 번, 웅장한 음악, 상상 속 결혼식 엔딩 크레디트까지요.","당신은 운명적인 첫눈에 반함이라고 부르죠. 달력은 다음 달을 통째로 점령당했다고 말합니다.","당신식 화해는 상대방이 설명을 마치기도 전에 불꽃놀이를 터뜨리는 것 같습니다. 볼거리는 좋지만 타이밍이 문제군요.","낭만적인 보물찾기를 준비했는데 유일한 단서는 '서두르세요'였습니다. 보물도 숨기를 포기했군요."],"wellbeing":["휴식 계획에 가장 가까운 벤치까지 전력 질주하는 일정이 들어 있습니다. 벤치는 이런 책임을 맡게 될 줄 몰랐겠죠.","쉬려고 산책하면서 상상 속 모든 보행자를 추월해요. 나무들이 심판을 요청합니다.","소파가 5분간 품어 주자 이제는 야망이 부족하다고 나무라요. 쿠션들이 노조를 결성합니다.","줄이 천천히 움직이면 시공간과 협상을 시작합니다. 우주는 접수한 요청을 기각했어요.","초시계 없는 휴식은 수상하죠. 주전자 옆에 결승선을 설치해 버립니다.","당신의 폭발적인 에너지 앞에서 해먹이 차분함을 설명하려 해요. 당신은 그 말까지 끊습니다.","침묵을 견디지 못해 토론을 열려고 해요. 화분은 입장 표명을 거절했습니다.","서랍 하나 정리하는 일까지 속도 경기로 바꾸셨군요. 양말들은 도착 순서대로 정렬됐습니다.","고객 후기입니다. '벤치는 편했지만 발전이 없었어요.' 별점 하나, 성급한 종아리 올림.","쉬는 동안 손목시계가 움직임을 셌습니다. 결국 팔걸이 위 손놀림 경주로 기록됐군요.","스트레칭을 예선 경기로 바꾸셨군요. 매트가 수동 저항 부문에서 메달을 땄습니다.","마음속 날씨는 계속 소란스럽습니다. 평온의 맑은 틈은 동영상이 로딩될 때만 찾아오겠군요."],"wisdom":["나침반 없이 돌진한다고 개척자가 되는 건 아닙니다. 엉뚱한 곳에 아주 제시간에 도착할 뿐이죠.","무턱대고 돌진하는 게 아니라고요? 생각을 전투가 끝난 뒤에 정찰대로 보내는 것뿐이죠.","마지막 한마디는 트로피가 아니에요. 당신은 이미 받침대를 주문했지만요.","천천히 하라는 말은 당신 귀에 더 빨리 할 수 있다는 걸 증명하라는 뜻으로 들려요.","용기는 열쇠 같은 것입니다. 그런데 당신은 열린 문을 망치질하는 데 열쇠를 쓰기도 하네요.","당신의 용기 뒤에서 상식은 반사 조끼를 요구하고 있어요.","모든 장애물이 당신에게 시비를 거는 건 아니에요. 어떤 것은 그냥 가구입니다.","차례를 기다린다고 항복하는 건 아니에요. 당신의 백기는 아직 포장도 안 뜯겼지만요.","방향 없는 용맹은 엉뚱한 도시에 도착해 보낸 엽서와 같습니다.","남보다 앞서 나가는 것과 이야기가 시작되기도 전에 떠나는 것을 가끔 혼동하시는군요.","가장 대담한 지름길이 출발점으로 정확히 돌아올 수도 있습니다. 신발값 영수증과 함께요.","어디로 갈지 아는 건 장점입니다. 요란하게 세 번 출발한 뒤 알아내는 건 좀 더 개성적인 방법이죠."],"roast":["토스터가 반응이 느리다며 서면 경고를 받았습니다. 마지막 식빵 한 장으로 수습 기간을 주셨군요.","내비게이션이 다른 길을 제안했다고 선전포고를 했군요. 로터리는 방어 태세에 들어갔습니다.","혼자 한 보드게임의 판정에 이의를 제기하셨군요. 역시 당신으로 구성된 항소위원회가 재대결을 준비 중입니다.","커피머신이 늦어지면 적에게 하듯 말을 걸어요. 머신은 항의의 표시로 디카페인을 내놓습니다.","잘 안 열리는 문을 개인적인 모욕으로 받아들이죠. 그런데 당기세요라는 표지판이 불리한 증언을 합니다.","당신의 솔직함 뒤에서는 외교가 논쟁의 톨게이트에 갇혀 있어요.","빨간 신호등을 붙잡고 개인의 주도권에 관한 강연을 하셨군요. 신호는 연설 중간에 초록색으로 바뀌었습니다.","고양이에게 눈싸움을 신청하셨군요. 고양이가 하품하자 즉시 경기 규칙에 이의를 제기했습니다.","번호표 기계가 '기다려 주세요'라고 하자 번호들의 자유로운 이동권에 관한 발표를 준비하셨군요.","우연히 지은 표정을 두고 거울 속 자신과 말다툼을 하셨군요. 거울은 증언을 거부했습니다.","커피 머신을 공식 라이벌로 승격하셨군요. 기계는 한마디도 하지 않고 논쟁에서 이겼습니다.","도로가 막혔다고 내비게이션을 혼내셨군요. 기계음이 공사장에 직접 항의하시라고 안내했습니다."]},"roastMy":["양자리인 당신은 조급한 사람이 아닙니다. 스스로 약속을 잡는 긴급 상황 그 자체죠. 엘리베이터 버튼을 일곱 번 누르고 건물에 팀워크가 부족하다고 비난합니다. 문이 열리자 뛰어들어요. 겨우 한 층 올라갈 예정이었는데요.","당신은 아무도 경기하지 않을 때에도 이기는 걸 좋아해요. 계단 오르기에 시간을 재고 모르는 사람을 추월한 뒤 참가해 줘서 고맙다고 하죠. 그 사람은 장바구니를 들고 걷고 있었을 뿐이에요. 올림픽 위원회는 당신의 신청서를 반려했습니다.","당신의 솔직함은 도서관에서 울리는 북만큼 섬세해요. 작은 장식품이 어떠냐는 질문에 사회적 논쟁을 시작하죠. 결국 꽃병을 설득해 자리를 옮깁니다. 벽은 논쟁 소음으로 민원을 제기하려고 합니다.","당신은 생각하기 전에 달려들고 그걸 용기라고 부릅니다. 가구가 길을 막자 목소리를 높여 협상하죠. 가구는 꿈쩍도 하지 않아요. 당신은 판정 논란 속에 가구의 승리를 인정합니다.","기능이 있는 물건이라면 무엇과도 다툴 수 있어요. 내비게이션과 알람 시계, 커피머신이 적군 목록에 올라 있죠. 어느 쪽도 싸움을 수락하지 않았습니다. 토스터는 국제적인 휴전을 요청했어요.","당신의 열정은 전염성이 있지만 아무도 소풍을 대회로 바꿔 달라고 하지 않았어요. 팀을 나누고 점수를 만들고 돗자리를 가장 잘 펼친 사람에게 상을 줍니다. 친구들은 그냥 앉아서 먹기 시작하죠. 당신은 스포츠 정신 부족을 고발합니다.","당신은 기다림을 거의 예술적으로 싫어해요. 계산대 앞의 세 사람이 거대한 지정학적 장애물로 변하죠. 효율성에 관한 연설을 머릿속으로 준비합니다. 막상 차례가 오자 뭘 주문하려 했는지 잊어버려요.","당신은 이미 지휘자가 있는 곳에서도 지휘권을 잡고 싶어 해요. 누군가 나들이를 준비하면 동선을 다시 짜고 더 역동적인 버전을 발표하죠. 일행은 엉뚱한 장소에 일찍 도착합니다. 당신은 최단 시간 기록을 자랑해요.","당신의 분노는 순식간에 치솟고 더 빨리 사라집니다. 누군가의 말에 열렬히 항의하다가 2분 뒤 활짝 웃으며 과자를 권하죠. 상대는 아직도 무슨 일로 다퉜는지 찾고 있어요. 당신의 홍보팀은 회의록을 삭제했습니다.","당신은 반대 의견을 들으면 공식 도전장을 받은 듯 행동해요. 친구가 다른 영화를 좋아하자 영화의 미래가 걸린 듯 자기 취향을 변호합니다. 친구는 조용히 쉬려고 결국 동의하죠. 당신은 대화의 위대한 승리라고 발표합니다.","무조건 먼저 나서고 싶어서 상대방이 인사를 끝내기도 전에 대화를 시작합니다. 일정표에는 자기 존재조차 모르는 프로젝트가 가득하군요. 당신은 이를 추진력이라고 부릅니다. 사무실은 끝없는 시사회라고 부르죠.","저녁 모임에 오면서 분마다 번뜩이는 아이디어를 준비해 오셨군요. 친구들은 조용히 이야기하려 했습니다. 그런데 음악 고르기부터 개막식으로 바꾸셨네요. 직원은 몰래 심판진을 찾고 있습니다.","당신은 장애물을 개인적인 도전장처럼 여기는 데 탁월합니다. 닫힌 문은 결투 신청이고 설명서는 소문이며 우회로는 모욕이 되죠. 결국 올바른 길을 찾기는 합니다. 처음부터 표지판에 써 있던 그 길이요.","다정한 고백을 마치 다리 개통식 연설처럼 열정적으로 하시는군요. 마음은 진심이지만 벌써 기념사진으로 넘어갔습니다. 상대방은 아직 첫 문장을 기다리고 있어요. 다리는 착공도 안 했는데요.","당신에게 평온이란 전원 버튼 없는 기계만큼 수수께끼입니다. 잠깐 쉬었다가 가벼운 활동을 하고, 다음 휴식 일정을 짜는 계획까지 세웠군요. 이제 휴식일에 목표가 여덟 개나 됩니다. 빠진 건 '쉬기' 하나뿐이네요."]},"taurus":{"classic":{"career":["당신의 꾸준함은 프로젝트를 단단하게 만들어요. 하지만 상황이 바뀌면 방법을 다시 살펴볼 줄도 알아야 해요.","업무 습관을 흔드는 제안을 받으면 바로 거절하기보다 차분히 평가할 시간을 가져 보세요.","장기적인 과제에는 당신의 끈기가 잘 어울려요. 작은 진전이라도 주변에 정기적으로 알려 주세요.","안정성을 추구하는 마음이 선택에 영향을 줍니다. 새로운 가능성을 닫아 버리지만 않는다면 강점이 될 거예요.","팀 전체가 급해질 때 당신의 침착함은 도움이 돼요. 다만 신중함과 제자리걸음은 구분해 보세요.","꼼꼼하게 일하려는 마음은 훌륭해요. 세부 사항만 끝없이 손보기보다 충분히 완성된 결과를 내는 편이 나을 때도 있어요.","업무 방식이 바뀌면 편하게 적응하기 위해 무엇이 필요한지 솔직히 설명해 보세요.","검증된 해결책을 선호하는 당신에게 작은 실험 하나가 새로운 가능성을 열어 줄 수 있어요."],"love":["당신의 성실한 애정은 반복되는 작은 행동에서 드러나요. 소중한 사람의 뜻밖의 바람도 존중해 주세요.","누군가와 가까워지면 오래갈 관계를 만들고 싶어 해요. 솔직한 대화가 그 믿음을 키워 줍니다.","함께하는 습관이 사랑을 표현하는 언어가 될 수 있어요. 다만 의무로 만들지는 마세요.","소박한 시간을 즐기는 마음이 관계를 풍요롭게 해요. 가끔은 상대방에게 계획을 맡겨 보세요.","의견이 다를 때 굳은 입장을 지키기보다 방어하지 않고 들어 볼 여유가 필요해요.","안정감이 필요하다는 마음을 다정하게 표현할 수 있어요. 주변의 모든 것이 그대로여야 하는 건 아니니까요.","당신은 실질적인 배려로 마음을 많이 전해요. 느끼는 감정을 말로도 전해 보세요.","관계가 새로운 단계에 들어섰다면 예전 모습에만 매달리지 말고 한 걸음씩 적응해 보세요."],"wellbeing":["당신에게 편안함은 중요해요. 바깥세상과 단절되지 않는 아늑한 공간을 만들어 보세요.","하루가 바빠질수록 좋아하는 음식을 여유롭게 즐기는 순간이 중심을 되찾게 해 줄 수 있어요.","익숙한 산책길도 주변을 천천히 살펴보면 특별한 휴식이 될 수 있어요.","반복되는 일상은 안정감을 줍니다. 부담 없는 작은 변화도 가끔 들여보세요.","요청이 많을 때는 쉬는 시간을 침범하는 일에 거절할 권리도 있어요.","좋아하는 소파에서 화면이나 할 일 목록 없이 진짜 휴식을 누려 보세요.","부드러운 음악과 편안한 조명, 서두를 필요 없는 시간처럼 단순한 감각적 즐거움도 소중해요.","해야 할 일이 너무 많다면 속도를 늦추고 마음을 편하게 해 주는 활동으로 돌아가 보세요."],"wisdom":["끈기는 방향을 바꿀 줄 알 때 지혜가 됩니다.","편안함은 피난처일 때 소중하지 경계선이 되어서는 안 됩니다.","굳은 신념이 대화의 문까지 닫을 필요는 없어요.","안정감은 적응하는 능력 속에서도 자라납니다.","현재를 음미한다고 시간을 붙잡아야 하는 건 아닙니다.","스스로 선택한 변화는 이미 소중한 것들과 공존할 수 있습니다.","예상 밖의 일이 일상의 따뜻함을 더 풍요롭게 할 수도 있습니다.","천천히 걸어도 계속 걷는다면 멀리 갈 수 있습니다."],"roast":["습관에 대한 애착이 지나치면 간단한 대안조차 복잡하게 느껴져 변화를 거부하게 돼요.","한 번 결심하면 타당한 근거조차 당신의 생각을 바꾸기 어려워요.","편안함만 추구하면 더는 맞지 않는 상황에 머물게 될 수 있어요.","어떤 시도든 확실한 보장부터 찾다 보면 좋아할 만한 새로운 것을 발견하지 못할 수 있어요.","좋은 것을 즐기는 데 집중하다 보면 때때로 자발적인 즐거움을 놓쳐요.","겉으로는 차분해 보여도 내면의 단호함이 다른 사람의 의견이 들어올 자리를 좁힐 때가 있어요.","모든 일을 예측 가능하게 만들려는 욕구는 즉흥적인 사람들을 지치게 할 수 있어요.","더 쉬운 방법이 나왔는데도 늘 하던 방식을 다듬는 편을 택하는군요."]},"funny":{"career":["당신의 책상에는 세 가지 우선순위가 있어요. 효율성, 편안한 의자, 그리고 내 컵은 절대 움직이지 말 것.","누군가 새 소프트웨어를 쓰자고 하면 기존 프로그램이 무슨 죄를 지었느냐고 묻습니다.","점심시간 회의는 당신의 업무 질서를 떠받치는 기둥에 대한 공격입니다.","안정감이 중요하죠. 가장 좋아하는 파일철은 너무 오래 함께해서 기념패를 달아 줘야 할 지경이에요.","새로운 방식이 나오면 시연과 2주간의 숙고, 그리고 스테이플러의 의견까지 요구합니다.","이 일정표는 쉽게 바뀌지 않아요. 당신이 승인했으니 거의 돌에 새긴 수준이거든요.","인내심이 필요한 업무엔 당신을 뽑아요. 하지만 자리를 옮겨야 한다면 채용부터 다시 시작해야 합니다.","제대로 일하는 걸 좋아하는 모습이 당신답죠. 다만 다른 방식으로도 잘할 수 있다는 사실을 믿기 어려울 뿐이에요.","소프트웨어 업데이트가 떴습니다. 당신은 먼저 이전 화면을 복사해 품위 있는 은퇴식을 열어 주려 하시네요.","점심시간을 너무 정확히 지켜서 구내식당도 빈 의자에 맞춰 시계를 조정합니다.","당신의 직장 목표는 안정적인 자리, 믿음직한 팀, 그리고 파일 이름에 생기는 놀라움 제로입니다.","동료가 '빠른 혁신'을 말합니다. 당신은 정중하게 답하죠. '물론이죠. 15년간 정상 작동했다는 검증부터 마치고요.'"],"love":["당신의 주요 사랑 표현은 디저트를 나눠 주는 거예요. 단, 나눈다는 말이 마지막 한 입을 가져가도 된다는 뜻은 아니죠.","당신을 유혹하는 데 기적 같은 약속은 필요 없습니다. 목요일엔 파스타, 토요일엔 나눠 먹는 디저트를 좋아한다는 사실만 기억하면 됩니다.","완벽한 저녁은 맛있는 식사로 시작해 아무도 다시 나가자고 하지 않는 것으로 끝납니다.","당신에게 낭만이란 상대방이 가장 좋아하는 피자 토핑을 정확히 기억하는 일이에요.","계획이 바뀌어도 미소를 유지합니다. 원래 가려던 식당과 작별할 시간만 조금 필요할 뿐이에요.","둘만의 작은 습관이 너무 좋아서 무기한 정기 일정으로 등록하고 싶어 해요.","좋아하는 사람의 최애 요리를 안다는 작은 배려에서 당신의 다정함이 드러납니다. 다만 민감한 문제가 하나 남았군요. 한 사람당 양은 얼마인가요?","즉흥적으로 하자는 말에 다정하게 대답해요. 물론이죠, 그런데 어느 일정표를 따를까요?","저녁 식사 때 음악을 고르는 건 흔쾌히 맡깁니다. 하지만 마지막 감자튀김 앞에서는 협상 방식이 한층 체계적으로 바뀌죠.","사랑의 의식을 워낙 잘 지켜서 금요일 예약을 받는 식당이 친구 몇 명보다 당신을 더 잘 압니다.","페이스트리 하나를 나눠 먹자고 했다가 동등한 조각을 구하는 기하학 속성 강의가 시작됐군요.","애정을 표현하려고 상대방이 가장 좋아하는 요리를 준비했습니다. 혹시 몰라 샘플용 한 접시까지 챙기셨군요."],"wellbeing":["당신이 앉는 소파 자리는 습관에 너무 잘 맞아서 어떤 옷보다도 편안해요.","산책 코스에는 자연스럽게 빵집과 앉아 쉴 수 있는 장소가 포함됩니다.","온도와 조명, 담요의 촉감까지 승인되어야 비로소 완전한 휴식이에요.","일요일의 거대한 목표는 리모컨을 잃지 않으면서 물건을 최대한 적게 옮기는 것입니다.","운동하러 가자는 제안에는 벤치에 앉아 경치를 감상하는 진지한 대안을 내놓아요.","잘못 놓인 쿠션 하나가 분위기를 망쳐요. 건축가처럼 진지하게 원상복구합니다.","바람 쐬는 건 좋지만 돌아왔을 때 앉을 자리가 있는지부터 확인해야 해요.","누가 낮잠을 방해하면 재판 중 방해받은 판사처럼 엄숙하게 한쪽 눈을 뜹니다.","당신의 소파에는 완벽하게 조정된 착륙 구역이 있습니다. 손님은 위험을 감수하고 그곳을 지나야 하죠.","아끼는 담요를 세탁기에 넣었습니다. 오늘 하루는 '안락함 저하' 비상 절차로 운영되겠군요.","예정에 없던 낮잠은 행복합니다. 누가 깨우기라도 하면 행정적 중대 사안이 되죠.","저녁마다 램프 하나, 찻잔 하나, 쿠션 세 개로 분위기를 완성합니다. 안락의자는 인테리어 담당자의 최종 승인을 기다리는군요."],"wisdom":["오래갈 가치가 있는 일은 도착하기 위해 서두를 필요가 없습니다.","좋은 계획이란 앉을 자리를 마련해 주는 계획입니다.","끈기는 고귀해요. 8년째 다른 식당을 거부하는 일은 조금 덜 고귀하지만요.","행복은 담요 한 장에 있을 수 있어요. 아무도 빌려 가지 않는다면 더 좋죠.","끈기는 다리를 놓지만, 막 완공한 다리를 건너길 거부한다면 아무 소용이 없습니다.","시간은 좋은 생각을 익힙니다. 가끔 창문을 열어 바람을 쐬게 할 수도 있겠죠.","음식이 식어 가면 당신의 인내심은 갑자기 왕관을 잃습니다.","편안하다고 해서 모든 가구를 영원히 보관할 필요는 없어요.","인내심은 수확을 기다릴 줄 알지만 대신 씨앗을 심어 주지는 않습니다.","오래갈 좋은 아이디어에는 뿌리가 필요하지, 뿌리마다 울타리를 칠 필요는 없습니다.","올바른 방향으로 천천히 걷는 한 걸음이 서랍 속 완벽한 계획보다 낫습니다.","규칙적인 삶은 강점입니다. 달력은 가끔 빈칸 하나도 남겨 주면 고마워할 거예요."],"roast":["식당 주인이 세 번 바뀌었는데도 충성심으로 옛 메뉴를 간직하고 있어요.","앱에서 주요 버튼 위치를 바꾸면 정식 항의 편지를 쓸까 심각하게 고민합니다.","당신의 전용 의자는 손님들이 앉기 전에 허락부터 구해야 할 정도로 유명해요.","마지막 케이크 한 조각은 외교적으로 민감한 사안입니다. 투표를 열고 거부권은 직접 챙기죠.","새 베개가 오면 엄격한 시험을 진행해요. 오래된 베개는 자신 있게 결과를 기다립니다.","그 편한 옷은 일요일을 너무 많이 함께 보내서 사실상 가구의 일부입니다.","아침 일과를 설명하는 말을 들으면 박물관에서 보호하는 전통을 소개받는 기분이에요.","누군가 지름길을 알려 줘도 늘 잘 다니던 길을 왜 버리냐고 묻습니다.","새 방식을 권하는 초대 세 번을 거절하셨군요. 네 번째에는 5년 뒤에 다시 논의하자고 제안하셨습니다.","마음속 토론에서는 모든 주장이 변화 반대에 투표했습니다. 찬성하는 주장들은 초대장을 받지 못했죠.","습관과 영구 계약을 체결하셨군요. 자동 갱신 조항은 있지만 해지 조항은 없습니다.","누군가 당신이 틀렸다는 걸 증명했습니다. 당신은 웃으며 '흥미롭지만 부정확한 관점이네요'라고 답하셨군요."]},"piquant":{"career":["새 소프트웨어에 유용한 기능이 세 개 생겼습니다. 당신은 옛 '인쇄' 버튼을 살리기 위해 50쪽짜리 연구 보고서를 작성했군요.","자기 방식을 박물관 학예사처럼 열렬히 지킵니다. 소프트웨어는 버전이 바뀌었는데 당신은 그대로예요.","사무실 자리 이동을 조약 위반으로 여깁니다. 의자는 대사관을 열었어요.","회의에서 새 방법을 제안하면 증빙 서류 세 장과 구버전 복귀 보증을 요구합니다.","잘 굴러가는 절차는 당신에게 신성합니다. 결함마저 문화유산 보호 대상이에요.","당신의 직장인다운 침착함 뒤에는 내 습관에 손대지 말라는 보이지 않는 표지판이 있죠. 신입사원들은 다른 출구로 나갔습니다.","지름길은 못 미더워요. 15년의 전통을 지킬 수 있는데 굳이 10분을 절약할 이유가 있나요?","이 책상은 과자 한 봉지까지 국경이 분명한 안정된 영토예요. 당신은 과자 상자 주위에 경계선을 그었습니다.","새 소프트웨어가 배포됐습니다. 당신은 옛 단축키를 부서의 무형문화유산으로 지정하셨군요.","점심시간을 시간표 차단벽으로 지켜 놓았습니다. 긴급 전화조차 내일이라는 개념으로 연결되네요.","당신의 경력은 엄격히 승인된 속도로 전진합니다. 승진 기회들이 모든 부록을 읽을 시간은 충분하겠어요.","부서에서 조직 개편을 발표했습니다. 당신은 현 사무실의 장점을 다룬 보고서를 제출하셨군요. 건물 준공 연도에 작성된 자료입니다."],"love":["당신의 낭만은 같은 식당에 예약한 저녁 횟수로 측정됩니다. 식당은 메뉴판에 두 사람의 이니셜을 새길까 고민 중이군요.","둘만의 습관을 문화재처럼 지켜요. 저녁 식사를 한 시간 옮기려면 국민투표를 해야 합니다.","나눔이 아름다운 가치라는 데 동의하죠. 마지막 한 입이 남을 때까지는요. 그 순간 재산권을 발견합니다.","새로운 장소에 가자는 제안을 받으면 가는 내내 단골 식당의 장점을 설명합니다.","깜짝 데이트를 준비했습니다. 같은 자리, 같은 메뉴, 같은 디저트네요. 놀라움은 냅킨 색깔 하나뿐입니다.","당신의 다정함은 놀랍도록 한결같습니다. 다만 마지막 한 입은 비밀 조약으로 보호받고 있군요.","다정한 말은 좋지만 마지막 디저트 조각을 고르는 중에는 삼가 주세요.","연인의 작은 습관에 늘 충실하시군요. 금요일의 관례를 아예 반복되는 역사적 기념일로 등록해 두셨네요.","삶과 일정, 습관은 기꺼이 나누지만 당신의 접시는 독립국 지위를 유지합니다.","가상 설문 결과, 당신의 낭만적인 저녁 98%가 같은 메뉴로 진행됩니다. 나머지 2%는 재료가 품절된 날입니다.","좋아하는 식당을 끝까지 고수하는 게 사랑의 증거라고 생각하시네요. 상대방은 신메뉴를 한번 먹어 보고 싶었을 뿐인데요.","둘이 떠나는 모험이란 식당은 그대로 두고 음식 나오는 순서만 바꾸는 것이군요."],"wellbeing":["당신의 휴식에는 주소와 담요, 지정석이 있어요. 가구들은 이미 거주지 등록을 마쳤습니다.","낮잠을 국제 정상회담처럼 지켜요. 방해하려면 서면 신청서 세 부가 필요합니다.","소파는 당신을 대신해 회의에 참석할 정도로 습관을 잘 알아요. 다만 거실 밖으로 나가는 건 거부합니다.","누가 즉흥적인 산책을 제안하면 신발을 원래 자리에 둘 수 있는지부터 묻습니다.","따뜻한 음료는 큰 위안이 되죠. 하지만 늘 쓰던 컵이 점령당했다면 다른 컵은 국경을 넘지 못해요.","당신의 안락함을 향한 사랑 뒤에는 담요의 최적 온도를 지키는 군대가 있어요. 온도조절기는 조용히 복종합니다.","평화로운 일요일은 특기죠. 아무도 깜짝 일정을 넣지 않는다는 조건으로요. 달력은 봉인됐습니다.","유연성을 연습한다며 쿠션을 바꿔 보려 해요. 위원회는 아직 제안을 심의 중입니다.","담요가 당신의 저녁시간 소유권을 취득했습니다. 다른 직물들은 신청서를 내도 희망이 없겠네요.","공식 안내입니다. 낮잠은 보호받는 행사입니다. 모든 방해 신고는 두 번째 낮잠 후에 심사됩니다.","안락의자, 주전자, 소파를 잇는 휴식 코스를 만들었습니다. 너무 짧아서 상상 속 지하철 노선까지 생겼군요.","비상용 쿠션에도 별도의 비상용 쿠션이 있습니다. 예기치 못한 상황은 거실에서 퇴장했네요."],"wisdom":["한결같음은 미덕입니다. 그러나 지난 결정을 모두 국가 기념물로 만드는 건 그다지 실용적이지 않죠.","당신은 의견을 바꾸지 않아요. 다른 사람들이 지칠 때까지 기다리도록 허락할 뿐이죠.","끈기는 산도 옮깁니다. 다만 산이 이미 다른 곳으로 옮겨졌다는 사실을 받아들여야 할 때도 있습니다.","세상이 움직이면 당신은 먼저 안락의자에 브레이크가 있는지 확인해요.","습관은 자연법칙이 아니에요. 그런데 당신은 이미 민법전을 써 놨군요.","당신의 평온함 뒤에는 마지막 타르트 조각을 지키는 방위위원회가 있습니다.","시간은 깊은 노력을 보상하지만, 끝까지 모든 조건을 똑같이 유지하겠다고 약속한 적은 없습니다.","앞으로 나아간다고 슬리퍼를 배신하는 건 아니에요. 그래도 공증부터 요구하겠죠.","끈기는 멋지지만 세상이 완벽하게 제자리로 돌아오길 기다리는 끈기는 좀 다릅니다.","단단하다고 해서 첫 결정을 기리는 기념상으로 변할 필요는 없습니다.","오래가는 것에는 관심이 필요하지, 기념일마다 개막식을 열 필요는 없습니다.","일관성을 향한 애정은 훌륭합니다. 하지만 미래는 과거를 그대로 재현하겠다고 서명한 적이 없어요."],"roast":["새 아이디어를 제시한 사람이 첫마디를 끝내기도 전에 거절하셨군요. 제안은 첫 단어 그대로 돌아갔습니다.","당신의 변화 거부는 꾸준함의 극치예요. 꿀병의 새 라벨 하나가 국가 비상사태가 됩니다.","마지막 치즈 조각은 음식이 아니에요. 삼엄하게 감시되는 전략 자산입니다.","공사 구간을 피해 다른 길로 가라는 제안에 익숙한 길을 택하셨군요. 적어도 그 공사는 낯설지 않으니까요.","새로운 제안이 당신의 방탄문 같은 눈빛에 부딪칩니다. 호기심마저 돌아서요.","전설적인 침착함 뒤에는 리모컨의 정확한 자리를 지키는 경비원이 있습니다.","즐겨 하시는 말은 '전 항상 이렇게 했어요'입니다. 새로운 방식이 증빙서류를 내밀었지만 입장은 거절됐습니다.","어떤 주장에도 입장을 바꾸지 않겠다고 선언하셨군요. 그런데 의자는 이미 1센티미터 옮겨져 있었습니다.","새로운 사실이 제시되자 이미 결론이 내려져 초대받지 못했다고 통보하셨군요.","토론이 끝나기도 전에 의견을 대리석에 새겨 놓으셨군요. 조각가는 이제 막 치수를 재러 왔는데요.","낡은 습관을 너무 열심히 지켜서 박물관마저 인수를 거절했습니다. 옮기기가 너무 어렵다네요.","당신의 생각을 바꾸는 사용 설명서입니다. 1단계, 기다리기. 2단계, 1단계 다시 읽기. 3단계는 국가 기밀입니다."]},"roastMy":["황소자리인 당신의 소파는 더 이상 가구가 아닙니다. 하나의 자치 행정구역이죠. 자리와 담요, 손님 출입 절차가 따로 있어요. 누군가 실수로 앉자 쿠션 위원회가 즉시 퇴거 명령을 내립니다.","당신의 고집은 문에 자물쇠를 하나 더 단 모습과 같아요. 실용적인 제안을 받으면 증거와 추천서, 3계절의 시험 기간을 요구하죠. 결국 아이디어는 물러납니다. 당신은 기존 방식이 다시 옳았다고 선언해요.","맛있는 걸 좋아하죠. 특히 마지막 한 조각을 아무도 탐내지 않을 때요. 태연한 눈으로 접시를 감시하다가 전략적으로 위치를 바꿉니다. 친구가 나눠 먹자고 하자 국제 협력의 한계를 새롭게 깨닫습니다.","당신은 새로운 것에도 열려 있다고 주장해요. 식당을 바꾸는 데도 동의하죠. 같은 자리와 같은 메뉴, 같은 분위기만 있다면요. 간판이 다르다는 것만으로도 대단한 모험입니다. 접시는 용기 훈장을 요구해요.","당신의 안락함에는 헌법이 있고 최고 수호자는 바로 당신입니다. 슬리퍼는 소파 옆에 대기하고 담요는 규정대로 접혀 있으며 차는 정시에 나와요. 손님이 창문을 엽니다. 당신은 직물 비상대책회의를 소집합니다.","평범한 습관도 명변호사처럼 변호할 수 있어요. 리모컨을 몇 센티미터 옮기려는 사람에게 그 자리의 역사를 설명합니다. 10분 뒤 상대는 포기해요. 리모컨은 당신의 헌신에 감사를 표합니다.","당신은 느리게 움직이는 게 아닙니다. 공식적인 안락함의 속도를 존중할 뿐이죠. 모두 현관에서 기다리는데 당신은 여행용 쿠션을 찾고 있어요. 그냥 산책이라는 말을 듣자 앉을 자리가 있느냐고 묻습니다.","당신의 완벽한 일요일에는 어떤 깜짝 계획도 들어올 수 없어요. 집으로 배달되는 놀라움이라면 예외겠죠. 즉흥적인 활동을 제안받으면 담요를 정치 고문처럼 바라봅니다. 담요가 반대해요. 당신은 가족 만장일치 결정이라고 발표합니다.","당신은 누군가 자기 몫을 탐낼 때까지는 너그러운 사람입니다. 조언과 담요, 맛집 정보도 기꺼이 나눠 줘요. 그러다 손 하나가 과자에 다가옵니다. 우호 조약은 무기한 정지됩니다.","당신의 안정 사랑은 인테리어와 안 어울리는 낡은 의자도 보존하게 만들어요. 역사와 영혼, 거주권이 있다고 주장하죠. 새 의자는 문밖에서 기다립니다. 오래된 의자는 방금 거실 장관으로 임명됐어요.","당신에게 새로운 것은 예약 없이 찾아온 방문객 같습니다. 최신 소프트웨어가 장점을 보여 주는데 옛 메뉴가 얼마나 좋은지 한 시간 동안 설명하시죠. 시연이 끝났습니다. 마우스는 아직 구버전에서 일하고 있습니다.","규칙성의 가치를 누구보다 잘 아십니다. 당신의 습관에는 장기근속 배지가 달려 있죠. 점심은 늘 같은 자리와 같은 시간에 같은 순서로 나옵니다. 한 번 식당에서 테이블 배치를 바꿨습니다. 아직도 대개혁으로 기억하시는군요.","시간과 애정은 넉넉히 나누지만 누군가 포크를 들고 디저트에 다가오면 달라지십니다. 갑자기 국경 전문가로 변신하죠. 케이크는 행정구역으로 나뉩니다. 상대방의 숟가락은 입국 거부를 받았군요.","편안함을 누리는 법을 잘 아십니다. 은은한 조명, 고른 책, 완벽한 의자까지 갖춰 놓았죠. 물건 하나가 움직이면 적응 기간이 필요합니다. 손님이 친절하게 가구를 다시 놓았다가 가구들이 평화협정으로 보호받는다는 사실을 알게 됩니다.","당신의 조용한 힘과 목표를 향한 끈기는 칭찬받을 만합니다. 문제는 다른 길이 더 낫다는 표지판이 나타날 때죠. 당신은 표지판을 꼼꼼히 살피고도 원래 길을 고집합니다. 당신은 이를 한결같음이라고 부르지만, 지도는 아주 멋진 우회라고 부르네요."]},"gemini":{"classic":{"career":["당신의 호기심은 남들이 따로 보는 아이디어를 연결해 줍니다. 유망한 생각을 깊이 발전시킬 시간도 마련해 보세요.","여러 프로젝트가 한꺼번에 나타나면 열정이 분산될 수 있어요. 새 일을 맡기 전에 우선순위를 정해 보세요.","업무 대화가 창의력을 자극할 수 있어요. 이후 진행을 위해 분명한 결정도 남겨 두세요.","다양한 업무가 당신의 사고를 활발하게 해요. 단순한 틀이 시작한 일을 마치는 데 도움이 될 거예요.","복잡한 문제를 보면 여러 각도를 탐색하죠. 그다음 한 가지 해법을 선택해 충분히 시도해 보세요.","설명하는 재능만큼 동료들의 질문에도 세심하게 귀를 기울이면 더 빛나요.","새 정보가 처음 생각과 다르다면 유연하게 바꿀 수 있어요. 왜 생각이 달라졌는지도 전해 주세요.","인맥을 넓히면 시야가 커져요. 모든 새 만남을 좇기보다 몇몇 관계를 깊게 가꿔 보세요."],"love":["당신은 대화를 통해 친밀감을 키워요. 모든 침묵을 말로 채우지 않고 받아들이는 여유도 가져 보세요.","누군가 궁금해지면 질문이 쏟아져요. 대화가 면접이 아니라 서로 나누는 시간이 되게 해 보세요.","늘 새로움이 있는 관계가 당신을 설레게 해요. 변함없는 마음도 그만큼 소중할 수 있어요.","가벼운 유머는 가까워지는 데 도움이 돼요. 상대가 진지한 이야기를 원하는 순간도 알아차려 주세요.","감정이 엇갈릴 때는 잠시 물러서서 일시적인 호기심과 오래가는 바람을 구분해 보세요.","새로움을 좋아하는 마음은 관계에 생기를 줍니다. 이미 함께 만든 작은 습관도 잊지 마세요.","생각이 바뀌었다면 상대가 짐작하게 두지 말고 그 과정을 간단히 설명해 주세요.","진심을 말하는 일은 자연스럽죠. 답변을 미리 준비하지 않고 듣는 경험이 또 다른 친밀함을 줄 거예요."],"wellbeing":["늘 움직이는 생각에도 고요한 시간이 필요해요. 정한 휴식 시간에는 자극을 조금 줄여 보세요.","아이디어가 너무 많아질 때 몇 줄 적어 보면 생각의 실마리를 찾는 데 도움이 될 수 있어요.","휴대전화 없이 짧게 걷는 동안에도 당신의 호기심은 충분히 즐거울 수 있어요.","관심사가 다양해 활력이 넘쳐요. 한 가지 활동만 천천히 즐기는 시간도 마련해 보세요.","대화로 가득한 하루를 보냈다면 자기 속도에 맞춰 잠시 고요함을 찾아보세요.","끊임없이 새로운 것을 찾고 싶어도 조용한 저녁 동안은 기다려도 괜찮아요. 모든 것을 지금 알아야 할 필요는 없어요.","잠들기 전까지 생각이 이어진다면 편안한 저녁 습관을 만들어 보세요.","알림에서 벗어나 잠시 쉬면 진정한 관심과 단순한 산만함을 구별하기 쉬워질 거예요."],"wisdom":["호기심은 한곳에 머무를 때 더욱 깊어집니다.","서로 반대되는 생각도 선택을 비출 수는 있지만 대신할 수는 없습니다.","말은 상대가 답할 자리를 남길 때 사람을 가깝게 합니다.","모든 길을 탐색한다고 동시에 다 걸어야 하는 건 아닙니다.","자유로운 정신은 스스로 선택한 일을 마칠 줄도 압니다.","생각을 바꾸는 건 강점이 될 수 있어요. 이유를 설명할 수 있다면요.","새로움은 문을 열고 집중은 그 안에 머무르게 합니다.","끝까지 듣는 일은 가장 아름다운 호기심일 수 있습니다."],"roast":["호기심이 너무 멀리 뻗으면 정작 중요한 프로젝트는 결론을 기다리게 돼요.","질문을 하나 던질 때 이미 세 가지 답을 준비해 놓고 상대의 대답은 놓치곤 해요.","관점을 쉽게 바꾸다 보니 주변 사람들은 당신의 진짜 입장이 무엇인지 헷갈릴 수 있어요.","새로운 것만 찾다 보면 이제 막 흥미로워지는 일을 너무 빨리 떠날 수 있어요.","침묵 앞에서는 눈빛 하나면 충분한 자리에 말을 더하는 경향이 있어요.","모든 것을 설명하려는 습관은 조용한 동행을 좋아하는 사람을 지치게 할 수도 있어요.","선택지가 여러 개라고 결정을 미뤄도 그 선택들이 더 좋아지는 것은 아니에요.","수많은 대화를 여는 건 자연스럽지만 한 대화를 끝까지 이어가는 데는 노력이 필요해요."]},"funny":{"career":["업무용 브라우저에 탭 열일곱 개가 열려 있어요. 전부 왜 열었는지 안다고 주장하지만 음악이 나오는 탭만은 못 찾습니다.","회의록을 부탁받으면 조연과 반전까지 등장하는 흥미진진한 연대기를 작성해요.","새 앱을 발견하면 30분간 푹 빠집니다. 그러고는 똑같은 기능을 약속하는 다른 앱을 발견하죠.","커피 시간은 사실 사무실 소식 수집 시간이죠. 커피는 식어 가지만 정보망은 정상 가동 중입니다.","읽지 않은 메일이 463개입니다. 긴급, 흥미로움, '곧 돌아올게요'라는 세 부류로 나눠 두셨군요.","보고서는 순조롭게 진행되다가 동료가 새 앱을 소개하는 순간 멈춥니다. '잠깐 비교만'이라는 폴더를 여셨군요.","업무 대화 다섯 개를 동시에 관리합니다. 정작 오늘 아침부터 B 회의실에서 기다리는 사람만 잊으셨네요.","여러 일을 동시에 하는 게 재미있어요. 열다섯 가지 일 아래 깔린 첫 번째 일을 마치는 것이 진짜 보물찾기입니다.","받은편지함에 새 메일 100개가 도착했습니다. 초콜릿 한 상자를 선물받은 것처럼 '완벽해요!'라고 하시네요.","화상 회의 세 개에 동시에 참석 중입니다. 그중 한 회의에서 당신의 마이크가 엉뚱한 팀을 축하해 버렸습니다.","프로젝트를 정리하려고 새 폴더를 만들었습니다. 이름은 '진짜 최종본 최종본 4'입니다.","하던 일을 처리하는데 메시지가 오고 동료가 전화를 합니다. 하루가 끝나자 네 번째 업무의 회의록만 훌륭하게 진척됐군요."],"love":["유혹하는 메시지를 보내고 첫 번째 메시지를 설명하는 두 번째 메시지를 보냅니다. 세 번째는 첫 번째가 로맨틱했다는 확인용이군요.","어디서 먹을지 물으면 식당 세 곳을 추천했다가 마음을 바꾸고 그사이 도자기 수업까지 찾아냅니다.","다정한 대화도 화산 이야기에서 이웃 이야기, 이불 접는 최선의 방법으로 이어질 수 있어요.","깜짝 이벤트를 너무 좋아해서 직접 계획을 바꿔 놓고는 놀란 척하기도 해요.","보고 싶다는 메시지에 답하려다가 오늘 있었던 일 여섯 가지를 순서대로 이야기합니다.","모든 걸 이야기하는 모습이 사랑스럽죠. 다만 상대는 이제 두 쉼표 사이에 나 먼저 잘게요를 끼워 넣는 기술을 익혔습니다.","휴대전화 없는 저녁을 약속하자마자 흥미진진한 기사를 발견해요. 물론 이번 한 번만은 예외죠.","같은 저녁에 두 초대를 모두 수락하셨군요. 해결책은 두 장소의 정중앙을 지나는 산책 코스를 제안하는 것이었습니다.","'만날까요?'라는 질문에 답 네 개를 준비했습니다. 결국 가장 긴 답을 보내고 시간대별 색상 선택지까지 덧붙이셨네요.","문자로 유혹하는 솜씨는 뛰어납니다. 다만 대화에 왜 목차가 생겼는지 설명해야 할 뿐이죠.","데이트를 제안받자마자 카페 후보 세 곳을 찾았습니다. 문제는 세 곳이 모두 다른 동네에 있다는 거군요.","연애 일정을 노래 바꾸듯 바꾸시네요. 상대방은 곡 사이에 잠깐 쉬는 시간이라도 달라고 합니다."],"wellbeing":["눈을 감고 쉬려는 순간 머릿속에 새 창이 열립니다.","머리를 비우려고 산책에 나갔다가 아이디어 열두 개와 들을 팟캐스트 제목을 가지고 돌아와요.","침묵하는 시간도 흥미롭다고 생각하지만 시작하기 전에 모임 사람들과 장점을 토론하고 싶어 해요.","휴대전화를 내려놓으면 휴식이 시작돼요. 다른 데서 무슨 일이 일어나는지 궁금해지는 순간 끝나지만요.","책더미를 보면 네 권을 동시에 읽기 시작합니다. 작가 모두를 존중하는 당신만의 방법이죠.","쉬려고 팟캐스트를 틀어 놓고 재생 속도를 올리셨군요. 이제 목소리마저 당신 생각만큼 급합니다.","아무 생각 없이 호흡하는 건 쉬워 보여요. 당신의 머릿속은 이미 그렇지 않다는 발표를 준비합니다.","평화로운 저녁을 보낸다면 분 단위 일정을 공유할 단체 채팅방만은 만들지 마세요.","아무것도 하지 않고 풍경을 바라보려 했습니다. 잠시 후 구름의 생성 과정을 다룬 다큐멘터리를 찾고 계시네요.","조용한 산책도 좋습니다. 물론 팟캐스트 두 개와 돌아와서 들려줄 이야기 목록이 함께라면요.","지루함을 피하려고 차분한 취미 하나를 배우기로 했습니다. 여섯 개를 발견해 여섯 개 모두 시작하셨군요.","빗소리를 들으며 쉬기로 했습니다. 즉시 녹음 파일 일곱 개를 비교해 가장 좋은 비를 고르기 시작했군요."],"wisdom":["당신의 머릿속에는 천 갈래 길이 있지만 완료 버튼은 하나뿐이에요.","한 문장에서 상반된 의견 두 개를 말하면 이미 원탁회의입니다.","침묵에 굳이 자막을 달아 줄 필요는 없어요.","새 아이디어를 들이기 전에 옛 아이디어부터 상자 밖으로 꺼내 보세요.","호기심은 새 길을 열지만, 애초에 왜 집에서 나왔는지 잊게 할 수도 있습니다.","마음을 바꿔도 괜찮아요. 세상에 알려 주는 건 여전히 예의죠.","자세히 안다고 전부 다 말해야 하는 건 아닙니다.","경청이란 상대의 생각이 문장을 마치도록 기다린 뒤 세 가지 다른 생각을 건네는 것입니다.","짧은 대답도 완전할 수 있습니다. 그 대답의 조상 이야기까지 안다고 해서 모두 말할 필요는 없어요.","역설을 이해하려면 즉시 쌍둥이 역설을 하나 더 만들어 붙이지 않아도 됩니다.","질문하는 건 괜찮습니다. 하지만 새 질문 여덟 개를 던지기 전에 첫 답변을 기다리면 더 좋겠죠.","세상에는 이야기할 주제가 넘칩니다. 다만 문장이 마침표에 도착하면 세상이 고마워할 거예요."],"roast":["동네에서 당신이 아는 소문이 너무 많아서 주민들이 주간 뉴스레터 발행을 부탁할 지경이에요.","짧게 말할게요라는 말을 들으면 친구들은 휴대전화 충전기를 찾기 시작합니다.","읽기 목록에는 왜 저장했는지 잊었는데도 제목만 여전히 흥미로운 기사가 가득해요.","당신이 할 말 없다는 문장은 건너뛸 수 없는 광고보다 짧게 지속됩니다.","영화를 고를 때 코미디를 지지하다가 다큐멘터리를 추천하고 결국 드라마를 보자고 하죠.","2분짜리 음성 메시지에도 서론과 곁가지 이야기, 다음 메시지를 예고하는 결론이 들어갑니다.","모임이 끝나자마자 누군가에게 전하려고 최고의 대화들을 벌써 새롭게 구성하고 있어요.","마지막 말을 할 기회를 주면 완전히 새로운 화제를 시작하는 데 사용합니다.","비밀을 듣고 지키겠다고 약속했습니다. 그리고 저녁 내내 '말할 수 없는 그 이야기'에 대해 떠드셨군요.","'소문을 퍼뜨릴 생각은 없어요'라고 말한 뒤 관련 동네 지도를 상세히 설명하셨네요.","당신식 짧은 이야기는 본장면, 배경, 역사적 맥락, 그 맥락의 뒷이야기까지 포함합니다.","같은 모험을 두 개의 반대 결말로 이야기하셨군요. 청중은 즐거워하지만 등장인물들은 대본을 확인하고 싶어 합니다."]},"piquant":{"career":["당신의 수다는 팀 회의를 연속극으로 바꿨습니다. 회의는 지난 시즌 줄거리 요약을 요청해요.","한 회의에서 서로 모순되는 전략 세 개를 발표하셨군요. '결론' 슬라이드가 방금 사직서를 냈습니다.","메일 한 통에 답하려고 초안을 열두 개 쓰셨군요. 원래 메시지는 그냥 '확인'이었습니다.","동료가 두 마디로 말해 달라고 하자 괄호 안의 말은 글자 수에 포함되느냐고 묻습니다. 동료는 이미 노트북을 닫았어요.","새 아이디어는 다음 아이디어가 나타날 때까지만 사랑받아요. 버려진 프로젝트들이 행정 지원 모임을 결성했습니다.","업무 화면이 국제 환승센터 같습니다. 탭마다 갈아탈 길은 안내하지만 최종 목적지는 아무도 모릅니다.","6분 동안 동료 여섯 명에게 메일 여섯 개를 전달했습니다. 일곱 번째 동료는 내용을 이해하는 책임자로 임명됐군요.","즉흥 발표 능력은 놀랍습니다. 발표 도중 결론을 바꿔 버리니까요. 슬라이드는 따라가기를 거부했어요.","속보입니다. 메일함에 미발송 초안이 너무 많아 아예 보내지 않은 메일 전용 답장 주소가 생겼습니다.","서로 다른 창 여섯 개에 업무 여섯 개를 배정했습니다. 그런데 닫힌 창은 가장 중요한 파일 하나뿐이군요.","화상 회의 안에서 대화가 네 갈래로 진행됩니다. 안건표는 분실물 센터로 이송됐습니다.","가상의 업무 보고입니다. 메시지 27개, 재촉 14번, 새 아이디어 9개. 핵심 업무 진행률은 제목 글자색 하나만 예쁘게 바뀌었군요."],"love":["당신의 매력은 너무 빠르게 말해서 침묵이 자기소개할 틈도 없어요. 미소 하나에도 음성 해설이 붙습니다.","당신의 매력은 데이트 도중 갑자기 방향을 바꿉니다. 두 사람의 예약에 식당 후보는 세 곳, 결정은 하나도 없군요.","첫 문자는 다정했습니다. 그다음 다섯 개에는 다른 선택지, 괄호 설명, 이모지 투표가 들어갔군요.","진심으로 어떻게 생각하냐는 질문에 정반대 답 두 개를 똑같은 미소로 내놓습니다. 심사위원단이 중재자를 요청합니다.","낭만적인 외출을 정했다가 신발도 신기 전에 마음을 바꾸셨군요. 달력은 첫 초대를 기록물로 보관 중입니다.","고백은 '드릴 말씀이 있어요'로 시작하지만 결국 '그러고 보니 지난 화요일 그 카페가...'로 끝납니다.","잘 자라는 메시지에 추신을 달고 또 추신을 달았습니다. 휴대전화가 감정 상담 당직을 서고 있군요.","둘이 걷던 중간에 갑자기 목적지를 바꾸자고 제안합니다. 상대방은 데이트 코스가 인터랙티브하다는 사실을 이제 알았네요.","데이트 장소를 정하려고 투표를 열었습니다. 첫 표가 나오자 후보를 바꾸셨군요. 연애 민주주의가 재투표를 꺼립니다.","다정한 메시지에 수정사항 두 개와 참고 링크 세 개가 붙었습니다. 사랑에도 고객지원 부서가 생겼군요.","같은 시간에 데이트 약속 두 개를 잡아 놓고 서로 보완하는 일정이라고 주장하셨군요. 달력은 그 이론을 거절했습니다.","당신의 매력은 다섯 갈래 교차로 같습니다. 단순한 만남이었는데 어느새 범례와 화살표가 필요해졌네요."],"wellbeing":["휴식용 팟캐스트를 두 배속으로 설정했습니다. 이 속도라면 차분한 목소리도 경매에 참가한 것처럼 들리겠군요.","아무것도 하지 않기로 하고 아무것도 하지 않는 가장 좋은 방법을 검색합니다. 휴식은 브라우저를 닫아 버렸어요.","침묵이 당신을 끄는 시간은 딱 8초예요. 그러고는 새롭고 재미있는 소식이 없느냐고 묻습니다.","산책하다가 우회로 세 곳과 즉흥적인 대화 두 번을 거쳐 동네 전체를 순회 강연장으로 만들어요.","자극 없는 휴식은 수상하죠. 오늘 이용 가능한 생각 목록부터 확인합니다.","사교적인 에너지 뒤에서 담요가 당신을 묵묵히 기다려요. 정확한 예약 시간은 포기했답니다.","차분한 음악도 당신의 호기심을 견디지 못해요. 두 곡 뒤에는 피아노의 역사를 조사 중이니까요.","평온한 저녁은 책 한 권으로 시작했어요. 지금은 책갈피 제작법에 관한 영상 일곱 편을 보고 있군요.","평온하게 숨 쉬는 앱을 설치했습니다. 모든 기능을 구경하고 싶은 마음 때문에 앱이 버티질 못했군요.","마음속 날씨는 상시 분주함입니다. 빨리 넘길 수 없는 광고가 나올 때만 몇 초간 고요해지네요.","휴식 영상을 켜고 세 배속으로 보셨군요. 평온함이 방을 가로질러 전력 질주합니다.","침묵에게 1분의 시간을 주셨습니다. 그리고 그 효과를 평가하려고 팟캐스트를 켰군요."],"wisdom":["당신 머릿속엔 의견이 너무 많아서 거수투표도 일주일이 걸려요.","당신은 화제를 바꾸는 게 아니에요. 이전 토론을 종료하지 않은 채 새 토론을 설립하죠.","침묵도 때로는 답이에요. 당신은 거기에 자세히 설명해 달라고 요청했습니다.","아이디어 하나가 스쳐 지나갈 때 이미 반대 방향에서 셋이 달려오고 있어요.","한 답이 반대되는 답까지 품을 수 있느냐고 물으셨군요. '네', '아니요', 그리고 '상황에 따라 달라요'라고 직접 답하셨네요.","당신의 짧은 문장 뒤에는 늘 부록이 있어요. 부록에도 별도의 서론이 있습니다.","모든 근거를 한자리에 소집하지 않으면 선택은 쉬워져요. 하지만 당신의 회의는 정족수 미달입니다.","모두를 아는 건 유용해요. 당신은 그들의 삶까지 드라마 시즌별로 저장했죠.","질문 하나는 깊을 수 있습니다. 질문 열다섯 개를 쌓으면 층계참 없는 계단이 되죠.","당신의 논리는 갈림길을 사랑합니다. 막다른 길 두 곳의 장식까지 비교하러 가는 경우도 있군요.","모순을 모두 해결하려고 혼자 모든 토론자 역할을 맡아 토론회를 열 필요는 없습니다.","모든 가능성을 생각하는 건 재능입니다. 그다음 모든 선택지가 동시에 옳다고 선언하면 철학이 아니라 서커스에 가깝죠."],"roast":["짧게 말하겠다는 당신의 대화는 도입부가 끝나기도 전에 달력이 다음 달로 넘어갔어요.","서로 반대되는 의견 둘을 목줄에 묶인 개 두 마리처럼 끌고 갑니다. 개들은 서로 반대쪽으로 달리고 싶어 해요.","같은 소문을 네 가지 버전으로 전하셨군요. 증인들은 자신들이 같은 사건을 겪었는지 의심하기 시작했습니다.","일화에 세부 사항이 부족하면 직접 덧붙입니다. 목격자들은 자기 이야기를 알아보지 못해요.","'전 완전히 일관돼요'라고 선언한 뒤 누가 따라오나 보려고 반대 주장까지 펼치셨군요. 아무도 박수칠 용기를 내지 못했습니다.","호기심 많은 당신 뒤에서는 다음 버튼이 완료 버튼보다 훨씬 잘 작동해요.","당신의 입을 거치는 소문은 급행열차만큼 빠릅니다. 비밀유지는 아직 플랫폼에서 기다려요.","당신의 집중력은 모든 방해 요소를 구독했어요. 공급업체조차 핵심 서비스가 뭔지 모릅니다.","작은 소문에는 증인 두 명과 짧은 도입부만 있었습니다. 당신이 부수 줄거리를 더하자 동네에서 시즌 2를 준비하는군요.","비밀스러운 이야기를 듣고 완전히 익명인 사례 연구로 소개했습니다. 주소만 빼고요.","같은 사건의 이야기를 세 번 바꾸셨군요. 원래 사건은 이제 증언을 거부합니다.","'우리끼리만'이라는 말이 벌써 네 번 환승했습니다. 비밀유지는 분명 다른 기차를 탄 모양이군요."]},"roastMy":["쌍둥이자리인 당신은 의견 두 개를 가진 게 아닙니다. 불안정한 의견 연합을 이끌고 있죠. 아이디어마다 장관 자리를 요구하고 앞선 생각을 뒤집은 뒤 즉각 개혁을 발표합니다. 당신은 그걸 소리 내어 생각한다고 부르죠. 머릿속에서는 의회 운영 규칙을 요구하고 있어요.","당신은 짧은 일화를 국제 대서사시로 만들어요. 서막과 조연 네 명, 과거로 돌아가야 이해되는 장면까지 나옵니다. 친구들은 최초의 질문을 잊었죠. 당신은 중요한 세부 사항 하나가 더 남았다고 발표합니다.","당신의 브라우저에는 탭이 아니라 도시 하나가 들어 있어요. 창마다 흥미로운 발견을 약속하며 자리를 내주지 않죠. 아침에 열었던 페이지를 찾고 있습니다. 검색엔진마저 도시 지도를 요청합니다.","당신은 놀라운 효율로 금세 지루해져요. 첫 번째 활동에 열광하다가 두 번째, 세 번째를 동시에 시작합니다. 하루가 끝날 때는 스무 개의 시작과 내일 할 일 목록이 남죠. 끝나지 못한 프로젝트들이 권익보호협회를 만들었습니다.","당신의 호기심에는 국경도 정지 버튼도 없어요. 누군가 주말 어땠냐고 물었더니 3분 뒤 그 사람 동네의 역사를 탐구하고 있죠. 상대는 영화 이야기를 하려던 참이었어요. 당신의 인터뷰는 기록물 담당 부서의 승인을 기다립니다.","당신은 너무 유창하게 말해서 상대들이 자기 차례를 되찾으려고 고개만 끄덕여요. 그런데 당신은 그걸 더 설명해 달라는 신호로 받아들입니다. 모임에서는 발언 요청용 깃발을 도입하죠. 당신은 즉시 깃발 색깔을 두고 토론을 제안합니다.","당신은 한 의견을 열정적으로 지지하다가 커피가 식기도 전에 정반대 의견을 받아들여요. 변화를 지적하면 둘은 상호보완적이라고 설명하죠. 커피는 식어 갑니다. 사전은 합의라는 단어의 정의를 다시 찾고 있어요.","당신의 소문 감각은 동네 신문도 부러워할 수준이에요. 누가 화분을 바꿨는지, 이웃이 왜 의자를 옮겼는지, 동료 둘이 몇 시에 웃었는지 전부 알죠. 절대 퍼뜨리지 않겠다고 맹세합니다. 그러고는 이런 말부터 해요. 이건 말하면 안 되는데요.","당신은 오후 한 번에 온 세상을 발견하고 싶어 해요. 요리를 시작하고 먼 나라 기사를 읽고 서랍 수리 영상까지 틀죠. 저녁이 다가오는데 서랍은 열려 있고 여행은 상상 속에서 예약됐습니다. 일정표는 통역사를 요청합니다.","당신의 생각은 너무 빠르게 옮겨 다녀서 대화들이 상상 속 안전모를 써야 해요. 실용적인 질문이 철학 토론으로, 휴가 추억으로, 과자 비교로 이어집니다. 마지막엔 아무튼이라고 말하죠. 아무도 요약해 달라고 할 용기가 없습니다.","당신의 머릿속은 모든 강연이 동시에 시작하는 축제 같습니다. 세 강연을 듣고 네 번째에 질문하고 다섯 번째에 메모까지 남깁니다. 처음 주제가 뭐였는지는 아무도 모르죠. 당신은 이런 밤을 아주 유익했다고 부릅니다.","단순한 데이트 하나도 대중교통 노선도처럼 복잡하게 만들 수 있습니다. 커피를 마시고 전시회를 본 뒤 인터넷에서 찾은 빵집까지 들르자고 하죠. 상대방은 겨우 따라옵니다. 이제 데이트에 관광 안내원이 필요합니다.","평범한 사건을 멋지게 이야기하는 놀라운 재능이 있으십니다. 초인종이 고장 난 일이 주인공과 동기, 반전이 있는 연속극이 됩니다. 친구들은 흥미롭게 듣고 있습니다. 초인종은 여전히 수리를 기다리죠.","고요한 시간을 보내며 한숨 돌리기로 하셨군요. 잔잔한 음악을 고르고 재생목록 다섯 개를 비교하다 악기 인터뷰까지 발견합니다. 두 시간이 지나 방은 조용합니다. 당신의 머릿속에서는 침묵에 관한 원탁 토론이 열리는 중이죠.","거의 모든 일에 대해 설득력 있는 의견 두 가지를 가지고 계십니다. 때로는 같은 문장 안에 두 의견이 함께 있죠. 결정을 내리라는 말에는 뉘앙스의 중요성을 설명합니다. 균형을 맞추려고 세 번째 관점도 더합니다. 심사위원은 당신이 심사위원까지 겸하고 있다는 사실을 확인했군요."]},"cancer":{"classic":{"career":["당신은 팀의 작은 긴장까지 잘 알아차려요. 그렇다고 분위기를 혼자 책임질 필요는 없어요.","동료가 어려운 하루를 보내고 있다면 당신의 경청이 큰 도움이 될 수 있어요. 자신의 여유도 소중히 지키세요.","업무상의 의견이 예상보다 오래 마음에 남을 수 있어요. 결론을 내리기 전에 맥락을 다시 살펴보세요.","지난 경험에 대한 기억은 선택에 도움이 돼요. 다만 오래된 실망이 새로운 시도까지 막게 두지는 마세요.","분위기가 변하면 직감적으로 알아차려요. 직접 대화해 그 느낌이 맞는지도 확인해 보세요.","다른 사람을 보호하려는 마음은 신뢰를 키워요. 각자가 직접 시도하고 결정할 자리도 남겨 주세요.","팀 프로젝트가 소중하다면 기대하는 바를 분명하게 말해 주세요. 말하지 않아도 알아주기를 바라지 마세요.","따뜻한 근무 환경은 당신에게 중요해요. 요청이 지나치게 많을 때는 경계를 세우는 연습도 필요합니다."],"love":["당신의 깊은 애착은 수많은 작은 배려로 표현돼요. 상대방이 직접 말하는 필요도 존중해 주세요.","행복한 추억이 떠오르면 현재를 평가하는 기준 대신 소중한 선물처럼 나눠 보세요.","서툰 한마디가 오래 마음에 남을 수 있어요. 침묵으로 물러서기 전에 뜻을 물어보는 편이 나을 수 있어요.","가족과 가까운 관계는 당신의 삶에서 큰 자리를 차지해요. 각자 자기 방식대로 함께할 공간을 마련해 주세요.","잠깐의 거리감에도 상상력이 빈칸을 채울 수 있어요. 간단히 물어보면 분명해지는 경우가 많아요.","위로가 필요하다는 마음을 솔직히 말해 보세요. 서로가 눈치로 맞히지 않아도 될 때 다정함을 전하기 쉬워집니다.","이해받지 못한다고 느낀다면 실망 속에 숨기보다 무엇이 마음을 건드렸는지 이야기해 보세요.","누군가를 돌보는 건 아름다운 사랑의 방식이에요. 모든 것을 직접 챙기지 않아도 다른 사람의 배려를 받아들여 보세요."],"wellbeing":["분위기에 민감한 당신에게는 익숙한 장소에서 보내는 휴식이 특히 소중해요.","감정이 쌓일 때 잠시 조용한 시간을 가지면 그 감정에 휩쓸리지 않고 바라볼 수 있어요.","좋아하는 장소 근처를 산책하면 편안한 연속성을 느낄 수 있어요.","향수는 때로 따뜻하게 다가와요. 추억을 즐기되 지금의 기쁨도 놓치지 마세요.","소중한 사람들의 부탁 앞에서도 자신을 위한 시간을 남겨 둘 권리가 있어요.","집을 아늑하게 꾸미는 일이 마음을 달래 줄 수 있어요. 다만 의무로 만들지는 마세요.","많이 지친 날이라면 속도를 늦추고 소박하고 편안한 저녁을 보내 보세요.","다른 사람의 안부를 묻는 일은 자연스럽죠. 오늘 자신에게 필요한 것도 물어보세요."],"wisdom":["다정함은 거절할 줄 알 때 더욱 단단해집니다.","과거는 마음을 따뜻하게 할 수 있지만 모든 선택을 지휘할 필요는 없어요.","감정은 귀 기울일 가치가 있지만 혼자 결정을 내려야 하는 건 아닙니다.","다른 사람을 보호한다고 그들의 침묵까지 짊어질 필요는 없어요.","기대하는 바를 분명히 말할 때 신뢰가 자라납니다.","안락한 집에도 각자가 숨 쉴 공간이 필요합니다.","직관에 귀 기울이되 현실과 맞춰 볼 때 더 정확해집니다.","자신을 돌본다고 다른 사람을 향한 사랑이 줄어들지는 않습니다."],"roast":["감정과 연결된 기억이 오래된 사소한 일을 현재를 판단하는 고정 기준으로 만들 수 있어요.","어떤 말에 상처를 받았을 때 말없이 있으면 다른 사람은 설명이 필요한 이유를 추측해야 해요.","소중한 사람을 너무 열심히 돌본 나머지 그들이 실제로 도움을 원하는지 묻지 않을 때가 있어요.","향수가 과거를 지나치게 아름답게 만들어 새로운 것을 실제보다 덜 반갑게 보게 할 수 있어요.","평범한 거리감에도 존재하지 않는 숨은 뜻을 찾을 때가 있어요.","자기 세계를 지키려는 마음이 관계를 위협하지 않는 변화까지 경계하게 할 수 있어요.","주변의 긴장을 감지하면 자신이 책임질 필요 없는 감정까지 떠안기도 해요.","다른 사람을 잘 위로하지만 정작 자신에게 무엇이 필요한지 말하기는 더 어려울 때가 있어요."]},"funny":{"career":["동료가 한숨만 쉬어도 업무를 줄인 일정표와 서류를 대신 검토하겠다는 약속을 들고 나타나시네요. 그 사람은 의자만 바꾸려던 참이었습니다.","상사가 느낌표 없이 고마워요라고 쓰면 오전 내내 그 메시지의 열정 수준을 분석하죠.","오래된 팀 사진 한 장이면 이직과 생일, 환영회까지 전부 돌아보는 추억 여행이 시작됩니다.","커피머신이 고장 났나요? 당신은 기계보다 팀의 사기가 걱정돼 휴게실에 위로 모임을 열어요.","새 인턴이 오면 너무 세심하게 환영해서 첫날부터 과자와 휴지의 위치까지 모두 알게 됩니다.","팀의 옛 메시지를 '혹시 몰라서' 전부 보관합니다. 메일함이 대화 보험회사로 바뀌었군요.","누군가 괜찮아요라고 하면 두 단어 사이에 숨은 한숨까지 듣고 바로 면담을 제안해요.","직장 분위기를 돌보는 게 당신답죠. 심지어 새잎이 나올 때마다 팀과 함께 축하하는 화분도 있어요.","동료가 바쁜 하루라고 말했습니다. 당신은 벌써 혼자 서류를 들지 않도록 근무 순환표를 짰군요.","메일함에는 지난 5년간 팀원들의 환영 인사가 전부 남아 있습니다. '맥락을 보관하려고요'라고 하시네요.","인턴이 회의실을 찾고 있습니다. 당신은 위치도와 동료들 이름, 응원의 말까지 준비하셨군요.","팀원들에게 다정한 알림 쪽지를 나눠 주셨군요. 할 일 게시판이 이제 아주 조직적인 가족 모임 같네요."],"love":["당신의 마음은 국립도서관처럼 추억을 분류해요. 첫 영화관 티켓에는 아마 전용 보호 커버가 있을 거예요.","메시지에 이모지가 없으면 애정 서비스가 잠시 점검 중인지 걱정합니다.","완벽한 로맨틱한 저녁은 첫 데이트 영화를 다시 보고 상대가 잊은 모든 장면을 설명하는 거예요.","당신의 다정함은 밥 충분히 먹었어요라는 질문에서도 드러나요. 놀라운 확신으로 여러 번 묻죠.","나중에 봐요라는 말에는 나중의 공식 정의와 정서적 온도가 몇 도인지 알고 싶어 해요.","손수 만든 선물을 받으면 포장지까지 간직해요. 그 종이에도 아름다운 사연이 있었으니까요.","익숙한 노래가 나오자마자 처음 들었던 장소와 날씨, 감정까지 줄줄이 설명합니다.","누군가 중요한 날짜를 잊어도 아무 말 하지 않아요. 대신 눈빛이 단독 강연을 시작할 듯하죠.","첫 데이트 때 식탁보 색깔까지 기억하십니다. 상대방은 그저 많이 웃었다는 사실만 기억하는데요.","오래된 노래가 지난 사랑의 시작을 떠올리게 합니다. 당신은 그날의 메뉴와 날씨, 버스 노선까지 기록 보관관처럼 설명하시는군요.","다정한 선물의 포장지를 간직하고 있습니다. 리본이 유난히 예뻤거든요. 정작 선물보다 포장에 관한 자료가 더 많군요.","첫 저녁을 똑같이 다시 보내자고 제안했습니다. 식당 주방장은 바뀌었지만 원래 메뉴의 사본을 가져오셨군요."],"wellbeing":["당신이 생각하는 위로는 부드러운 담요, 따뜻한 음료, 이미 줄거리까지 외운 영화 한 편이면 충분해요.","집에서 평온한 밤을 준비했습니다. 은은한 조명, 따뜻한 찻잔, 지정석까지 마련했군요. 손님 맞을 준비가 완벽합니다.","옛 학교 앞을 지나면 머릿속에서 서정적인 음악이 흐르는 다큐멘터리가 즉시 상영돼요.","쉬는 건 어렵지 않아요. 다만 다른 사람들도 나만큼 편안한지 걱정하기 시작하면 이야기가 달라지죠.","바쁜 하루 끝에는 집에 있자고 제안합니다. 소파는 오랜 여행에서 돌아온 가족처럼 반겨 주죠.","사진첩을 5분만 보려 했어요. 두 시간 뒤에도 케이크 사진 한 장에 감동하고 있습니다.","혼자 쉬는 시간이 낯설어서 누군가에게 간식을 만들어 줄 사람부터 찾습니다.","애니메이션을 볼 때는 휴지를 가까이 두세요. 잃어버린 장난감이 주인에게 돌아와도 눈시울이 뜨거워지니까요.","당신의 부엌에는 힘든 날을 위한 특별한 요리법이 있습니다. 집에 돌아온 것을 환영하는 의식처럼 정성껏 만들죠.","편안한 밤의 시작은 담요 고르기입니다. 이 과정에는 예선이 세 차례나 있군요.","거실의 완벽한 조명을 찾았습니다. 이제 램프를 손가락 하나만큼 옮기는 것도 대담한 실험입니다.","당신이 생각하는 조용한 외출은 장을 봐서 맛있는 저녁을 만들고 서둘러 집으로 돌아와 집의 편안함을 즐기는 것입니다."],"wisdom":["당신의 직관은 가끔 알겠다는 말 한마디에서 드라마를 듣습니다.","뿌리는 서 있도록 돕지만 새 가지가 자라는 것까지 막지는 않습니다.","다정함이 모든 감정에 간식을 준비해 줘야 하는 건 아닙니다.","가까운 사람의 침묵이 비극의 첫 장면인 건 아니에요.","피난처는 안에서도 문을 열 수 있을 때 더 든든합니다.","소중한 사람을 지킨다는 건 그 사람의 날개 크기까지 정해 주는 일이 아닙니다.","사랑은 상대가 자기 수프를 고르도록 두는 데서도 드러납니다.","다른 사람을 돌보는 일은 그 사람의 말이 끝날 때까지 기다리는 데서 시작될 수 있어요.","튼튼한 뿌리라고 잎들이 어느 쪽 햇빛을 향할지 대신 정할 수는 없습니다.","소중한 관계를 지키면서도 그 사람의 개인 일정표까지 쥐고 있을 필요는 없습니다.","정원을 돌본다는 건 식물들이 자기만의 모양으로 자라게 두는 일이기도 합니다.","기억은 길을 밝혀 줍니다. 뒤만 바라보는 동안 운전대를 잡도록 맡기지는 마세요."],"roast":["당신은 너무 오래된 생일 카드를 보관해서 봉투가 친구들보다 당신의 역사를 더 잘 알 지경이에요.","누군가 알겠어라고 답하면 무슨 일이 생긴 건지 머릿속에서 시나리오 세 편이 바로 시작됩니다.","짧은 '네'라는 답을 암호문처럼 해석하셨군요. 가까운 세 사람이 이미 당신의 모든 가설을 전달받았습니다.","옛 애니메이션 주제가만 들려도 오늘은 눈물 나는 날이 될 거라고 선언합니다.","색연필 광고를 보며 눈물이 핑 돌았습니다. 주인공이 마침내 가장 좋아하는 색을 되찾았거든요.","소중한 사람의 음성 메시지는 고작 지금 가요라고만 해도 지우기가 어려워요.","가족 모임에 갈 때마다 사진을 더 찍고 모두 즐거웠는지 확인하는 임무를 스스로 맡습니다.","누군가 별일 없다고 하면 그 말 뒤에 숨은 감정을 확신하고 수사를 시작해요.","'곧 봐요'라는 말을 너무 모호한 공식 선언으로 받아들이셨군요. 당신의 침묵이 행사복으로 갈아입었습니다.","강아지가 장난감을 다시 찾는 광고를 보며 눈물을 닦으셨군요. 정작 강아지는 벌써 다른 장난감을 갖고 놀고 있는데요.","기분 나쁘지 않다고 하시지만 '물론이죠'라는 말투가 단체 대화방 전체를 얼려 놓았군요.","작은 모임 초대에서 빠졌습니다. 표정은 여전히 다정하지만 말줄임표에는 엄숙한 식전의 분위기가 흐릅니다."]},"piquant":{"career":["당신의 섬세함은 세 단어짜리 이메일에서 숨은 뜻을 찾아냈어요. 보낸 사람은 시간만 확인하려던 겁니다.","동료가 짧게 한숨을 쉬자 부담을 덜어 주는 새 일정표를 내놓으셨군요. 사실 그는 그냥 자세를 고치려 했습니다.","팀의 작은 변화에도 거창한 작별식을 열어요. 옮겨진 의자는 기념 앨범을 받았습니다.","누군가 인사를 잊으면 예의 위반 조사위원회를 머릿속에 소집합니다. 그 사람은 통화 중이었어요.","별뜻 없는 말 한마디도 밤까지 따라다녀요. 감정 일지의 공식 항목으로 등록됐습니다.","팀원들의 지원을 마치 무제한 구독 서비스처럼 제공하시네요. '고마워요'라는 말 한마디도 사건의 공식 종료로 기록됩니다.","직장 습관은 당신에게 소중해요. 화분 위치가 바뀐 날에는 추모식까지 생각합니다.","당신의 직장 기억에는 옛 사무실 시절 이야기가 가득해요. 프린터조차 감동적인 조연이었죠.","동료들의 기분을 사내 기상 예보처럼 관찰합니다. 누군가 하품하자 긴급 지원 속보를 내셨군요.","오래된 메일을 백업 폴더 여섯 개에 보관합니다. 장애가 생겨도 쉼표 하나가 태어난 순간까지 재구성할 수 있겠어요.","직장에서 당신의 친절이 비공식 직원보호센터를 만들었습니다. 쉬는 시간에도 배려 확인서가 따라붙는군요.","새 직원이 '제가 알아서 할게요'라고 말했습니다. 당신이 건넨 입문 키트에는 복도 지도까지 들어 있군요."],"love":["당신의 향수는 영화표를 국가 문서처럼 보존해요. 추억 서랍은 증축을 요청했습니다.","이모지 없는 알겠어를 싸늘한 외교 선언으로 해석합니다. 휴대전화는 위기가 발생한 줄도 몰라요.","조그만 다정한 추억도 머릿속 상설 전시관으로 들어갑니다. 관람객은 손대면 안 돼요.","누군가 작은 기념일을 잊어도 아무것도 아니라고 말해요. 침묵은 이미 알림 열네 개를 보냈습니다.","첫 데이트 식당 영수증을 간직하고 계시군요. 거기에 붙인 주석이 역사 문헌보다 많습니다.","당신의 세심한 배려 뒤에서는 애정 표현이 제대로 인정받았는지 확인하는 감시실이 작동합니다. 기록부가 열렸어요.","사랑 때문에 옛 대화를 휴대전화에 간직한다면서요. 내면의 기록관리자는 10년 단위 분류를 준비합니다.","당신의 마음은 누구든 따뜻하게 맞아들이지만 현관의 감정 장식을 알아봐 주지 않으면 서운해합니다.","첫 데이트는 안내 투어가 가능한 수준으로 보관돼 있습니다. 종이 냅킨에도 설명서가 붙어 있네요.","둘이 식사한 흐릿한 사진을 간직하며 당시 분위기가 담겼다고 주장합니다. 사진사는 그냥 접시 하나만 보이는데요.","예전 대화들을 감성적인 제목으로 저장하셨군요. 휴대전화가 스스로 로맨스 도서관을 운영한다고 믿기 시작했습니다.","기억에 남는 외출의 입장권을 발견하고 재현 행사를 준비합니다. 상대방은 커피 한 잔 마시자는 줄 알았는데요."],"wellbeing":["당신의 휴식은 옛 영화를 다시 보며 예전에 느낀 감정을 정확히 재현하는 일이에요. 엔딩 크레딧은 당신을 이미 알아봅니다.","거실을 모든 기분이 들를 수 있는 공간으로 꾸며 놓으셨군요. 담요 접수 창구만 있으면 완벽하겠습니다.","소파가 당신을 너무 잘 이해해서 외출 수락 전에 의견을 묻습니다. 소파는 언제나 담요에 표를 던져요.","위로가 되는 음식을 의식처럼 정성껏 준비합니다. 수프가 식탁에 오르기 전에 축사부터 들었군요.","집에서 보내는 평화로운 하루가 사진과 상자, 추억 어린 컵 사이를 도는 성지 순례가 됩니다. 먼지는 방명록에 서명해요.","아늑한 공간을 원하는 마음 뒤에는 한숨까지 지키는 쿠션 요새가 있어요. 손님은 감정 검문을 통과해야 입장합니다.","산책하다가 벤치 하나가 옛 대화를 떠올리게 하면 그 벤치는 대하드라마의 주인공이 됩니다.","한 시간 쉬려던 계획이었죠. 그런데 사연 있는 담요를 찾는 데만 40분을 썼어요.","당신의 아늑한 저녁에는 담요 네 개, 따뜻한 음료, 외풍 차단 점검이 필요합니다. 거실이 극지 연구 기지 같군요.","오븐에서 좋은 냄새가 나자 집이 세상과 공식적으로 화해했다고 선언하십니다. 타이머가 예의상 박수를 치네요.","좋아하는 의자에는 전용 조명과 찻잔, 대기 중인 담요가 있습니다. 자리를 잡는 의식이 영화보다 더 길군요.","자기 거실에 남긴 고객 후기입니다. '분위기는 훌륭하지만 주 담요가 거주지를 떠나지 않습니다.' 별 다섯 개군요."],"wisdom":["당신의 향수는 지나간 일요일 박물관을 확장할 예산을 신청했어요. 현재는 밖에서 기다립니다.","뿌리는 자라는 것을 키웁니다. 그런데 당신은 가끔 뿌리에게 정원 전체의 지휘권까지 넘기시네요.","세상을 지킨다고 모든 새로운 경험마다 신분 확인대를 설치할 필요는 없습니다.","누군가 아무것도 아니라고 말하면 감정 수사 네 장을 시작합니다.","애니메이션을 보고 눈물을 흘렸다고 기자회견까지 할 필요는 없어요. 이미 자료집을 준비했지만요.","당신의 다정함 뒤에서 감시관은 누가 적절한 순간에 고맙다는 말을 잊었는지 기록합니다.","당신의 기억은 훌륭한 도서관입니다. 현재를 위해 열람실 문도 열어 두면 좋겠군요.","남을 돌본다고 감정 일정표까지 짜서 선물할 필요는 없어요.","당신은 뿌리를 열심히 지키십니다. 하지만 새 잎이 하나 날 때마다 경비원을 세울 필요는 없어요.","과거에 대한 애착은 깊이를 줍니다. 그 과거를 미래의 유일한 설계도로 삼으면 길 찾기가 꽤 어려워집니다.","당신의 보호 본능은 소중합니다. 다만 인사하러 온 사람에게 울타리까지 치는 건 조금 과하죠.","뛰어난 기억력은 나침반입니다. 그런데 당신은 나침반을 모든 미래 경로의 종신 장관으로 임명하셨군요."],"roast":["'알겠어요'라는 답을 너무 무표정하게 했다는 이유로 삐치셨군요. 문장 끝 마침표가 이제 주요 용의자입니다.","당신은 삐치는 기술이 너무 섬세해서 동네 전체가 정확한 이유를 추측해야 해요. 구청은 수사 요청을 거절했습니다.","최근 애니메이션에서 물건이 주인과 재회했다고 눈물을 쏟았군요. 물건은 조용히 넘어가 달라고 부탁합니다.","가족 상봉 광고에 감동한 뒤 토스터가 이 순간을 함께 나누지 않는다며 타박하셨군요.","옛 단골 카페에 들른 일은 역사적 기념행사가 됩니다. 직원은 그냥 주문을 받으려던 건데요.","사랑스러운 배려 뒤에는 모두가 노력을 알아봤는지 확인하는 보이지 않는 체크리스트가 있어요. 도장만 남았습니다.","가벼운 농담에 기분이 상하셨군요. 세 시간이 지나자 사건 파일에 시간표와 증인 두 명까지 붙었습니다.","아무도 모르게 삐치려던 계획이었군요. 대신 침묵할 시간을 상세히 적은 안내문을 배포하셨습니다.","당신의 '다 괜찮아요'에는 너무 치밀한 침묵이 따라붙어서 오프닝 음악이 필요할 지경입니다.","평범한 메시지의 문장부호를 추리소설 수사관처럼 분석하셨군요. 범인은 그냥 키보드의 마침표였습니다.","재회 광고에 감동한 뒤 감독에게 왜 상상 속 휴지 상자로 당신을 기습했느냐고 항의하시네요.","가벼운 농담이 마음에 들지 않자 '전혀 문제 없어요'라고 답합니다. 단체방에는 이제 가능한 사과 일정표가 배포됐군요."]},"roastMy":["게자리인 당신은 추억을 간직하는 게 아닙니다. 평범한 감정들로 사립 박물관을 운영하죠. 구겨진 표와 리본, 옛 장보기 목록마다 설명문이 붙어 있어요. 그 중요성을 20분 동안 설명합니다. 서랍이 마침내 매표소를 열었습니다.","당신은 이유를 알리지 않은 채 협상을 끊어 버리는 외교부처럼 삐쳐요. 괜찮냐는 질문에는 완벽히 괜찮다고 대답하죠. 그 뒤 당신의 침묵이 성명서 세 장을 작성합니다. 쿠션들이 평화 특사로 파견됐어요.","애니메이션에서 헤어진 두 인물이 재회하면 잘 울어요. 장면을 외우면서도 휴지를 준비하죠. 친구가 왜 또 보느냐고 묻습니다. 당신은 줄거리 때문이라고 답하고 엔딩 크레딧은 한숨을 쉽니다.","당신의 휴대전화에는 마음을 울린 화면 캡처가 도서관만큼 많아요. 평범한 메시지도 중요한 날에 왔다며 보관하죠. 누군가 정리를 제안합니다. 기록물 위원회가 즉시 제안을 반려했어요.","당신은 24시간 운영하는 특급 안내 데스크처럼 사랑하는 사람을 챙깁니다. 담요와 음료, 응원 쪽지를 준비하죠. 그런데 아무도 냅킨을 완벽하게 접은 걸 알아봐 주지 않아요. 내면의 감사 담당 부서가 항의서를 제출합니다.","당신에게 집은 단순한 인테리어가 아니에요. 쿠션마다 추억이 있고 컵마다 사연이 있고 소파 구석마다 감정적 가치가 있죠. 손님이 스탠드를 옮기자고 합니다. 당신은 방의 문화유산을 존중해 달라고 요청해요.","당신은 모든 것을 기억해요. 특히 남들이 잊은 사소한 말들을요. 오래전 점심에 나온 농담 하나를 날짜와 메뉴까지 곁들여 다시 꺼냅니다. 말한 사람은 무슨 이야기인지도 몰라요. 당신의 기억이 회의록을 제출합니다.","당신은 가까운 사람들과 아늑한 저녁을 보내는 걸 좋아해요. 누군가 조금 일찍 가야 한다고 말하기 전까지는 모든 게 따뜻하죠. 당신은 웃으며 빈 의자를 영화 장면처럼 바라봅니다. 의자는 슬픈 배경음악 좀 꺼 달라고 요청해요.","당신의 감정 레이더는 문장부호만 보고 기분 변화를 알아챕니다. 느낌표 없는 고맙다는 말에 원인 조사가 시작돼요. 3주치 대화를 다시 읽으며 의미를 찾습니다. 상대는 그냥 배터리가 부족했던 거예요.","당신은 과거를 너무 좋아해서 오래된 과자 상자에도 거주권을 줍니다. 상자 하나하나가 소중한 순간을 떠올리게 한다고 설명하죠. 새 과자를 넣을 공간은 없습니다. 부엌은 감성 도시계획을 수립하기 시작해요.","냄새 하나만으로 첫 저녁의 모든 장면을 되살릴 만큼 감정 기억력이 뛰어납니다. 식탁에는 그때의 요리와 저녁 이야기가 함께 올라오죠. 가족들은 다정하게 듣습니다. 현재의 저녁은 이야기 속 자기 차례를 기다리는 중입니다.","직장에서 당신은 등대지기처럼 팀을 지키십니다. 동료가 자리를 옮기자 문제가 없는지 곧바로 확인합니다. 그는 창문 가까이 앉으려던 것뿐이죠. 그런데도 작은 환영 방문을 준비하셨군요.","당신의 집은 편안함을 위한 최고의 환영위원회입니다. 조명을 고르고 쿠션을 다듬고 포근한 요리법까지 찾았습니다. 손님이 바람을 쐬러 나가자고 합니다. 그러자 부엌에 갑자기 내일 메뉴가 등장하네요.","당신의 서운함은 작은 말을 조용한 연속극으로 만드는 재능이 있습니다. 이제 생각하지 않는다고 말하면서도 문장들을 발언 순서대로 정리하시죠. 다음 날이면 다 평온해집니다. 하지만 기억 속 자막은 지워지지 않았군요.","광고를 보고 웃다가 결말에서 감동할 만큼 감수성이 풍부합니다. 잠시 뒤 가까운 사람에게 가장 다정한 장면들을 곁들여 다시 이야기하죠. 듣는 사람은 대작 영화를 놓쳤나 싶어 합니다. 사실 수납 상자 할인 광고였는데요."]},"leo":{"classic":{"career":["주목받고 싶은 마음은 팀의 성과도 함께 빛낼 때 큰 힘이 됩니다.","눈에 띄는 일을 먼저 맡는 것을 좋아하죠. 드러나지 않는 동료의 기여까지 살피면 영향력이 커질 거예요.","자신감은 아이디어를 자연스럽게 소개할 기회를 열어 줍니다.","즉각적인 인정에 얽매이지 않고 창의력을 발휘할 때 생각이 더 깊어집니다.","앞장서는 역할에 끌리지만 무대 뒤에서 쌓이는 노력의 가치도 알아봐 주세요.","당신의 당당함 뒤에는 진정한 책임감이 있어요. 말보다 행동으로 보여 주세요.","직장에서 보여 주는 너그러움이 팀에 새로운 활력을 줄 수 있어요.","프로젝트에 쏟는 열정에는 끊임없는 칭찬보다 명확한 방향이 더 도움이 돼요."],"love":["당신의 따뜻함은 나누는 만큼 상대의 말에도 귀 기울일 때 더욱 특별해집니다.","관심받는 것을 좋아하죠. 보답을 기대하지 않는 배려도 친밀함을 키웁니다.","관계에서 인정받고 싶은 마음과 상대를 향한 호기심을 함께 품어 보세요.","감동을 줘야 한다는 부담을 내려놓으면 더 부드러운 애정이 드러나요.","너그러운 사랑은 거창한 고백보다 작은 행동에서 빛날 수 있어요.","자존심 뒤에는 더 조용한 언어로 전하고 싶은 진심이 숨어 있어요.","칭찬도 기쁘지만 솔직한 대화에서 더 오래가는 행복을 얻을 수 있어요.","당신의 사랑은 관계에서 각자가 충분한 자리를 가질 때 더 큰 의미를 얻습니다."],"wellbeing":["넘치는 에너지에도 무언가를 증명할 필요 없는 순간이 필요해요.","다른 사람의 시선에서 벗어난 고요함 속에서도 힘을 회복할 수 있어요.","누구에게 보여 주기 위해서가 아니라 자신을 위해 창작하는 기쁨을 느껴 보세요.","일정 속에서 늘 중심에 서 있다면 조용한 휴식으로 균형을 되찾아 보세요.","목표 없는 산책은 성과를 요구하지 않는 공간을 열어 줍니다.","열정이 넘치는 당신에게도 쉬어야 할 이유는 충분해요.","소중한 사람들과 함께할 때 꼭 분위기를 이끌지 않아도 마음을 채울 수 있어요.","삶을 즐기는 마음에 스스로 선택한 평온한 시간도 곁들여 보세요."],"wisdom":["자신의 빛으로 다른 사람도 빛나게 할 때 그 빛은 더 강해집니다.","박수받지 않아도 당신의 가치는 사라지지 않습니다.","소박해질 용기는 더 오래가는 품격을 보여 줍니다.","자존심이 경청을 배우면 자신감이 됩니다.","진심 어린 존재감은 화려한 과시보다 더 멀리 비춥니다.","눈에 보이는 성공 뒤에는 작은 행동을 이어 온 성실함이 있습니다.","아름다운 열정에 언제나 무대가 필요한 것은 아닙니다.","빛난다는 건 다른 사람과 공간을 나눌 줄 아는 일이기도 해요."],"roast":["이끌고 싶은 마음이 너무 강하면 다른 사람은 문장을 끝내기조차 어려워져요.","주목받는 것을 좋아하지만 주변이 조용하다고 반드시 당신을 인정하지 않는 건 아니에요.","계속 칭찬받고 싶은 마음이 진정 자랑스러운 것을 가릴 수도 있어요.","모든 대화를 설득의 기회로 만들면 자연스러움이 사라져요.","눈에 띄게 등장하는 것만으로 세심한 존재감을 대신할 수는 없어요.","너그러움 뒤에 좋은 일을 했다는 사실을 반드시 누가 봐 주길 바라는 마음은 없는지 살펴보세요.","다른 사람의 시선만으로 관계의 가치를 모두 알 수는 없어요.","마지막 말을 포기한다고 당신의 매력이 줄어드는 건 아니에요."]},"funny":{"career":["당신의 사무실은 무대예요. 서류 정리 하나에도 앙코르 박수가 필요하죠.","회의에서 새로운 파일명 하나를 제안하면서 세기의 발견을 발표하듯 말합니다.","동료가 당신을 칭찬하면 즉시 부서에서 가장 좋아하는 사람 1위가 돼요. 순위는 매시간 갱신됩니다.","자원자를 모집하면 질문이 끝나기도 전에 손을 듭니다. 손은 곧 마이크도 요구해요.","문서에 서명하는 일도 당신에게는 공식 기념식이 됩니다.","모니터 뒤에서 경영진을 방송 오디션 심사위원처럼 여기며 발표를 연습합니다.","팀이 성과를 내면 너무 기뻐서 단체 사진부터 제안해요. 물론 가운데는 당신 자리죠.","당신의 명함에는 잊지 못할 순간 담당자라고 적어도 돼요. 사실 이미 비공식적으로 맡고 있거든요.","사내 공지입니다. 앞으로 당신의 발표에는 엔딩 크레디트가 들어갑니다. 엑셀 문서는 자신이 예술가가 된 줄도 몰랐군요.","회의 뒤 팀원 전원을 칭찬하셨습니다. 그리고 본인의 폐회사를 적어 갈 수 있도록 카드까지 나눠 주셨군요.","당신의 추산에 따르면 당신이 말할 때 회의의 흥미가 40% 높아집니다. 동료들은 이 통계를 끄는 방법부터 물었습니다.","'누가 회의를 진행하죠?' '공식적으로는 아무도요.' 그래도 당신은 정문 입장과 마지막 인사까지 준비해 두셨네요."],"love":["당신의 매력은 큰 몸짓을 좋아해요. 과자 하나를 건네면서도 소개 연설이 필요합니다.","저녁 식사에 초대하면서 입장 음악까지 준비하셨군요. 상대방은 파스타를 먹으러 오는 줄 알았지 세계적인 시사회에 참석하는 줄은 몰랐습니다.","어떤 데이트든 영화제처럼 등장해야 한다고 믿어요. 레드카펫은 선택 사항이죠.","상대가 하루 이야기를 할 때 진지하게 듣다가도 슬쩍 새 옷을 알아봤는지 확인합니다.","둘이 찍는 사진은 몇 번이고 다시 찍어야 마음에 들어요. 주로 당신의 미소가 가장 잘 나올 때까지요.","당신의 다정한 너그러움 뒤에서는 언제 멈춰야 할지 모르는 작은 악단이 연주 중이에요.","다정한 말 한마디에 마음이 녹아요. 예쁜 스웨터네요라는 칭찬 하나로 저녁까지 행복해집니다.","고백을 카드 세 장에 나눠 적었는데 갈수록 더 로맨틱해집니다. 상대방이 답할 시간을 벌려면 중간 휴식이라도 필요하겠어요.","낭만적인 깜짝 선물에는 꽃잎과 재생목록, 상세한 일정표가 있습니다. 상대방은 신발을 어디에 둘지만 물었는데요.","너무 거창한 고백을 보내서 휴대전화가 연재물로 올리자고 합니다. 첫 회는 하트 하나로 끝나네요.","데이트에 꽃다발과 짧은 연설을 들고 오셨군요. 다행히 꽃다발에는 자막이 필요 없습니다.","촛불 저녁을 영화 같은 입장 장면으로 꾸몄습니다. 작은 불꽃이 주인공 자리를 빼앗을 뻔했군요."],"wellbeing":["휴식하는 아침은 유명 스파에 어울릴 옷 고르기로 시작합니다. 고민이 너무 길어 차는 분장실에서 식어 버렸군요.","조용히 쉬려고 했는데 2분 뒤 휴식 후기를 게시할까 생각합니다.","당신의 관리 루틴에는 시작과 절정, 엔딩 음악이 있습니다. 크림 병이 가장 시간을 잘 지키는 무대 파트너군요.","가벼운 산책도 개인 패션쇼가 됩니다. 자신감 있게 걸어가니 비둘기들이 상상의 사진기자처럼 비켜서네요.","일정 없는 저녁도 좋지만 엔딩 음악만큼은 직접 고르고 싶어 해요.","바깥 활동을 좋아하지만 때로는 소파와 품격에 맞는 담요 한 장이면 충분해요.","고요한 시간도 마음에 들어요. 다만 아무도 고요함을 칭찬 부족과 혼동하지 않는다면요.","오로지 자신을 위한 시간을 마련했군요. 느긋한 목욕, 웅장한 목욕가운, 수건 위의 상상 속 사인까지 준비됐습니다.","피부 관리 팩을 쓰는 10분마저 시상식 준비로 바꿉니다. 욕실에서 나올 때는 비밀 분장실에서 나온 스타 같네요.","가상의 오늘 날씨입니다. 스파 같은 분위기, 은은한 향기 안개, 목욕가운을 위풍당당하게 걸칠 확률 매우 높음.","쉬는 시간에 잔잔한 음악을 골랐습니다. 두 곡 뒤에는 다음 미용 의식의 제목까지 지으셨군요.","조용한 목욕만으로도 거의 충분합니다. 다만 수건은 유명 호텔도 놀랄 만큼 완벽하게 접혀 있어야겠죠."],"wisdom":["당신의 겸손이 늦는 이유는 더 극적인 입장을 찾고 있기 때문이에요.","다른 사람과 빛을 나누는 건 좋아요. 스위치는 계속 본인이 잡으려 하지만요.","빛은 자기 일대기를 설명하지 않고도 주변을 밝힙니다. 태양에게 그 기술을 배워 보셔도 좋겠습니다.","아무도 지켜보지 않을 때 사자자리도 드디어 따뜻한 커피를 끝까지 마실 수 있어요.","좋은 아이디어에 꼭 당신 사진이 들어간 포스터가 필요한 건 아니에요.","거창한 연설 뒤에 숨어 있는 바람이 사실은 과자 한 조각일 때도 있어요.","빛나는 일은 밝기 경쟁이 아닙니다. 촛불 하나도 등대에 전쟁을 선포하지 않고 쓸모 있을 수 있습니다.","함께 빛나면 조명을 전부 혼자 들 필요가 없어요.","램프는 방 안의 유일한 빛이 되려고 애쓰지 않을 때 더 잘 비춥니다.","빛날 용기도 좋지만 누군가 먼저 지나가도록 비켜 주는 용기도 중요합니다.","진짜 빛은 사람들이 얼마나 고개를 돌리는지로 측정되지 않습니다. 가로등이 그 사실을 보증합니다.","겸손은 빛을 꺼 버리는 게 아닙니다. 다른 사람들이 열쇠를 찾을 때 밝기를 조금 낮추는 것이죠."],"roast":["당신이 방에 들어오려면 예고편이 필요해요. 그냥 열쇠 가지러 들어오는 건데 말이죠.","당신은 시간을 묻는 게 아니라 시계에 답변할 영광을 베풀어요.","당신의 겸손은 너무 은밀해서 휴대전화 배경화면에 금색 글씨로 적혀 있군요. 글자 크기는 '왕실용'입니다.","누군가 일화를 이야기하면 당신은 현장에 없었어도 더 극적인 버전을 내놓습니다.","당신 없는 단체 사진은 당신 기준으로 구도가 잘못된 사진이에요.","왕 같은 미소 뒤에는 칭찬 부족 전담 고객센터가 운영되고 있어요.","남의 생일도 즐거워요. 드디어 당신의 등장을 위해 장식된 장소가 생겼으니까요.","선물을 주는 마음은 진심이에요. 다만 선물 안에 당신에 대한 감사 프로그램이 들어 있기도 하죠.","당신 없이 사진을 찍어 보셨군요. 휴대전화는 조작 실수로 판단했습니다.","거울에는 작은 명패가 붙어 있습니다. '이곳에는 당신의 가장 충실한 팬이 근무합니다.' 영업시간도 길군요.","'정말 대단하세요'라는 칭찬에 '어느 분야에서요?'라고 답하십니다. 질문지는 세 쪽입니다.","당신의 자아가 조용한 사람 뽑기 대회에 참가했습니다. 참가 사실을 알리려고 보도자료를 배포했군요."]},"piquant":{"career":["당신의 야망은 직책이 아니라 회사를 향해 손을 흔들 발코니를 찾고 있어요. 인사팀은 조명 설치를 고민합니다.","회의에서 자신의 기여를 꼭 알아봐 달라고 합니다. 의자 하나를 옮겼을 뿐인데 연례 보고서가 나올 판이에요.","팀의 작은 성공도 당신의 기자회견이 됩니다. 다른 동료들은 단체 사진에서 자신을 찾아야 해요.","발표 뒤 박수가 없으면 모두의 예술 감각에 단체 고장이 났다고 의심합니다.","승진도 직함을 충분히 번쩍이는 명패에 새길 수 있어야 마음에 들어요. 사무실 가구들이 생존 협상을 시작했어요.","당신의 지도자다운 열정 뒤에서 모든 동료는 자기도 모르게 엑스트라로 캐스팅됐어요. 동의 없는 오디션이 시작됐죠.","익명 업무는 개인적인 모욕입니다. 증인 없는 업적이 무슨 소용인가요? 프린터는 사인 요청을 거절합니다.","당신의 리더십은 분기 보고회를 대형 공연으로 만듭니다. 정작 수치들은 엑스트라 출연에 동의한 적이 없군요.","속보입니다. 팀이 프로젝트를 마치자마자 당신은 승리 연설, 제작 뒷이야기, 연례 시상식 계획까지 준비했습니다.","이를 참여형 경영이라고 부르십니다. 동료들의 주된 참여 활동은 당신의 홍보 포스터에서 자기 자리를 찾는 일이군요.","발언이 워낙 장엄해서 발표 자료에 앙코르 요청까지 들어왔습니다. 원래 안건은 아직 슬라이드 한 장도 못 받았는데요.","가상의 사내 조사입니다. 직원 98%가 당신의 최신 성과를 압니다. 휴가 중이던 2%에게는 등기우편이 발송됐군요."],"love":["칭찬을 향한 갈망이 조용한 저녁을 시상식으로 바꿔요. 메뉴에는 올해의 특별한 존재라는 부문까지 생겼습니다.","애정을 아낌없이 주고 나서 감사 인사 시상식을 기다려요. 수상 소감에는 꼭 당신 이름이 들어가야 합니다.","낭만적인 놀라움을 준비하면서 무대 연출이 너무 거창해 초대받은 사람에게 프로그램까지 나눠 줍니다. 감동은 1부 순서네요.","관심을 끌고 싶지 않다고 말하면서도 누가 그 선언을 들었는지 이미 확인하고 있어요.","수수한 고백은 오히려 수상해요. 사진기자와 바이올린 연주자는 어디에 숨었나요?","화려한 매력 뒤에는 반응을 감시하는 작은 검사실이 있어요. 미지근한 미소 하나도 감사 대상입니다.","소박한 로맨틱한 행동은 이해하기 어려워요. 막이 오르는 커튼은 어디에 설치하죠? 소파는 공연 허가를 요청합니다.","당신의 마음은 넓어요. 특히 본인 액자를 걸 자리에는요. 상대에게는 액자 테두리를 고를 권한을 줍니다.","당신은 로맨틱한 데이트를 준비하는 게 아니라 연애 대작 영화를 제작합니다. 디저트마저 오디션을 보네요.","'깜짝 선물을 준비했어요.' '뭔데요?' '발표까지 3분만 기다리세요.' 놀라움에도 당신의 서명이 들어가는군요.","당신의 애정은 리본과 바이올린, 상상 속 사진기자와 함께 등장합니다. 상대방은 그냥 손을 잡을 곳을 찾고 있는데요.","작은 카드 한 장이면 충분했을 텐데 양피지와 밀랍 봉인, 낭독식까지 준비하셨군요. 이제 우편배달부가 사회자입니다."],"wellbeing":["당신의 휴식에는 관객이 필요해요. 평온함을 목격할 팬이 없으면 정식 민원을 고려합니다.","당신의 미용 의식에는 세팅과 소품 세 개, 욕실을 나서는 장엄한 퇴장이 포함됩니다. 목욕가운이 출연료를 요구하고 있군요.","소파에서 잠시 쉴 생각이었는데 어느새 자서전 열 권을 펼쳐 놓았어요. 쿠션들이 저작권료를 요구합니다.","명상을 마음속 시상식으로 바꿔 버리셨군요. 평온함이 우승했는데 트로피는 본인이 가져가셨습니다.","혼자 산책한다더니 쇼윈도 앞에서 퍼레이드를 열어요. 마네킹들이 경쟁을 멈춰 달라고 요청했습니다.","바쁜 하루 뒤에 무대 조명 없는 1분을 찾았어요. 그리고 그 1분에 본인 이름을 붙였습니다.","조용한 목욕도 좋지만 성과를 발표하고 싶어지자 심사위원단까지 소집했어요.","당신의 자기 관리 방식은 순회공연 중인 스타의 분장실 같습니다. 보습 크림조차 비밀유지계약서를 들고 다니네요.","당신의 피부 관리 의식이 개인의 시간이 아니라 궁중 의전이 됐습니다. 화장솜에는 출입증이 있고 수건에는 공식 직급이 있군요.","고객 후기입니다. '휴식은 완벽했지만 목욕가운이 세 번째 등장 전까지 분장실을 떠나지 않았어요.' 총평은 왕실급 복잡함입니다.","당신은 목욕을 하는 게 아니라 미니 온천시설 개장식을 엽니다. 거품이 최고의 자리를 예약했군요.","당신의 평온 사용 설명서입니다. 분위기 준비, 소품 선택, 입장 선언. 선택 사항은 실제로 쉬기입니다."],"wisdom":["당신의 자존심은 왕좌조차 필요 없어요. 이미 이사회 전체를 예약했거든요.","당신은 카리스마라고 불러요. 벽들은 쉬는 시간 없는 강연이라고 부릅니다.","침묵은 당신의 재능에 대한 비판이 아니에요. 법정 휴식 시간일 뿐이죠.","다른 사람에게 주인공 자리를 양보하는 날이면 기적 관리 부서가 특별 개장합니다.","보이지 않는 왕관도 소품일 뿐이에요. 그런데 당신은 보험부터 들었군요.","겸손은 열린 창문과 같습니다. 그런데 당신은 극장 커튼을 달고 전망 구경료까지 받으시는군요.","다른 사람을 밝히려면 때로 한 걸음만 물러서면 됩니다. 당신은 조명 기계를 더 크게 만드는 쪽을 택했군요.","빛은 왕관보다 나누기 좋습니다. 당신은 전구에 왕관을 씌우고 균형이 회복됐다고 선언하셨군요.","눈부시지 않게 빛나려면 그늘의 자리도 남겨야 합니다. 그런데 당신은 '예약석' 안내판을 세워 두셨군요.","빛은 누구의 소유도 아닙니다. 당신의 홍보팀은 아직 이 사실에 관한 입장문을 쓰고 있군요.","진정한 위대함은 때로 한발 물러날 줄 아는 데서 드러납니다. 당신은 자신을 제외한 모두를 물러나게 했군요.","등대는 배를 안내하지 사인을 해 주는 곳이 아닙니다. 당신은 벌써 친필 서명 카드를 준비 중이시네요."],"roast":["당신의 자존심은 식탁에 의자 하나를 더 요청해요. 식당은 단체 손님으로 등록했습니다.","스스로 소박하다고 하죠. 그 소박함에는 로고와 슬로건, 홍보팀까지 있어요.","거울은 당신이 오기도 전에 알아봅니다. 결국 휴가를 신청했어요.","친구가 성공하면 축하한 뒤 시상식 사회자를 자청해요. 초청받지도 않았는데요.","당신이 중심이 아닌 대화가 시작되면 비상 절차가 발동됩니다. 교환실은 전화를 받지 않아요.","너그러움 뒤에는 열두 쪽짜리 감사 인사 내규가 있어요. 서명자는 물론 당신이죠.","셀카가 외장 기억 장치가 됐어요. 휴대전화는 풍경이 뭔지도 잊어버렸습니다.","당신의 겸손이 책을 냈어요. 헌사만으로 표지 전체를 채웠습니다.","특보입니다. 당신의 셀카가 개인 기념물로 지정됐습니다. 사진 갤러리에서 가이드 투어를 시작하는군요.","당신은 칭찬을 찾아다니지 않습니다. 그건 너무 평범하죠. 예약제로 운영되는 칭찬 접수 창구를 열었으니까요.","당신의 자아가 대기실에 들어가더니 의자를 '왕실 관람석'이라 이름 붙이고 접수번호 대신 초상화를 나눠 줬습니다.","거울이 이상 징후를 보고했습니다. 사흘 동안 아무도 당신이 가장 좋아하는 옆모습을 알아보지 못했답니다. 비상대책반을 여셨군요."]},"roastMy":["사자자리인 당신은 방에 들어가는 게 아닙니다. 개관식을 여는 거죠. 조명과 시선의 각도, 관객 반응까지 살핍니다. 가족 점심 식사도 연례 기자회견이 돼요. 친척들은 의무적인 칭찬을 동시통역해 달라고 요청했습니다.","당신은 칭찬받기를 좋아하지만 이제 잘했어요만으로는 부족해요. 근거와 날짜, 증인 두 명의 서명이 필요하죠. 칭찬이 도착하자 표현이 마음에 안 든다고 이의를 제기합니다. 당신의 법무팀 이름은 바로 나예요.","당신의 너그러움은 무척 커요. 특히 홍보 포스터가 붙어 있을 때요. 디저트를 사고 사진을 찍고 감사에 관한 연설을 합니다. 상상 속 박수 속에서 케이크는 식어 가죠. 제과점은 다음 후원자에게는 조용히 해 달라고 요청했어요.","당신은 관심받는 걸 싫어한다고 주장해요. 그런데 문을 닫기도 전에 단체 채팅방에 자신의 도착을 알리죠. 자리에 앉자 자기가 없을 때 분위기가 달랐냐고 물어요. 침묵은 별 다섯 개짜리 평가로 기록됩니다.","당신의 셀카는 순간을 담는 게 아닙니다. 왕조의 역사를 기록하죠. 풍경이 뒤에서 나오려 하자 침입자라며 잘라 버립니다. 노을마저 당신 미소의 배경이 됐어요. 노을은 불공정 경쟁에 대한 이의 신청을 준비합니다.","당신의 자존심은 보통 회의실에 들어가지 않아요. 의사일정과 연단, 개회 1분 기립박수를 요구하죠. 안건은 종이컵 고르기였어요. 종이컵들이 위원회를 탈퇴했습니다.","당신은 소박함을 꿈꾸지만 우아하고 눈에 띄는 소박함이어야 해요. 편한 옷차림을 정하는 데 세 번 입어 보고 공식 발표까지 하죠. 낡은 스웨터에도 홍보팀이 있습니다. 세탁소는 더 이상 인터뷰를 받지 않아요.","당신이 있는 파티는 환해져요. 직접 조명 밝기를 올리기 때문이죠. 일화를 하나 얘기한 뒤 대사까지 맞춰 재연합니다. 친구들은 대본을 외워 버렸어요. 한 친구는 웃음 연기 대역을 요청합니다.","당신은 칭찬을 국빈 방문처럼 맞이해요. 의전과 미소, 짧은 감사 연설, 잊힌 공적을 다시 강조하는 순서까지 있습니다. 상대는 그냥 화분이 예쁘다고 말했을 뿐이에요. 화분이 대통령 자리를 요구했어요.","당신의 리더십은 의심할 여지가 없어요. 길을 아는 사람에게도 방향을 알려 주니까요. 매장 출구를 알려 준 뒤 효율성을 인정받았는지 확인합니다. 경비원이 상징적인 임무를 맡겼어요. 당신은 즉시 대관식으로 바꿨습니다.","사자자리인 당신은 친구들과 보물찾기에 참가했습니다. 첫 수수께끼부터 지휘권을 잡고 팀 이름을 본인 이름으로 바꾸셨죠. 결국 보물을 자기 주머니에서 찾았습니다. 다른 사람들은 지도를 찾는 동안 당신은 박물관 개관식을 준비하고 있었습니다.","연출 없는 간단한 모임을 열기로 했습니다. 그런데 손님마다 역할을 정하고 당신의 의자 주변 동선까지 그리셨군요. 도착한 사람들은 모두 환영받는 기분이었습니다. 즉흥성만 빼고요. 즉흥성은 아직 옷 보관소에 갇혀 있습니다.","계획 없는 하루를 보내며 자신을 돌아보기로 했습니다. 아침 메뉴를 고른 일부터 책 한 권 정리한 일까지 작은 성취마다 혼자 시상식을 여셨군요. 정오가 되자 상을 일곱 개나 수여했습니다. 하루가 여덟 번째 부문은 사양하네요.","모임에 좋은 소식을 전할 사람으로 뽑혔습니다. 목소리가 영화 예고편처럼 바뀌고 결정적인 순간에 이야기를 멈춰 긴장감을 높이셨죠. 친구들은 진지하게 발표를 기다렸습니다. 알고 보니 새 카드게임이 출시됐다는 소식이었고, 이제 당신의 수상 목록에 올라 있습니다.","손님맞이 솜씨가 대단합니다. 의자를 내주고 그 의자의 역사와 집 안에서의 의미까지 설명하시죠. 손님은 감탄하며 앉습니다. 그런데 당신이 다른 가구 소개 책자까지 꺼냅니다. 그사이 소파는 이사해 버렸군요."]},"virgo":{"classic":{"career":["세부 사항을 살피는 능력 덕분에 프로젝트를 발표하기 전에 더 단단하게 다듬을 수 있어요.","명확한 방식을 좋아하지만 뜻밖의 아이디어가 들어올 여지도 남겨 보세요.","매 단계에 기울이는 정밀한 관심은 동료들에게 신뢰를 줍니다.","기준이 너무 높아질 때는 중요한 것과 사소한 것을 구별하면 한결 수월해져요.","복잡한 업무도 체계적으로 살펴보면 일관된 방향을 찾을 수 있어요.","정리하려는 마음 뒤에는 다른 사람에게 도움이 되고 싶은 진심이 있어요.","당신이 발견하는 작은 개선점은 팀 전체에 큰 변화를 가져올 수 있어요.","분석 능력에 다른 사람을 향한 믿음을 더하면 그 가치가 더욱 커져요."],"love":["세심한 눈길 덕분에 말하지 않은 필요까지 알아차릴 때가 있어요.","소중한 사람의 일상을 더 편하게 만드는 방식으로 애정을 표현하는 편이군요.","잘하고 싶은 마음도 관계에서 예상 밖의 일을 받아들일 때 한결 부드러워져요.","완벽한 말을 찾으려는 노력을 내려놓으면 진심이 더 쉽게 전해져요.","관계는 미완성의 작은 몸짓들이 아름다운 추억이 되면서 만들어지기도 해요.","조심스러운 모습 뒤에는 세심한 경청과 깊은 성실함이 숨어 있어요.","상대의 미묘한 변화를 느낄 때 반드시 분석하기보다 그대로 받아들여 보세요.","잘해 주려는 마음이 즉흥적인 행동도 허락할 때 당신의 다정함이 온전히 드러납니다."],"wellbeing":["정리정돈은 도움이 되지만 휴식까지 과제로 만들지는 마세요.","하루 중 아무 목표 없이 보내는 시간을 조금 남겨 보세요.","최적화한 동선 없이 그저 걷는 즐거움이 시선을 새롭게 할 수 있어요.","모든 게 수정이 필요해 보일 때 잠시 쉬면 관점이 달라질 수 있어요.","화면에서 벗어난 짧은 휴식은 엄격한 생각에 여유를 줍니다.","책임감 강한 당신에게도 고요함을 누릴 자리가 필요해요.","물을 마시거나 자기 속도로 숨을 쉬는 단순한 행동도 일상의 균형에 도움이 됩니다.","행복은 체크한 항목 수로 측정되는 것이 아니에요."],"wisdom":["정확함은 삶에 숨 쉴 공간을 남길 때 더 유익합니다.","세부 사항 하나를 정성껏 살피되 전체를 고치려 할 필요는 없습니다.","균형은 아직 완성되지 않은 것들도 받아들입니다.","방법과 유연함이 만나면 노력은 가벼워집니다.","목록을 전부 끝냈다고 하루의 가치가 정해지지는 않습니다.","완벽하지 않은 것 뒤에도 새로운 가능성이 숨어 있을 수 있어요.","단순한 것은 개선하지 않아도 아름다울 수 있습니다.","끝나지 않은 일을 인정하는 것도 하나의 능숙함입니다."],"roast":["모든 것을 확인하려는 습관이 생각보다 간단한 결정을 무겁게 만들 수 있어요.","아주 작은 차이도 잘 알아차려서 주변 사람들은 쉴 틈이 없을 때가 있어요.","잘 정리하고 싶은 마음 때문에 결과를 즐길 시점을 자꾸 미룰 수 있어요.","어색한 문장을 보면 본래 뜻보다 고치는 일이 더 중요해질 때가 있어요.","지나치게 자세한 목록은 왜 만들었는지조차 잊게 할 수 있어요.","효율성을 중시하는 마음에도 예상 밖의 일이 들어올 여지를 남겨 보세요.","당신의 조언은 매우 구체적이지만 상대가 그만큼 구체적으로 부탁한 것은 아닐 수 있어요.","흠잡을 데 없는 결과를 추구하되 이미 충분히 훌륭한 것을 인정하는 능력도 필요해요."]},"funny":{"career":["사내 메모를 '잠깐 확인만' 하려고 다시 읽으셨군요. 세 번째 수정본이 완벽해졌을 때 회의 날짜는 이미 바뀌었습니다.","동료의 이메일을 다시 읽으며 쉼표 세 개를 대상으로 정밀 평가를 실시합니다.","문서 검토를 부탁받고 원본과 수정 사항 범례, 파일 버전 이름 짓는 방법에 대한 조언까지 돌려주셨군요.","누군가 즉흥적으로 하자고 하면 일정표가 상징적으로 모든 창을 닫습니다.","15분 회의도 번호를 잘못 매긴 문서에서 세상을 구할 절호의 기회예요.","새 절차가 도입됐습니다. 당신은 그 절차를 읽는 절차가 없다는 문제를 즉시 발견하셨네요.","통화 중 적은 메모가 너무 상세해서 상대방이 복사본을 주문하고 싶어 해요.","가장 좋아하는 펜은 아무에게나 빌려주지 않아요. 철저한 비교 끝에 선택한 펜이니까요.","공식 안내입니다. 쉼표 하나라도 자리를 옮기면 당신 부서에 신고해야 합니다. 문장들이 발끝으로 살금살금 걷기 시작했군요.","세 줄짜리 메일을 읽고 목차를 추가하셨군요. 받는 사람이 길을 잃지 않도록 해야 하니까요.","'준비됐나요?' '거의요.' 당신은 아직 업무 매뉴얼에서 '거의'의 정의가 필요한지 검토 중입니다.","새 절차가 흥미롭게 보입니다. 특히 더 나은 절차로 만들 수 있는 지점 여섯 개를 찾아낸 뒤로는요."],"love":["당신의 사랑 고백은 잘 정리된 서비스 같아요. 우산과 버스 시간표까지 미리 생각해 뒀거든요.","누군가 집의 작은 장식 하나를 바꿔도 즉시 알아차립니다. 상대는 당신이 재고 목록을 작성한 줄도 몰라요.","둘만의 저녁을 위해 상대방 취향을 모두 반영했습니다. 이제 남은 건 냅킨이 잘못 접혔다는 말을 어떻게 꺼낼지뿐이군요.","꽃을 선물받으면 감동한 뒤 즉시 가장 알맞은 꽃병을 찾습니다.","깜짝 이벤트는 정말 좋아해요. 단, 달력에 미리 등록하는 예의를 지켰다면요.","진지한 모습 뒤에는 사랑한다는 말을 찬장 문을 고쳐 주는 것으로 표현하는 사람이 있어요.","로맨틱한 메시지에는 사랑스러운 배려와 유용한 설명 세 가지가 들어갑니다. 마지막 설명은 선물의 정확한 위치를 알려 주네요.","당신의 배려에는 수건을 올바르게 접는 법에 관한 작은 안내문도 포함될 수 있어요.","상대방이 좋아하는 음료와 적정 온도, 앉기 편한 자리까지 기억합니다. 빠진 건 깜짝 놀랄 즐거움뿐이군요.","다정한 고백은 '당신 생각을 했어요'로 시작해 더 좋은 데이트를 만드는 상세 제안서로 이어집니다.","사랑하는 사람의 새로운 습관을 바로 알아차리십니다. 상대방은 컵 위치만 바꿨다고 생각했는데요.","연인이 작은 고민을 털어놓자 귀 기울여 듣고 섬세함의 순서대로 정리한 해결책 세 가지를 제시하셨군요."],"wellbeing":["휴식 공간을 너무 깔끔하게 정리해서 쿠션이 움직일 엄두를 못 냅니다. 쉬는 사람조차 앉아도 되는지 허가를 기다리는군요.","산책하려고 하면서 가장 단순한 길을 고르기 위해 경로 세 개를 비교합니다.","담요를 덮고 앉아야 할 때 정확히 접어 제자리에 놓고 있어요.","잠시 쉴 때도 예정 시간보다 2분 늦게 시작했다는 사실을 머릿속에 적어 둡니다.","차 한 잔도 당신 손에서는 받침 접시의 위치까지 정확한 실험이 돼요.","정리하고 싶은 마음 뒤에서 소파는 첨부파일 없는 초대장을 보냅니다.","산책이 도움이 돼요. 나뭇잎 하나가 제자리에 없어도 괜찮다는 걸 받아들인다면요.","당신의 평온함에는 모든 알림을 분류했다는 만족감도 포함됩니다.","수건을 크기별로 정리했습니다. 이제 욕실이 손님은 당신 하나뿐인 매장 같습니다.","가상의 마음속 날씨입니다. 선반 위는 맑음, 찬장 북쪽에는 옅은 먼지, 간식 시간 전 처리 예정.","쉬려고 현관의 신발을 줄 맞춰 놓으셨군요. 신발끈들이 마침내 집단 규율을 이해했네요.","청소 없는 저녁을 선언했지만 부스러기에 예외를 두고 손자국에도 예외를 추가하셨습니다."],"wisdom":["좋은 하루에는 작은 흠도 어울립니다. 하늘은 열리기 전에 교정 작업을 거치지 않으니까요.","인생이 목차를 빼먹어도 믿어 볼 수 있어요.","어지러움이 늘 비상사태인 건 아니에요. 가끔은 쿠션 하나가 옮겨졌을 뿐이죠.","체크칸 하나가 비었다고 우주가 자동으로 조사에 착수하진 않아요.","쉼표가 잘못 찍혀도 커피 맛은 좋을 수 있어요.","완벽함 뒤에는 그냥 앉아도 되는 의자 하나가 숨어 있을 때가 있어요.","돌발 상황들은 당신의 절차서를 읽지 않아요. 예의가 없죠.","중요한 일이라도 나중에 확인이라는 폴더를 받아들일 수 있어요.","작은 디테일 하나가 완벽하다고 해서 흔들리는 아이디어가 바로잡히는 건 아닙니다. 'ㅣ' 위의 점이 건축가는 아니니까요.","작은 실수를 받아들인다는 건 인생이 여백에 메모 하나를 남기도록 지우개를 내려놓는 일입니다.","세상은 쉼표 하나가 삐뚤어져도 굴러갑니다. 그래도 다음 문단까지 가는 길을 찾죠.","가장 중요한 것에는 항상 라벨이 붙어 있지 않습니다. 그것을 알아보려면 인내가 필요합니다."],"roast":["당신의 비판적인 눈은 쉬지 않아요. 휴가 포스터마저 레이아웃 수정 의견을 받습니다.","장보기 목록에는 범례와 분류표, 돌발 상황 전용 작은 칸이 있습니다. 뜻밖의 상황에도 라벨이 붙었군요.","대충이라는 말만 들어도 수평계를 꺼내고 싶어집니다.","누군가 이 정도면 됐다고 하면 당신은 협상 시작 신호로 받아들입니다.","빈 상자에도 '언젠가 넣을 물건'을 표시해 두셨군요. '즉흥적인 아이디어' 상자는 꼼꼼하게 봉인돼 있습니다.","공손한 미소 뒤에서는 보이지 않는 평가표가 사람들에게 점수를 매깁니다.","취미 활동 표에는 '재미있음', '매우 재미있음', '조건부 재미있음'이 구분돼 있습니다. 취미들이 판정을 기다리는군요.","당신의 휴식에는 출퇴근 기록까지 필요할 만큼 정확한 일정이 있습니다.","주말 일정표에 '아무 계획 세우지 않기' 칸이 있습니다. 이미 일정표 검토용으로 예약돼 있군요.","목록을 만들기 위한 목록을 준비하셨군요. 세 단계쯤 내려가자 연필이 독립을 선언했습니다.","가상의 가정 설문 결과, 물건 100%에 라벨이 붙었습니다. 고양이만 자기 분류를 공개하지 않고 있습니다.","수납 상자 비교표를 만드셨군요. 상자들은 거기에 갇혀도 되는지 망설입니다."]},"piquant":{"career":["당신의 완벽주의는 간단한 이메일 하나를 허가받아야 하는 공사장으로 만들었어요. 첫 인사말은 아직 건축 허가를 기다립니다.","동료의 쉼표를 판사처럼 엄숙하게 고칩니다. 키보드는 변호사를 요청했어요.","동료의 발표 자료를 검토하다 이름 표기까지 고치셨군요. 회의는 행정적인 맞춤법 논쟁으로 시작됐습니다.","업무가 끝나도 다시 열어 정말 완료라고 불러도 되는지 확인해요. 완료라는 단어가 사표를 냈습니다.","간단한 사내 메모가 당신의 품질 관리를 거쳤습니다. 불일치 세 개를 찾아내고 기록을 위한 네 번째 단계까지 새로 만드셨군요.","완벽한 업무 방식 뒤에서는 감사위원회가 감사위원회를 감시합니다. 감사 담당자는 또 당신이죠.","마감 기한을 존중하려면 여유 시간과 경고, 경고에 대한 경고 계획까지 있어야 해요. 일정표는 숨어 버렸습니다.","제목 글꼴 때문에 회의가 멈췄어요. 정작 회의 안건이던 긴급한 일은 이미 지나갔습니다.","속보입니다. 팀이 흠잡을 데 없는 문서를 전달했습니다. 당신이 보이지 않는 공백 두 개의 불일치를 찾아 축하 행사가 연기됐습니다.","절차를 고치는 모습이 틀린 음표를 지적하는 지휘자 같습니다. 연주자는 지친 복사기들이고요.","사내 공지의 문구를 검토하는 데 발표할 결정보다 더 오래 걸렸습니다. 공지가 자기 존재를 포기하고 싶어 하네요.","당신의 이상적인 회의 운영법입니다. 안건 확인, 문법 승인, 제목 점검. 본론 논의는 선택 사항입니다."],"love":["당신의 다정함은 은근한 교정으로 나타나요. 꽃다발은 꽃병 심사를 받기 전까진 아름다웠습니다.","고민을 들어주면서 품질관리 책임자처럼 행동해요. 상대는 위로를 원했는데 개선 계획서를 받았습니다.","로맨틱한 문자에 감동한 뒤 오류 두 개를 찾아냅니다. 사랑의 신은 재교육 통보를 받았어요.","깜짝 계획이 있으면 시간과 장소, 준비 수준을 묻습니다. 신비감은 참석을 취소했습니다.","쿠션이 대칭으로 놓여 있으면 둘만의 저녁은 성공입니다. 감정들은 외투 보관소에서 기다려요.","세심한 배려 뒤에는 다정한 행동의 일관성을 평가하는 보이지 않는 양식이 있어요. 즉흥성 칸은 비활성화돼 있습니다.","상대의 귀여운 결점도 다섯 단계로 해결할 수 있으면 참을 수 없어요. 로맨스는 기술 지원 요청을 열었습니다.","당신의 마음은 닫힌 게 아닙니다. 주제와 날짜, 우선순위별로 분류돼 있을 뿐이죠. 열쇠는 공유 폴더에 있습니다.","당신은 상대의 습관을 관찰하는 게 아니라 비교 연구를 발표합니다. '사랑스러운 작은 버릇' 편에 부록만 46개군요.","낭만적인 선물과 함께 보관 지침과 세부 선택의 이유를 설명합니다. 감동은 '자유 모드' 버튼을 찾고 있습니다.","다정한 고백에서 사소한 불일치를 찾아내셨군요. 축하합니다. 이제 그 감정은 이전 버전과의 적합성 인증을 받았네요.","'좋은 시간 보내셨어요?' '네, 하지만 후반부 구성은 좀 더 나을 수 있었죠.' 데이트가 교육 자료 보관소로 들어갑니다."],"wellbeing":["휴식 공간을 상상 속 먼지 연구소처럼 정밀하게 청소하셨군요. 그리고 더러워질 가능성이 있는 모든 활동을 금지했습니다.","누워 있기 전에 쿠션을 정리하고 정렬 상태를 확인합니다. 소파는 중재자를 요청했어요.","침묵에 마음이 편안해졌다가 살짝 기운 시계를 발견합니다. 평온함은 연기됐어요.","산책하면서 거리와 보도를 비교하고 경로를 최적화합니다. 신선한 공기마저 점수를 받아요.","따뜻한 음료로 쉬려 했는데 컵 비교 분석을 시작합니다. 심사하는 동안 음료는 식었습니다.","좋은 의도 뒤에서 휴식은 불시 점검으로 변해요. 담요는 신분증이 없습니다.","할 일 없는 주말은 불안해요. 즐거움을 어디에 배치할지 적힌 칸이 없거든요. 일요일은 직무기술서를 기다립니다.","휴식하려는 의지는 훌륭해요. 다만 잊지 않으려고 알림을 세 개나 설정했군요.","옷장이 너무 질서정연해서 양말마다 구역 번호가 붙었습니다. 짝 잃은 양말은 외국으로 추방됐군요.","고객 후기입니다. '청소는 완벽하지만 지정된 위치를 벗어난 물건을 찾을 수 없어요.' 당신은 축척이 표시된 도면으로 답했습니다.","테이블을 닦고 걸레를 닦고 걸레가 놓였던 자리를 닦으셨군요. 순환 작업은 이제 사람 없이도 계속될 지경입니다.","저녁 루틴에는 정리 단계 네 개와 휴식 하나가 있습니다. 휴식이 정리를 방해하지 않도록 다른 시간으로 옮겨졌군요."],"wisdom":["사소한 부분은 유용한 손님이지 집주인이 아닙니다. 그런데 당신은 안방까지 내주셨군요.","당신은 완벽함을 찾는 게 아니에요. 결점의 이웃집까지 추적하는 거죠.","혼란이란 가끔 양말 하나가 옮겨진 일일 뿐이에요. 당신의 보고서는 스무 쪽이지만요.","사소한 것 하나만이라고 말하는 순간 기술팀은 현장에서 대피합니다.","쉼표 하나가 세상을 지배하지는 않아요. 쉼표는 아직 그걸 모르는 모양입니다.","마음의 평화 뒤에서 검사관 하나가 구름의 접힌 모양까지 확인합니다.","실수는 인간적인 일이에요. 당신은 인간 인증 양식을 먼저 검토하자고 했어요.","예상 못 한 일은 설문지를 작성하지 않았어요. 그래서 출입을 거절합니다.","완벽함은 항상 마지막 수정을 약속합니다. 당신은 무기한 구독을 신청하셨군요.","사소한 부분이 삐져나왔다고 핵심이 사라지는 건 아닙니다. 당신은 돌출 길이를 재는 위원회를 열었군요.","아주 작은 실수도 교훈이 될 수 있습니다. 당신은 그 1밀리미터를 주제로 연례 학회를 여셨네요.","약간의 불완전함이 개성을 만들기도 합니다. 자동 교정기가 정식 이의신청서를 냈지만요."],"roast":["우선순위 목록 안에 우선순위를 어떻게 분류할지 정하는 항목이 있습니다. 파일철이 정부 입성을 준비하는군요.","당신은 목록을 그만 만들 이유까지 목록으로 작성했어요. 코팅까지 마쳤죠.","비스듬한 액자 하나를 보면 조사위원회가 열립니다. 못은 무죄를 주장해요.","누군가 틀린 표현을 쓰면 마음속에서 외교 관계를 중단합니다.","즉흥적인 저녁은 물류 체계 파괴 행위예요. 보드게임은 허가서를 기다립니다.","겉으로 차분한 모습 뒤에서 검사관이 수건들의 출석부 서명을 확인하고 있어요.","남들은 쉬고 있는데 당신은 그 휴식의 품질을 평가하고 수정안을 제안합니다.","병에 라벨을 붙인 뒤 여분 라벨에도 라벨을 붙였습니다. '라벨'이라고 쓰인 라벨이 이제 액자 속에 모셔져 있군요.","초대 손님 목록에는 '예상 친목도'와 '실제 친목도' 칸이 있습니다. 친구들이 데이터가 됐군요.","라벨 보관 서랍에 붙일 라벨까지 만드셨군요. 새로운 범주인 '분류 체계 위기'가 태어났습니다.","표 관리 현황표가 원래 표보다 더 커졌습니다. 이제 각 열과 연례 면담도 계획하고 있습니다.","당신은 계획을 세우는 게 아닙니다. 미래 계획을 승인할 계획을 준비합니다. 우연에는 더는 출입증이 없군요."]},"roastMy":["처녀자리인 당신은 집을 정리하는 게 아닙니다. 하나의 영토를 통치하죠. 모든 물건에는 주소와 기능, 이동했을 때의 처벌이 있어요. 손님이 엉뚱한 곳에 외투를 놓습니다. 디저트가 나오기도 전에 징계위원회가 열렸어요.","당신은 이웃에게 인사하듯 자연스럽게 오타를 고쳐요. 애정 어린 메시지에 작은 오류가 있으면 왜 감동했는지 거의 잊을 지경이죠. 하트를 보낸 뒤 수정본을 전달합니다. 키보드는 행정적 분리를 요청했어요.","당신의 할 일 목록에는 표지와 장, 하위 목록 부록까지 있어요. 체크 한 번으로 세계 질서를 회복한 듯 뿌듯해하죠. 그 순간 새 업무 두 개가 나타납니다. 목록이 독자적인 관료 조직을 세웠어요.","당신은 제대로 하는 걸 좋아한다고 말합니다. 다른 사람들은 의자 하나 옮기려면 서류를 제출해야 한다고 말하죠. 절차를 간단하게 만들겠다며 짧은 양식을 새로 제안합니다. 열네 쪽짜리예요.","당신은 모든 메시지를 너무 깊게 분석해서 간단한 알겠어요도 수수께끼가 됩니다. 왜 완벽하다는 말이 아닐까, 왜 마침표를 찍었을까, 왜 이 시간일까? 대화는 끝났지만 당신은 이제 의회 조사위원회를 열었어요.","당신이 생각하는 즉흥성이란 예정된 활동 두 개의 순서를 바꾸는 거예요. 잠시 설레다가 일정을 원래대로 돌려놓죠. 운명조차 회의록을 받습니다. 운명은 수신 확인을 요청한 적이 없어요.","당신은 남을 돕는 걸 좋아해요. 특히 애초에 어떻게 했어야 하는지 설명할 수 있을 때요. 도움은 효율적이고 자세하며 문서와 도표까지 첨부돼 있죠. 사람들은 진심으로 고마워합니다. 그리고 자기 서랍을 숨겨요.","아무 의무 없는 하루를 꿈꾸나요? 먼저 일정을 비우고 의무 없는 활동 목록을 만든 뒤 그 시간을 즐기라는 알림을 설정합니다. 정오에는 휴식 효율을 감사합니다. 해먹은 소송을 예고했어요.","당신의 부엌은 너무 잘 정리돼서 숟가락 하나가 없으면 전국 경보가 울릴 지경이에요. 그런데 숟가락은 제자리에 조금 돌아가 있을 뿐이죠. 누군가 일부러 그랬다고 의심합니다. 식기세척기는 정치적 망명을 요청했어요.","당신은 누구도 판단하지 않는다고 엄숙하게 말해요. 단지 관찰하고 분류하고 비교하고 머릿속으로 건설적인 평가를 작성할 뿐이죠. 친구는 발표가 명확했는지 한마디만 물었어요. 당신은 프로젝터 사용 시간을 연장해 달라고 합니다.","처녀자리인 당신은 친구들과 산책을 계획했습니다. 경로와 대안 두 가지, 차이를 기록할 종이까지 준비했죠. 산책은 문제없이 끝났습니다. 길에 나뭇잎 하나가 떨어진 것만 빼고요. 다음 회의 안건에 '예상 밖의 낙엽'을 추가하셨습니다.","완전히 즉흥적인 선물을 준비하고 싶었습니다. 포장지를 비교하고 크기를 확인하고 매듭 방식 세 가지를 시험했죠. 선물은 완벽하게 포장돼 사랑스러웠습니다. 놀라움은 결국 사용 설명서와 함께 도착했군요.","이번에는 다른 사람이 요리하게 두기로 하셨습니다. 미소 지으며 과정을 지켜보다 작은 개선점 하나를 제안하셨고, 그 제안이 다섯 개로 늘어났습니다. 음식은 훌륭했고 아무도 의심하지 않았죠. 주걱은 다음 해 희망사항으로 '자율성'을 적었습니다.","도서관에서 책 한 권이 살짝 비뚤어진 걸 발견했습니다. 그것을 바로 세운 뒤 양옆 책까지 맞추셨죠. 10분 후에는 책장 전체가 보이지 않는 감독관의 검사를 받은 듯했습니다. 사서는 현장 점검이 나온 줄 알았습니다.","아무것도 평가하지 않는 하루를 보내기로 했습니다. 커피 맛과 이동 경로, 음악에 점수를 매기고 싶은 충동을 참으셨죠. 저녁에는 이 발전을 세 쪽짜리 결산 보고서로 칭찬했습니다. 즉흥성은 10점 만점에 9점을 받았군요."]},"libra":{"classic":{"career":["당신의 균형 감각은 직장에서 의견이 부딪힐 때 한 발 물러서서 보는 힘이 됩니다.","서로 다른 관점을 하나로 모으는 데 능숙해요. 명확한 방향을 결정하는 능력도 더해 보세요.","조화를 추구하는 마음은 유용한 의견 차이까지 없애지 않는다면 프로젝트에 도움이 됩니다.","여러 해법이 좋아 보일 때 중요한 기준부터 정하면 앞으로 나아가기 쉬워요.","신중한 표현은 어려운 결정을 둘러싼 협력을 도울 수 있어요.","외교적인 태도 뒤에는 자기 생각을 우아하게 지킬 수 있는 힘이 있어요.","모든 대안을 비교하지 않아도 된다고 받아들이면 업무 선택이 한결 가벼워집니다.","미적 감각은 세련된 발표와 독창적인 비전에 힘을 더할 수 있어요."],"love":["조화를 바라는 마음은 서로 존중받는다고 느끼는 대화를 만들어 줍니다.","아름다운 순간을 만드는 걸 좋아하지만 그 순간의 소박함도 소중할 수 있어요.","모두에게 좋은 인상을 주려는 마음을 내려놓으면 자기 취향을 더 자유롭게 표현할 수 있어요.","솔직해야 하는 대화에서도 당신의 부드러움은 진심을 전하는 데 도움이 돼요.","균형 잡힌 관계는 받아들이는 차이 속에서도 자라납니다.","은은한 매력 뒤에는 상대를 깊이 이해하려는 마음이 있어요.","일상의 작은 망설임보다 함께하는 사람을 향한 관심이 더 중요해요.","공정함에 대한 감각은 다정함을 통해 더욱 개인적인 의미를 얻어요."],"wellbeing":["균형을 찾는 마음이 자신의 필요를 존중하는 생활 리듬으로 이끌 수 있어요.","아름다운 장소를 좋아하지만 편안함을 느끼는 데 꼭 화려한 공간이 필요한 건 아니에요.","모두를 만족시키려는 마음 대신 자신의 평온함을 먼저 살펴도 괜찮아요.","선택지가 너무 많아질 때 잠시 자극에서 벗어나면 원하는 것이 분명해질 수 있어요.","조화로운 장소를 걷다 보면 작은 것들을 새롭게 바라보게 돼요.","다른 사람에게 늘 열려 있는 당신에게도 혼자만의 시간은 소중해요.","부드러운 음악이나 밝은 공간처럼 아름다움을 느끼는 작은 즐거움이 휴식에 도움이 됩니다.","마음의 평화를 위해 주변 모두가 같은 의견일 필요는 없어요."],"wisdom":["절대적인 확신 없이도 선택할 용기를 낼 때 균형이 자랍니다.","모든 목소리를 듣되 자신의 목소리를 잊지 마세요.","아름다움이 진실을 대신할 수는 없지만 진실로 가는 문을 열 수는 있습니다.","평화를 위해 침묵해야 할 때도 솔직함의 자리를 남겨 두세요.","완벽하지 않은 결정도 끝없는 기다림보다 나을 수 있어요.","망설임 뒤에는 잘하고 싶은 진심이 있을 때가 많아요.","차이가 조화를 없애는 건 아니에요. 오히려 깊이를 더합니다.","부드럽게 고른 선택도 분명한 선택입니다."],"roast":["비교를 지나치게 좋아하면 단순히 취향을 말하면 될 선택까지 미루게 돼요.","모두를 배려하려다 자기 생각이 잘 들리지 않을 때가 있어요.","좋은 분위기를 지키고 싶은 마음 때문에 꼭 필요한 대화를 피할 수 있어요.","두 선택지가 비슷할 때 즐기는 시간보다 비교하는 시간이 더 길어질 수 있어요.","지나치게 공손한 태도는 원치 않는 일에도 동의하는 듯 보이게 할 수 있어요.","매력적인 모습 뒤에는 분명한 답이 필요한 진짜 망설임이 있어요.","주변의 의견은 생각을 풍부하게 하지만 결정을 대신할 필요는 없어요.","대화가 조금 불편해져도 조화를 사랑하는 당신의 가치는 변하지 않아요."]},"funny":{"career":["당신의 이상적인 회의는 모두가 동의할 때 끝나요. 그러니 다음 분기까지 계속될 수 있겠군요.","제안을 승인하기 전에 동료 네 명에게 물어보셨군요. 다섯 번째 동료는 아무도 소외감을 느끼지 않았는지 확인하는 담당입니다.","동료들이 다투면 곧바로 중재자가 돼요. 화해를 위한 음료까지 이미 준비했죠.","두 팀이 업무 하나를 두고 다투자 우아한 절충안을 내놓으셨군요. 양쪽 모두 스테이플러 반쪽씩을 들고 돌아갑니다.","빨리 결정해 달라는 요청은 당신에게 거의 운동 경기 같은 도전이에요.","외교적인 미소 뒤에는 아마도라는 말로 시작하는 이메일 초안 열두 개가 있어요.","합의를 위한 회의가 또 다른 회의를 열자는 만장일치 투표로 끝났습니다. 적어도 그 결정에는 반대가 없겠네요.","모든 의견을 듣는 재능은 엄청나요. 시계마저 자기 의견을 내기 시작합니다.","직장에서 즐겨 하시는 말은 '두 아이디어 모두 장점이 있어요'입니다. 문제는 둘이 서로 완전히 모순된다는 거죠.","가상의 팀 설문입니다. 동료 열두 명에게 의견을 물었고 갈등은 없었습니다. 프로젝트는 아직 의견 수렴 단계군요. 당신은 이것을 평화로운 출발이라고 부릅니다.","'결정 좀 내려 주시겠어요?' '물론이죠.' 그러고는 왜 결정을 미루고 싶은지 모두가 이야기하는 회의를 제안하시는군요.","팽팽한 대화를 재치 있게 누그러뜨리는 재능이 있습니다. 끝날 즈음에는 프린터도 종이를 나누는 데 동의할 정도죠."],"love":["당신의 로맨스는 촛불 저녁과 산책 사이에서 망설여요. 마음속으로 둘 다 예약합니다.","낭만적인 산책과 아담한 공연 사이에서 고민하다 완벽한 순간을 찾으셨군요. 상상 속 음악과 함께하는 산책입니다.","선물 하나를 고르는 과정이 너무 정교해서 전시회를 열어도 될 지경이에요.","어디서 먹을지 정해 달라는 말을 들으면 깜짝 시험을 치르는 사람처럼 품위 있게 웃습니다.","당신의 미적 감각은 작은 배려를 영화 장면으로 만듭니다. 꽃다발 하나에도 전용 사운드트랙이 필요하겠네요.","타고난 매력 뒤에서는 좋은 밤 인사를 어떤 방식으로 할지 보이지 않는 위원회가 토론 중이에요.","다툼이 싫어서 정반대 의견 둘을 모두 놀라울 만큼 부드럽게 설명합니다.","매력이 너무 자연스러워서 '좋은 밤 되세요'를 어떻게 말할지 10분간 망설이는 모습까지 사랑스럽게 만드시는군요.","낭만적인 초대 문구를 세 가지 말투로 연습했습니다. 마지막 문구가 너무 매력적이라 앞의 두 개를 버릴 수 없었군요.","우아한 쇼윈도 하나가 멋진 데이트 아이디어를 줍니다. 다음 쇼윈도에서는 더 좋은 생각이 떠오르죠. 산책은 이제 아이디어 전시회가 됐습니다.","저녁 분위기에 어울리는 꽃을 선물하셨군요. 상대방은 드디어 선물하기로 결정했다는 사실을 가장 반가워합니다.","멋진 풍경을 바라볼 벤치 하나를 고르는 순간까지 매력이 넘칩니다. 두 자리가 모두 좋아 결국 서서 감상하시네요."],"wellbeing":["당신의 휴식은 분위기 선택에서 시작해요. 향초 세 개를 켠 뒤에도 조명이 마음에 드는지 고민합니다.","산책을 계획하고 아름다운 공원 두 곳 중 어디가 더 좋을지 10분 동안 비교해요.","소파의 쿠션은 절대 완벽한 위치에 있지 않아요. 마음속에서 쿠션과 협상합니다.","친구가 뭘 하고 싶냐고 물으면 진심으로 편한 대로 하라고 답합니다. 무서운 말이죠.","잔잔한 음악을 틀려다 똑같이 훌륭한 곡들 사이에서 어려운 결정을 내려야 해요.","평화를 사랑하지만 꽃병의 의견까지 물어보지 않고 결정할 때도 있어야 해요.","예쁜 물건은 마음을 쉬게 해 줍니다. 그러다 머릿속에서 방 전체를 다시 배치하죠.","완벽한 오후라면 어떤 결정도 할 필요가 없겠죠. 그 오후를 어떻게 보낼지부터 결정해야 하지만요.","평온한 공간을 만들려고 액자 세 개를 다시 배치했습니다. 이제 안락의자는 어느 방향을 보고 쉬어야 할지 모르겠군요.","당신의 휴식 의식은 쿠션 줄 맞추기로 시작됩니다. 소파 양쪽 끝이 평화협정에 서명해야 비로소 편안해지죠.","가상의 마음속 날씨입니다. 조화로운 분위기, 작은 불균형이 발견되면 꽃병이 이동할 가능성 있음.","꽃다발 하나면 방이 한결 부드러워질 것 같습니다. 열 번 시도한 끝에 가장 좋은 자리를 찾았군요. 처음 있던 바로 그곳이었습니다."],"wisdom":["균형을 맞춘다고 과자 하나마다 투표할 필요는 없어요.","두 가지 다 좋아해도 가게 문 닫기 전에 하나는 고를 수 있어요.","좋은 취향을 증명하는 데 증인 열두 명은 필요 없습니다.","문 하나를 고른다는 건 나머지 문을 모두 열어 보지 않는다는 뜻입니다. 안내책자는 갖고 있어도 손잡이까지 다 붙들 수는 없어요.","개인의 의견 하나가 자동으로 국제회의를 부르지는 않아요.","모든 망설임 뒤에는 가끔 소파가 기다리고 있을 뿐이에요.","서로 다른 생각은 공존할 수 있지만 굳이 버스를 운전할 필요는 없어요.","무작위로 고르는 것도 선택이에요. 주사위라면 당신보다 잘 설명하겠죠.","균형을 지키려면 가끔 신발을 모두 비교하는 대신 앞으로 걸어야 합니다.","좋은 선택지는 둘 다 아름다울 수 있습니다. 중요한 건 고른 쪽을 즐기면서 다른 쪽에 편지를 쓰지 않는 것입니다.","망설임은 생각할 시간을 줍니다. 하지만 머릿속에 아파트까지 임대해 줄 필요는 없습니다.","움직이지 않는 저울이 지혜롭다는 뜻은 아닙니다. 때로는 접시 하나를 비우길 기다릴 뿐이죠."],"roast":["식당에서 메뉴를 세 가지로 좁혔습니다. 역사적인 진전이지만 직원은 이미 퇴근했군요.","다툼을 피하는 솜씨가 너무 좋아서 길을 막는 문에게도 사과합니다.","식당 메뉴는 당신을 잘 알아요. 여러 결말이 있는 소설처럼 읽으니까요.","취향을 물으면 두 가지의 장점을 다 설명하고 정작 질문은 잊어버려요.","주변에서 다툼이 시작되면 중재팀을 출동시키고 냅킨부터 나눠 줍니다.","페인트 색 두 가지 사이에서 너무 오래 고민해서 벽이 '임시 흰색'을 좋아하게 됐습니다.","예쁜 물건을 너무 좋아해서 클립마저 우아한 선을 가져야 해요.","당신의 배려는 전설적이에요. 거울이 잘못 비춘다는 말도 아주 정중하게 전할 수 있죠.","식당 세 곳의 메뉴를 비교했습니다. 첫 식당은 당신이 생각하는 사이 리모델링에 들어갔군요.","페인트 가게에서 '부드러운 베이지'와 '차분한 베이지' 사이에 망설입니다. 점원은 그 두 나라가 존재하는 줄 몰랐군요.","당신에게 이상적인 메뉴는 선택지 하나뿐입니다. 그래도 다른 선택지를 실수로 빠뜨렸는지 확인하시겠죠.","우산 하나 고르는데 20분을 쓰셨군요. 비는 그쳤지만 색깔은 이제 거의 결정됐습니다."]},"piquant":{"career":["당신의 우유부단함은 스테이플러 고르기를 외교 정상회담으로 만들었어요. 대표단은 폐회 날짜를 요구합니다.","세 단어짜리 이메일을 보내기 전에 동료 여덟 명의 의견을 구해요. 답장이 질문보다 먼저 도착했습니다.","당신의 외교술은 업무 절차를 둘러싼 다툼을 45분짜리 대화 모임으로 바꿨습니다. 절차 자체는 탈의실에 놓고 왔군요.","상사가 결정을 요구하면 어느 쪽에도 기울지 않은 비교표를 제출합니다. 표의 열들마저 결론을 거부해요.","동료 모두가 의견을 들었다고 느끼게 하고 싶으셨군요. 그래서 의견 수렴 순서를 정하는 의견 수렴까지 열었습니다. 프로젝트는 아직 차례를 기다립니다.","모두에게 동의하는 미소 뒤에서 부서 전체가 당신의 진짜 생각을 찾고 있어요. 사건은 미학 분야로 분류됐습니다.","당신과 협상하면 너무 평화롭게 끝나서 무엇이 결정됐는지 아무도 모릅니다. 회의록에는 '건설적인 분위기'만 남았군요.","당신의 외교 실력은 완벽해요. 아무것도 결정하지 않기로 모두의 합의를 얻었죠. 회의록이 감사 인사를 보냅니다.","공식 공지입니다. 팀에서 합의위원회를 만들었습니다. 정작 위원회는 '합의'라는 말의 정의에도 합의하지 못했군요.","갈등을 너무 잘 피해서 불일치는 '병행 제안'으로 이름을 바꿉니다. 회의 끝에 서로 맞지 않는 결정 두 개가 남았군요.","세 단어짜리 문구 하나를 승인하려고 동료 열두 명에게 물었습니다. 열세 번째가 소외감을 느끼자 처음부터 다시 시작합니다.","당신의 중재 솜씨라면 스테이플러와 종이도 화해시키겠죠. 하지만 부탁받은 보고서는 여전히 빈칸입니다."],"love":["당신의 매력은 길을 묻는 사람에게까지 작동해요. 그 사람은 가상의 초대장 세 장을 들고 돌아갑니다.","데이트 장소 두 곳에서 망설이다가 세 곳, 다섯 곳으로 늘려요. 달력은 주말 양육권을 요청했습니다.","낭만적인 저녁은 편한 대로 하세요라는 말로 시작해요. 마흔 번 제안하는 사이 식당이 문을 닫았습니다.","너무 섬세하게 유혹해서 초대장이 미술 전시 같습니다. 아름답고 조명도 완벽하지만 무슨 뜻인지 도무지 알 수 없네요.","다툼이 생길 것 같으면 놀라운 우아함으로 화제를 바꿔요. 방금 스탠드를 칭찬했군요.","사랑에 관한 망설임이 데이트 아이디어 두 개를 연속극으로 바꿨습니다. 예고편에서도 장소를 공개하지 않는군요.","매력을 너무 쉽게 나눠 주다 보니 당신의 미소가 출시 홍보 캠페인처럼 보입니다. 정작 사랑이라는 제품은 아직 등장하지 않았군요.","당신의 마음은 완벽하게 균형 잡힌 동화를 꿈꿔요. 등장인물들은 표지 고르기가 끝나길 기다립니다.","낭만적인 아이디어 두 개를 고르지 못하고 상상 속 결승전을 여십니다. 각 후보가 없는 심사위원 앞에서 매력을 발표해야 하죠.","당신의 유혹은 고급 미술관 같습니다. 전부 아름답지만 진짜 고백에 도달하려면 안내 화살표를 따라가야 하죠.","드물게 우아한 초대장을 준비했습니다. 글도 완벽하고 종이도 완벽합니다. 다만 모든 가능성을 남겨 두려고 날짜는 비워 뒀군요.","가상의 연애 통계입니다. 당신의 고백은 100% 섬세합니다. 그중 절반은 아직 초안 공책을 벗어나지 못했지만요."],"wellbeing":["평온함을 찾다가 향초 향 두 가지 앞에서 멈춰 섰어요. 향초 평의회는 입장을 정하지 못했습니다.","휴식을 준비하느라 쿠션을 40분 동안 비교했어요. 휴식은 예약을 취소했습니다.","공원에서 벤치 하나 고르는 일도 조명과 전망, 조화에 관한 연구가 됩니다. 비둘기들은 두 벤치를 다 차지했어요.","깜짝 산책을 제안받자 어느 경로도 서운하지 않게 대안을 모두 보여 달라고 요청합니다.","차 한 잔으로 쉬려다가 컵 선택 문제가 생겨요. 찬장은 미적 괴롭힘으로 민원을 냅니다.","전설적인 다정함 뒤에서 편안한 음악 두 목록이 내전을 벌여요. 침묵이 부전승을 거뒀습니다.","계획 없는 휴가를 꿈꾸면서 계획 없는 휴가를 고르는 계획표를 만들었어요.","평온한 순간을 위해 커튼과 꽃, 담요의 동의가 필요해요. 고양이가 거부권을 행사했습니다.","당신의 거실은 놀라울 만큼 균형이 잡혀 있습니다. 그런데 화분이 2센티미터 옮겨져 인테리어 긴급 회의가 열렸군요.","고객 후기입니다. '아름다운 공간과 평화로운 분위기. 단, 컵 하나도 옮기면 안 됩니다.' 가구들이 속삭이며 동의하네요.","방을 더 차분하게 하려고 꽃병 세 개를 골랐습니다. 이제 서로 자기 위치가 맞는지 하루 종일 토론하고 있군요.","양탄자는 부드러움을 더해야 했습니다. 당신은 커튼과 소파의 정신적 화해를 맡기셨군요."],"wisdom":["저울은 무게를 재는 도구이지 세상을 멈추는 도구가 아닙니다. 당신은 그 차이를 따져 보려고 세 번째 접시까지 달았군요.","선택은 다른 가능성을 포기하는 일입니다. 당신은 포기 자체도 선택 사항으로 남겨 두려고 하셨네요.","타협은 훌륭해요. 식사 메뉴를 두고 화분들에게 투표시키는 건 조금 덜 훌륭합니다.","길 두 개가 열리면 건축가를 불러 세 번째 길을 만들게 해요.","결정을 미룬다고 더 우아해지는 건 아니에요. 리본만 하나 더 달릴 뿐이죠.","균형이란 모든 갈림길의 정중앙에 머무는 일이 아닙니다. 당신은 길 한복판에 벤치를 설치했군요.","거울은 있는 것을 비출 뿐이에요. 그런데 당신은 아직도 어느 거울이 맞느냐고 묻습니다.","선택한다고 나머지 후보들을 공격하는 게 아니에요. 후보들도 잘 견딜 겁니다.","결정하지 않은 선택이 완벽한 선택은 아닙니다. 그저 결정을 유리 진열장에 보존해 둔 거죠.","균형을 이루려면 때로 한쪽으로 기울어야 합니다. 당신은 움직이지 않고 움직이는 방법을 발명하셨군요.","마음의 평화가 버튼 두 개 사이의 끊임없는 협상은 아닙니다. 그래도 중립 조약을 준비하고 계시네요.","다른 선택지를 포기한다고 그 선택지가 세상에서 사라지는 건 아닙니다. 당신은 그 선택지를 기리는 작은 기념비를 세우셨군요."],"roast":["당신의 우유부단함에는 자문위원회와 대리위원 세 명까지 있어요.","메뉴를 너무 오래 살펴서 요리사가 메뉴판을 바꿔 버렸습니다. 이제 새로운 철학적 난제가 생겼군요.","메뉴는 결말 페이지로 넘어가길 당신이 거부하는 추리소설이에요.","다툼이 시작되면 너무 환하게 웃어서 의자들까지 협상에 나설 의무를 느낍니다.","자기 취향 하나가 머릿속을 스쳐 갑니다. 당신은 즉시 공개 의견수렴에 부치죠.","단순한 색 하나를 고르려다 84칸짜리 색상표를 만드셨군요. 모두가 지친 끝에 흰색이 당선됐습니다.","칭찬을 너무 많이 나눠 줘서 주차장마저 자기가 아름다운 줄 압니다.","당신의 긴급 대응이란 결정을 미루기로 신속히 결정하는 일이에요. 회의록은 벌써 준비됐습니다.","식당 주문이 국민투표가 됐습니다. 종업원은 휴식에 찬성표를 던졌군요.","초록색 두 가지 사이에서 망설이다 세 번째 범주를 만들었습니다. '다른 두 초록을 모두 존중하는 초록'입니다.","전채요리를 고르지 못해 새로운 식사 전통이 생겼습니다. 디저트가 끝나야 저녁을 시작하네요.","가게가 찻잔 다섯 개를 보여 줍니다. 당신은 독립위원회에서 장단점을 비교해 달라고 요청합니다. 이제 가게 문을 닫아야겠군요."]},"roastMy":["천칭자리인 당신은 식당을 고르는 게 아닙니다. 주민 공청회를 여는 거죠. 모든 사람의 의견을 모아 비교표를 만들고 마지막 순간 새 후보까지 추가합니다. 결국 일행은 각자 집으로 돌아가요. 당신은 적어도 분위기는 좋았다고 평가합니다.","당신의 외교술이라면 상상 속 적군 둘도 화해시킬 수 있어요. 하지만 디저트 두 개 중 하나는 못 고르죠. 가격과 모양, 식감, 직원 기분까지 따져요. 직원이 진행을 위해 둘 다 권합니다. 당신은 세 번째 선택지가 있느냐고 묻습니다.","당신은 아름다움을 너무 사랑해서 쿠션 하나가 삐뚤어져도 협상이 실패했다고 생각해요. 쿠션을 옮기면 다른 쿠션이 균형을 잃죠. 한 시간 뒤 소파는 전시장이 됩니다. 아무도 앉을 허가를 받지 못했어요.","당신은 취향이 없다고 완벽한 미소로 말해요. 사람들이 여러 의견을 내면 각각의 장단점을 설명하죠. 결국 누군가 제발 싫다고만 말해 달라고 부탁합니다. 당신은 그렇게 거절해도 예의에 어긋나지 않느냐고 묻습니다.","당신의 매력은 대량 평화 무기예요. 서비스와 장식, 영수증까지 칭찬하죠. 가게 주인이 친절하게 답하자 너무 적극적이었나 걱정합니다. 영수증 하나를 두고 중재 위원회가 생겨요.","당신은 다툼을 피하는 전문가예요. 친구 둘이 논쟁하면 똑같은 확신으로 번갈아 동의하죠. 결국 누구 편인지 묻습니다. 당신은 세 계절 동안 계속될 차 마시는 휴식을 제안합니다.","옷을 고르는 모습은 박물관의 상설 전시를 준비하는 것 같아요. 옷마다 장점과 분위기, 관람 대상이 정해져 있죠. 결국 첫 번째 옷을 고르고는 정말 최선이었는지 다시 묻습니다. 옷장은 과도한 자문에 대한 배상을 요구해요.","당신은 공정함을 너무 추구해서 마지막 케이크 조각에게 먹히고 싶은지 나뉘고 싶은지 물어요. 누구도 케이크 대신 답하지 못하죠. 그래서 공평한 순환 배분제를 만듭니다. 케이크가 신속한 결정을 요구해요.","모두에게 좋은 인상을 주고 싶어 서로 반대되는 의견 둘에도 동의합니다. 그다음 두 입장을 양립시키려 다시 설명하죠. 사전마저 증언을 거절합니다. 당신은 사전이 지나치게 단정적이라고 생각해요.","당신은 갈등도 불편한 선택도 없는 조화로운 삶을 꿈꿔요. 하지만 매일 아침 똑같이 예쁜 컵 두 개와 마주합니다. 찬장 앞에서 두 컵의 장점을 끝없이 비교하죠. 주전자는 다른 부서로 옮겨 달라는 신청서를 냈습니다.","당신은 친구들과 차를 타고 갈 때 음악을 맡았습니다. 가능한 기분마다 재생목록을 만들고 곡 순서까지 고민하셨죠. 차 안은 놀랄 만큼 평화롭게 조용했습니다. 도착할 즈음 돌아가는 길에 딱 맞는 목록을 완성했지만 아무도 재생할 용기를 내지 못했군요.","공평한 선물 교환 행사를 준비하려 했습니다. 포장과 상징적인 가치, 각자의 취향을 비교한 뒤 누구도 손해 보지 않는 배분을 제안했죠. 모두 당신의 배려에 감탄했습니다. 결국 진행을 위해 선물들이 서로를 주고받았군요.","외출 전에 즉흥적으로 결정 하나를 내리겠다고 약속했습니다. 옷장 두 개를 열고 옷 세 벌을 살펴보며 각각 줄 인상을 고민하셨죠. 결국 처음 입어 본 옷으로 나갔습니다. 그 대담한 결정 앞에서는 1분간 경건하게 침묵해야겠군요.","가까운 사람들과 카드게임을 하려다 테이블 위 물건들을 재배치했습니다. 모두에게 접근이 쉽고 예쁘며 공정한 자리가 필요했죠. 참가자들은 당신의 구성에 감탄했습니다. 그러다 편애를 없애려는 뜻에서 카드까지 가나다순으로 정리돼 있다는 걸 발견했습니다.","친구 두 명이 게임 규칙 때문에 다툴 때 중재를 맡았습니다. 양쪽의 주장을 듣고 인정한 뒤 모두 만족할 문장을 제안했죠. 두 친구는 화해했습니다. 하지만 적용할 수 있는 규칙이 없어 게임은 취소됐군요."]},"scorpio":{"classic":{"career":["당신의 통찰력은 다른 사람들이 아직 말하지 않은 핵심을 알아차리는 데 도움이 돼요.","의미 있다고 느끼는 프로젝트에는 강한 집중력을 쏟습니다.","사람들의 동기를 이해하려는 마음은 전략적인 강점이 될 수 있어요.","신뢰를 주기로 결정하면 함께하는 일에 깊이 헌신해요.","강한 직관도 사실과 맞춰 본 뒤 결정에 활용하면 더 좋아요.","조용한 모습 뒤에는 어려운 상황을 체계적으로 헤쳐 나가는 끈기가 있어요.","복잡한 상황일수록 겉모습 너머를 살피려는 마음이 강해져요.","다른 사람도 자기 방식으로 나아가도록 허락하면 결단력이 더 큰 힘을 발휘합니다."],"love":["당신의 깊은 감정은 진실하고 깊이 있는 관계를 바라게 해요.","신뢰를 신중하게 주는 편이죠. 서로에 대한 믿음도 각자의 속도로 자라납니다.","관계에서 진실을 추구하는 마음과 부드러운 경청은 함께할 수 있어요.","감정이 찾아왔을 때 말로 표현하면 멀어지기보다 가까워질 수 있어요.","단단한 관계를 위해 상대의 모든 생각을 알아야 하는 것은 아니에요.","겉으로는 절제해 보여도 깊이 함께할 수 있는 사람이에요.","함께한 추억을 소중히 여기되 현재를 거기에 묶어 두지는 마세요.","당신의 성실함은 서로의 자유를 존중할 때 진정한 의미를 얻습니다."],"wellbeing":["강렬한 마음에도 당장 답을 내지 않아도 되는 공간이 필요해요.","주변을 이해하려는 걸 좋아하지만 산책만큼은 해석 없이 즐겨도 괜찮아요.","익숙한 장소의 고요함은 발을 땅에 딛고 있다는 느낌을 줄 수 있어요.","생각이 멈추지 않을 때 잠시 대화에서 벗어나 숨 쉴 틈을 주세요.","창의적인 활동은 깊은 내면에 평화로운 출구를 마련해 줍니다.","경계심 많은 당신에게도 아무것도 감시하지 않는 기쁨이 필요해요.","가까운 사람들과의 솔직한 대화가 무거운 침묵을 가볍게 할 수 있어요.","혼자 있는 시간은 선택일 때 더 건강한 의미를 가집니다."],"wisdom":["무엇을 놓아줄지 선택하는 순간에도 강함이 드러납니다.","진실을 찾되 모든 것을 알아야 한다고 생각하지 않아도 됩니다.","비밀은 지켜 줄 때도 있지만 신뢰는 사람을 가깝게 합니다.","직관이 대화에 열릴 때 이해로 자라납니다.","깊은 감정이 모든 결정을 지배할 필요는 없어요.","의심 뒤에는 진심 어린 연결을 바라는 마음이 기다릴 수 있어요.","가장 의미 있는 침묵은 무언가 숨기지 않고 편안함을 줄 때 찾아옵니다.","이해한다는 것은 통제한다는 뜻이 아닙니다."],"roast":["말하지 않은 뜻을 알아채는 재능이 아무 의미 없는 곳에서도 의미를 찾게 할 수 있어요.","내면을 철저히 감추다 보면 자신의 의도를 주변에 전하기 어려워져요.","오래된 의견 충돌을 이야기하지 않은 채 간직하면 마음속에서 차지하는 자리가 커져요.","모호한 대답을 받으면 호기심이 심문처럼 들릴 위험이 있어요.","직관이 아무리 확신에 차도 언제나 증거가 되는 건 아니에요.","모든 것을 이해하려는 마음이 지나친 통제로 이어지면 대화가 지칠 수 있어요.","지키고 있는 비밀마다 자물쇠를 하나씩 더 달 필요는 없어요.","한번 내린 인상을 지키려는 마음에도 새 설명을 받아들일 여지가 필요해요."]},"funny":{"career":["사무실에서 파일 이름이 바뀐 걸 누구보다 빨리 알아차리십니다. 동료 셋은 평범한 점검 회의가 공식 수사로 바뀐 걸 보고 놀랐군요.","일정이 바뀐 이유를 조사하는 모습은 국제적인 미스터리 사건을 맡은 것 같아요.","기밀 문서 한 장도 은행 금고에 들어갈 만큼 엄중하게 다룹니다.","동료가 나중에 설명할게요라고 하면 벌써 왜 나중인가라는 사건 파일을 열었어요.","서류가 잘못 분류된 사소한 실수 하나에서 옛 회의 세 번으로 이어지는 단서를 찾아냅니다.","조용한 책상 뒤에서 머릿속은 탐정처럼 끈기 있게 단서를 짜 맞추고 있어요.","복도에서 들리는 작은 대화가 너무 궁금해서 화분마저 수상해 보입니다.","관찰력이 뛰어나서 누군가 펜을 제자리에 놓기도 전에 누가 옮겼는지 알고 있어요.","동료가 회의를 15분 옮겼습니다. 당신은 벌써 사건의 시간순 기록과 가능한 동기 세 가지를 찾아냈군요.","사내 공지입니다. 새 팀 비밀번호는 수수께끼가 아닙니다. 그런데 당신은 금고를 여는 심정으로 접근했군요.","회의실의 습관을 회의실 달력보다 더 잘 아십니다. 일정표는 몇 가지 비밀을 남기기로 했습니다.","'누가 이 파일을 수정했죠?' '아무도 몰라요.' 당신은 이미 상상 속 손전등을 들고 버전 기록을 살피고 있군요."],"love":["당신의 강렬한 눈빛은 오늘 뭐 먹을까라는 질문도 긴장감 넘치는 장면으로 만들어요.","대화의 작은 부분까지 기억하는 솜씨는 기록관리자도 놀랄 수준이에요.","'다시 전화할게요'라는 짧은 말에 예상보다 설레셨군요. 눈빛이 너무 강렬해서 휴대전화조차 숨을 곳을 찾는 것 같습니다.","비밀을 털어놓으면 머릿속의 여러 겹 잠금장치가 있는 금고에 보관해요.","비밀스러운 데이트를 좋아하십니다. 상대방이 깜짝 선물을 준비하면 당신의 미소는 이미 낭만적인 시나리오 열두 개를 검토했다는 뜻이겠죠.","신비로운 표정 뒤에서는 적절한 순간에 들었던 칭찬을 다정하게 기억하고 있어요.","아주 짧은 메시지를 보면 고민에 빠져요. 당신에게 알겠어 한마디도 거대한 줄거리가 될 수 있거든요.","당신의 사랑은 끝을 이미 아는 조용한 주인공이 등장하는 흥미진진한 소설 같아요.","당신의 강렬한 눈빛은 3초짜리 대화를 영화 장면으로 만듭니다. 상대방은 소금을 찾고 있었을 뿐인데요.","깊은 고백을 좋아하십니다. 특히 여덟 박자 침묵으로 시작하는 고백을요. 커피는 첫 대사를 기다리다 식어 갑니다.","질투가 잠깐 찾아왔습니다. 누군가 웃는 걸 보셨다가 모든 사람이 예의 바르게 웃을 수 있다는 걸 떠올리셨죠.","상대의 손을 소설처럼 진지하게 잡으셨군요. 상대방은 당신이 책의 결말까지 아는지 몰래 확인합니다."],"wellbeing":["공원에서 가장 외진 벤치를 골라 조용히 쉬고 있습니다. 비둘기 한 마리가 다가오자 당신의 고독에 첫 손님이 생겼군요.","조용한 저녁을 보내려는데 옆집에서 의자를 옮기는 소리가 들려요. 새로운 음모가 탄생했습니다.","쉬려고 고른 소설에 비밀이 열 개나 나와요. 당신은 아주 편안함을 느낍니다.","커튼을 친 방이 더없이 편안하군요. 천장 조명이 의견을 내지 않는 평화를 찾으셨습니다.","따뜻한 차 한 잔이 생각을 도와줘요. 차는 자신이 조용히 심문받는다는 걸 모릅니다.","혼자 있고 싶은 마음 뒤에는 담요와 오래된 드라마로 이뤄진 믿음직한 팀이 있어요.","퍼즐은 마음을 편안하게 해요. 아무도 마지막 조각을 일부러 숨기지 않았다면요.","완벽한 휴식에는 놀라운 일이 없어야 해요. 그래서 쿠션 밑을 두 번 확인하죠.","쉬기 좋은 장소는 동화 속 은신처 같습니다. 들어갈 수 있는 유일한 생명체는 밝기 조절 램프뿐이군요.","휴식을 위해 커튼을 닫고 세상을 밖에 둡니다. 휴대전화에는 정식 침묵 초대장을 보내셨군요.","아무도 없는 테라스를 찾아냈습니다. 빈 의자 두 개만 있어도 비밀 성의 주인이 된 기분이죠.","가상의 마음속 날씨입니다. 평온한 안개, 완벽한 그늘, 다른 방에서 '조용히 쉬고 있어요'라고 답할 확률 높음."],"wisdom":["직관에도 휴가가 필요해요. 토스터는 용의자가 아닙니다.","질문 하나를 하기 위해 심문실부터 준비할 필요는 없어요.","미스터리는 매력적이지만 모든 봉투에 음모가 들어 있는 건 아니에요.","페이지를 넘기려면 열네 장짜리 서문부터 쓰지 않는 편이 더 쉽습니다.","비밀을 들었다고 꼭 여섯 자리 암호를 정할 필요는 없습니다.","침묵마다 폭로가 숨어 있는 건 아니에요. 그냥 누군가 씹고 있는 중일 때도 있어요.","변화란 때로 이야기의 결말을 바꾸는 일입니다. 예전 등장인물은 새 장에 데려오지 않아도 됩니다.","신뢰한다고 매번 금고의 자물쇠를 확인할 필요는 없습니다.","용서는 과거를 지우지 않습니다. 다만 아침마다 다시 읽지 않게 할 뿐이죠.","새로운 사람이 되기 위해 옛 습관 하나하나에 작별식을 열 필요는 없습니다.","넘긴 페이지는 사라지지 않습니다. 다만 이후의 모든 페이지에 꽂아 둘 책갈피 역할을 그만두는 거죠.","새로워진다는 건 어둠 속에 두고 싶었던 방의 창문을 열어 보는 일일 수도 있습니다."],"roast":["작년 모임에서 누가 당신의 컵을 옮겼는지 아직 기억하시네요. 컵은 이미 그 일을 잊었습니다.","비밀을 너무 철저히 지켜서 주인조차 털어놓은 사실을 잊어버릴 정도예요.","읽음만 뜨고 답장이 없는 메시지는 즉시 첩보소설 1장이 됩니다.","누군가 아무 일 아니라고 하면 용의자 관계도를 바로 그립니다.","오래된 서운함은 날짜가 정확히 적힌 상자에 보관돼 있어요.","살짝 놀리는 말을 들은 기억이 가족 모임 때마다 떠오릅니다. 그 말을 한 사람은 디저트가 나오기도 전에 잊었는데요.","당신에게 깜짝 선물은 어려워요. 포장지의 리본까지 벌써 심문하고 있으니까요.","신비로운 모습이 너무 강해서 추리소설 속 수상한 이웃마저 당신을 무뚝뚝하다고 생각해요.","당신의 기억은 작은 서운함을 달력보다 정확히 기록합니다. 일정표는 회의를 놓쳤지만 당신은 안 놓쳤죠.","'아무 문제 없어요'라고 말하지만 이미 문제를 기념패에 새긴 사람처럼 차분하시군요.","친구의 지각을 용서하셨습니다. 다만 시계가 울릴 때마다 그 업적을 상기시켜 주실 뿐이죠.","오래전 농담이 마음에 들지 않았습니다. 모임은 다른 주제로 넘어갔지만 당신은 이제야 폐회사를 준비하고 있군요."]},"piquant":{"career":["당신의 의심은 함께 마시는 커피를 정보 작전으로 바꿉니다. 설탕은 잠재적 공범으로 등록됐어요.","단순한 시간 변경을 비밀 권력 이양처럼 조사합니다. 일정표는 변호사를 요구했어요.","내일 얘기하자는 동료의 말로 열두 시간짜리 수사가 시작됩니다. 내일은 아직 오지도 않았어요.","모르는 정보가 하나라도 있으면 특별수사반을 꾸립니다. 비밀은 과자 고르기였어요.","비공개 회의 하나가 탐정 본능을 깨워요. 회의실에서는 의자 유지보수를 이야기하고 있었습니다.","전략적인 침착함 뒤에서 보이지 않는 파일이 팀원들의 한숨을 분류합니다. 복사기가 1위예요.","당신의 전략에는 세 수 앞, 네 가지 가설, 조용한 퇴로가 포함됩니다. 그런데 프로젝트는 폴더 이름 하나 바꾸는 일이었죠.","복사기의 이동 경로를 정보망처럼 분석하셨군요. 기계의 유일한 비밀 작전은 종이가 떨어졌다는 것이었습니다.","아침 식사 전에 회사의 결정 세 가지를 미리 내다보셨군요. 회사에서는 콘센트가 많은 회의실 하나를 찾고 있었습니다.","당신의 사무실 전략은 첩보 작전 같습니다. 비밀의 방에 있던 건 파란 펜 재고뿐이었습니다.","속보입니다. 파일 하나가 옮겨졌습니다. 비상대책반을 꾸린 뒤 '옮긴 파일' 폴더에서 찾아냈군요.","가상의 보안 보고서입니다. 부서의 모든 비밀을 아십니다. 풀리지 않는 수수께끼는 단 하나, 금요일 회의의 존재 이유군요."],"love":["당신의 강렬함은 단순한 나중에 보자를 민감한 사건으로 만들어요. 나중이라는 단어가 감시 대상이 됩니다.","믿는다고 말하면서 준비 중인 깜짝 선물이 정말 깜짝 선물인지 확인합니다. 포장지는 변호사를 요청했어요.","마침표가 없는 메시지도 수상하고 있는 메시지도 수상해요. 문장부호는 어느 쪽이든 소환됩니다.","상대방이 '오늘 하루 좋았어요'라고 말하자 고대의 비밀이라도 털어놓은 듯 뚫어지게 보셨군요. 그냥 다정한 대화였습니다.","옛말 한마디를 기억 속 기록물에 보관해요. 사건 번호와 재검토 날짜까지 붙어 있습니다.","직원이 웃어 주는 모습에 질투가 발동해 조용한 오페라 한 편이 시작됐습니다. 직원은 빈 접시를 치우려던 것뿐인데요.","비밀을 털어놓는 일은 감동적이지만 당신의 엄숙한 표정 앞에서 곧바로 국가기밀로 격상돼요. 다정함은 보안 인가를 기다립니다.","당신의 마음은 깊이를 좋아해요. 그래서 날씨 이야기조차 가끔 구름에 대한 심문으로 끝나죠.","당신의 눈빛이면 빵 한 개 주문도 극적인 로맨스 스릴러로 바꿀 수 있습니다. 빵집 직원은 영화 촬영 중인 줄 알았겠네요.","당신은 깊은 애정이라고 부르지만 상대방은 컵을 고르러 가는 길에도 의미심장한 시선의 복도를 지나야 하는 기분입니다.","'그 사람 아세요?' '조금요.' 그런데 당신의 눈썹은 방금 이 대답에 관한 장편소설을 출간했군요.","질투가 식당 한구석의 수수께끼 같은 손님처럼 조용히 자리를 잡았습니다. 그리고 머릿속에서는 모든 테이블을 독점합니다."],"wellbeing":["통제 욕구 때문에 평화로운 산책도 순찰 업무가 됩니다. 비둘기들은 조직적으로 움직였다는 의심을 받아요.","빈 방에서 평온함을 찾았다가 왜 비어 있는지 의심합니다. 의자는 알리바이를 제출해야 해요.","어두운 방에서 혼자 한 시간을 보내기로 하셨군요. 문 아래로 들어오는 빛 한 줄기조차 초대받지 않은 손님 취급을 받습니다.","침묵을 좋아한다면서 안락의자도 자기가 당신을 맞이하고 있다는 걸 모를 만큼 비밀스러운 자리를 고르셨군요. 평온함조차 익명입니다.","조용히 차를 마시는 순간도 지나치게 조용해서 수상해요. 티백은 정밀 심문을 받습니다.","침묵 뒤에서는 이웃이 마지막으로 왜 한숨을 쉬었는지 가설들이 싸우고 있어요. 시계는 증언을 거부합니다.","아무 일 없는 날이 오히려 더 불안해요. 달력은 이불 밑에 숨었습니다.","휴식을 위해 거실에서 조용히 사라지는 게 당신의 방식이군요. 세 방 건너편에서는 은신처를 독립적인 침묵 구역으로 선포하셨습니다.","혼자 있는 시간을 너무 사랑해서 고독에게 방 하나를 더 내줄까 고민하시는군요. 첫 번째 방은 이미 기밀 구역입니다.","고객 후기입니다. '멋진 휴식 공간이지만 거주자가 커튼을 움직이는 방식으로만 소통해요.' 침묵에는 별 다섯 개가 주어졌습니다.","조용함을 찾으려고 불을 전부 껐습니다. 문 아래로 들어오는 빛줄기마저 지나친 친근함을 이유로 퇴장당했군요.","당신의 휴식 공간은 오래된 성보다 신비롭습니다. 위대한 비밀은 찻잔 하나와 아무도 만나고 싶지 않다는 소망이죠."],"wisdom":["용서는 때로 길에서 돌 하나를 치우는 일입니다. 당신은 먼저 새 풍경의 전체 설계도를 요구하셨군요.","당신은 답을 찾는 게 아니에요. 우연을 심문대에 올리는 거죠.","신비감이 항상 배신을 숨기는 건 아니에요. 가끔은 그냥 닫힌 서랍입니다.","변화란 닫힌 문에 계속 페인트칠하지 않는 것입니다. 그런데 그 문의 다음 생을 위해 색상표를 주문하셨네요.","빛나는 직감이 자동으로 믿을 만한 증인이 되는 건 아니에요. 배심원은 증거를 기다립니다.","다시 태어난다는 건 더 어두운 세트에서 같은 장면을 반복하는 게 아닙니다. 그래도 새 커튼을 준비 중이시군요.","비밀은 스스로도 잘 지켜져요. 그런데 당신은 전용 벙커까지 지었습니다.","믿는다는 말이 믿음을 감시할 탐정까지 고용한다는 뜻은 아니에요.","용서는 예전 이야기의 결말에 찬성하는 일이 아닙니다. 당신은 영화를 바꾸기 전에 전체 엔딩 크레디트부터 요구하셨군요.","다시 시작하려면 옛 버전의 자신이 새 버전을 지휘하지 않게 해야 합니다. 그런데 옛 버전에게 감독 의자를 그대로 남겨 두셨네요.","삶을 바꾸려면 때로 문 하나를 열어야 합니다. 당신은 아직 문손잡이의 상징성부터 분석 중이시군요.","오래된 장면에 영원히 머문다고 자유로워지는 건 아닙니다. 실내 장식만 바꾸고 무대는 그대로 남겨 두셨군요."],"roast":["당신의 앙금은 너무 잘 분류돼서 기록보관소와 민원 창구까지 갖췄어요.","당신의 신뢰는 잃어버린 열쇠를 대하는 금고만큼 조심스러워요.","사소한 말을 세 계절 동안 마음에 담아 두셨군요. 말한 사람은 휴대전화를 바꿨지만 당신의 서운함은 옛 번호를 그대로 저장하고 있습니다.","깜짝 선물이라는 말에 즉시 정보 유출 경로부터 찾습니다. 선물은 아직 포장도 안 풀렸어요.","작은 서운함 하나도 잊지 않으십니다. 기억 속에서는 한정판으로 보관하고 화해 코너는 거의 비어 있네요.","어긋난 농담 하나가 역사적인 불만 수집품에 들어갔습니다. 상대방은 이미 다른 일에 웃고 있는데 당신은 제2권을 쓰는 중입니다.","비밀은 당신과 있기를 좋아해요. 명패와 암호, 면회 시간까지 제공받으니까요.","당신의 용서는 조건부 석방과 같아요. 옮겨진 의자마저 보호관찰 대상입니다.","당신의 앙금에는 기념일 달력이 있습니다. 날씨에 대한 작은 언급에도 자체 기념일이 생겼군요.","사소한 서운함을 용서했습니다. 그 사실을 3년째 만날 때마다 설명하시네요. 용서가 공식 공지가 됐습니다.","당신은 뒤끝이 없다고 하십니다. 그건 너무 평범하죠. 그저 서툰 발언 박물관의 자원봉사 관장이실 뿐입니다.","사소한 농담 하나가 기억 속에서 역사 문서가 됐습니다. 기록 보관소조차 중대한 사건으로 분류하길 거부하는군요."]},"roastMy":["전갈자리인 당신은 대화를 듣는 게 아닙니다. 사건 기록을 작성하는 거죠. 잠깐의 멈춤과 눈빛, 빠진 쉼표 하나가 모두 증거가 됩니다. 누군가 냅킨이 어디 있냐고 물어요. 당신은 증인 이름부터 요구합니다.","당신의 서운함 기억은 국립 기록보관소 같아요. 다만 종결되는 사건이 하나도 없다는 점이 다르죠. 비 오는 화요일 누군가 플레이리스트에 대해 했던 말도 기억해요. 그 사람은 자신이 조사 대상인 줄도 모릅니다. 용서 담당 부서는 재고 조사로 휴업 중이에요.","당신은 미스터리를 좋아한다고 말해요. 사실은 미스터리 뒤의 또 다른 미스터리, 그 뒤에 숨은 무엇인가를 의심하는 거죠. 닫힌 문 하나를 조사하기 시작합니다. 알고 보니 찬장이었어요. 이제 찬장은 증인이 없으면 당신을 만나지 않겠답니다.","당신의 강렬한 눈빛은 카페 직원이 심문받고 있는 듯 느끼게 해요. 직원은 창가에 앉고 싶은지만 물었죠. 당신은 출입구 위치를 확인한 뒤 답합니다. 직원은 계산대로 전근을 신청했어요.","당신은 공휴일의 은행 금고만큼 너그럽게 신뢰를 나눠 줘요. 비밀을 나누려면 열쇠와 암호, 추천장이 필요하죠. 일단 가까워지면 누구보다 성실하게 관계를 지킵니다. 금붕어마저 비밀유지 계약에 서명해야 해요.","당신은 누구도 숨기는 게 없을 때조차 모든 것을 이해하려 해요. 상대가 네라고 답하자 말투와 답변 시간, 이모지 부재를 조사하죠. 결론은 중대한 비밀의 존재입니다. 상대는 그냥 네라고 한 거였어요.","당신의 침착함 앞에서 물건들도 긴장해요. 쏟아진 커피잔을 국제 수사관처럼 바라보죠. 테이블은 심문받고 행주는 용의자가 되며 커피는 현장 재현을 거부합니다. 고양이는 증거 불충분으로 면책됐어요.","당신은 지난 일을 넘겼다고 말해요. 맞아요, 페이지를 넘기고 책갈피를 꽂은 뒤 사본까지 보관했죠. 세 시즌 뒤 비슷한 말을 들으면 사건 파일이 다시 열립니다. 추억 법정은 비공개로 열려요.","당신의 비밀 사랑은 깜짝 간식 파티를 기밀 작전으로 만들어요. 시간도 장소도 접시 색깔도 알려 주지 않죠. 손님들은 암호화된 지시를 받고 따로 도착합니다. 케이크는 그냥 초대장 한 장을 요청해요.","당신은 깊은 관계를 좋아하지만 가벼운 질문조차 역사적인 사건으로 만들어요. 하루 어땠냐는 말에 의미심장한 침묵으로 답합니다. 상대는 계속 기다려요. 침묵마저 공인 통역사를 요구합니다.","전갈자리인 당신은 팀과 함께 길 찾기 게임에 참가했습니다. 숨은 길과 샛길, 장애물을 피하는 방법까지 이미 알고 있었죠. 동료들은 당신의 전략을 칭찬했습니다. 그러다 게임 안내지에 없는 수수께끼를 찾고 있다는 걸 알게 됐군요.","친구들과 가볍게 웃는 저녁을 보내기로 했습니다. 사소한 말 하나에 눈썹이 올라갔지만 아무렇지 않게 웃으셨죠. 2주 뒤 당신은 그 말을 억양까지 그대로 꺼냈습니다. 모임은 끝났지만 기억은 재방송을 준비 중이군요.","당신은 조용함을 너무 세심하게 추구해서 짧은 이동도 혼자만의 공간으로 만듭니다. 말 거는 사람이 가장 적을 자리를 고르고 전화 소리를 줄이며 풍경을 바라보죠. 친구가 게임을 제안합니다. 카드들이 침묵을 지켜 준다는 조건으로 수락하셨군요.","진솔하고 깊은 대화를 좋아하십니다. 누군가 집 안 장식을 바꿨다고 말하자 그 결정이 삶의 포부에 어떤 의미인지 설명해 달라고 하셨죠. 상대방은 1분간 진지하게 생각합니다. 램프를 옮겼을 뿐인데 자기 변신의 상징으로 승격됐군요.","오래된 서운함을 끝내기로 했습니다. 종이에 적어 접고 상자에 넣으며 마지막 장을 닫는 의식을 치렀죠. 거의 시적이었습니다. 그리고 상자에 '다시 열지 말 것. 단, 추가 설명이 필요하면 예외'라는 라벨을 붙이셨군요."]},"sagittarius":{"classic":{"career":["자유를 사랑하는 마음은 익숙한 틀을 벗어나야 하는 프로젝트에 새로운 바람을 불어넣어요.","큰 아이디어도 목표에 닿으려면 때로는 더 자세한 경로가 필요해요.","솔직함은 적절한 때를 골라 표현할수록 힘을 얻어요.","반복되는 업무에 의욕이 떨어진다면 배울 수 있는 부분을 찾아보세요.","당신의 열정적인 낙관은 팀이 더 넓은 가능성을 보게 만들 수 있어요.","빨리 나아가고 싶은 마음 뒤에는 동떨어진 생각들을 잇는 귀한 능력이 있어요.","업무에서는 자율성을 바라는 마음과 명확한 약속이 함께할 때 조화로워져요.","새로운 방식을 탐색하면 노력을 분산하지 않으면서도 창의력을 키울 수 있어요."],"love":["혼자만의 공간이 필요하다고 소중한 사람에게 진심을 다하지 못하는 것은 아니에요.","솔직한 말은 상대방에게도 이야기할 여지를 남길 때 관계를 더 가깝게 해요.","자발적인 성향은 애정 어린 대화에 신선함을 더해요.","멀리 떠나고 싶어질 때 그 바람을 나누면 더 깊은 대화가 열릴 수 있어요.","타고난 낙관은 관계를 밝게 하지만 잔잔한 감정도 소중히 받아들여 보세요.","모험을 사랑하는 마음 뒤에서는 그 자유를 존중하는 관계도 찾고 있어요.","관계 속 신뢰는 끊임없이 설명하지 않아도 각자 숨 쉴 공간을 줍니다.","상대방의 다른 속도를 받아들이면 이미 소중한 친밀함이 더 깊어질 수 있어요."],"wellbeing":["여행을 좋아하는 에너지는 정해진 목적지 없는 산책에서 균형을 되찾을 수 있어요.","두 프로젝트 사이의 휴식은 열정을 오래 이어가게 합니다.","자유란 아무 일정도 없는 오후의 모습일 수도 있어요.","생각이 내일로 달려갈 때 지금 주변에 있는 것에도 주의를 기울여 보세요.","새로운 곳을 찾고 싶다면 가까이 있지만 잘 모르는 장소를 탐험해 보세요.","움직이고 싶은 마음이 커도 평온한 잠자리에는 자기 자리가 필요해요.","수많은 가능성 속에서 사랑하는 사람과 나누는 소박한 순간을 선택해 보세요.","스스로 속도를 늦춘다고 시야가 좁아지지 않아요. 오히려 풍경을 감상할 시간이 생깁니다."],"wisdom":["자유는 한 약속을 지킬 때 더 넓어집니다.","먼 지평선을 향하는 길도 눈앞의 한 걸음에서 시작됩니다.","솔직함은 돌아올 수 있는 문을 남길 때 더 소중합니다.","모든 모험은 돌아오는 시간을 받아들일 때 깊이를 얻어요.","낙관에는 큰 약속보다 분명한 기준이 도움이 됩니다.","탐험은 꼭 떠나는 것만이 아니에요. 귀 기울이는 것만으로도 충분할 수 있습니다.","진정한 추진력은 함께 걷는 이들의 속도도 존중합니다.","세상을 이미 다 안다고 믿는 것만큼 시야를 좁히는 일은 없습니다."],"roast":["자유를 갈망하다 보면 모든 계획을 불필요한 구속으로 착각할 때가 있어요.","열정적으로 한 약속도 희미한 기억으로만 남아서는 안 돼요.","진실을 말하는 건 쉽지만 그 진실을 포장하는 배려가 부족할 때가 있어요.","대화가 진지해지면 마음속에서 다른 창을 열고 싶어져요.","감탄스러운 낙관도 실무적인 세부 사항은 종종 빠뜨립니다.","새로운 것을 바라는 마음 뒤에서 몇몇 프로젝트는 여전히 결론을 기다려요.","빡빡한 일정표를 보면 비상구부터 찾고 싶어지는군요.","새로운 아이디어를 향해 떠나는 일이 어제 시작한 일을 마치는 것보다 더 즐거워요."]},"funny":{"career":["모험을 좋아해서 책상 두 개 사이를 오가는 일도 원정이 됩니다. 복도에는 이미 발견의 길이라는 이름을 붙였어요.","계획 회의가 잡히면 기발한 생각이 떠올라요. 회의가 시작하기 전에 떠나자는 거죠. 달력은 기분이 상했습니다.","솔직함 덕분에 발표에 슬라이드가 40장이나 많다고 말해요. 첫 두 장만 보고도 다 셌다고 주장하죠.","실행 계획을 요청받으면 세계지도를 보여 줍니다. 팀은 그냥 프린터를 옮기려던 건데요.","열정에 휩쓸려 점심 전에 프로젝트 다섯 개를 수락합니다. 오후에는 여행 안내자로 이직할까 고민해요.","처음 보는 테라스에서 원격 회의에 참석하며 사무실 배경화면을 켜셨군요. 갈매기들은 기밀유지 서약을 한 적이 없는데요.","절차라는 말을 듣자마자 반사적으로 출구를 살펴요. 사내 규정조차 지나치게 극적이라고 생각합니다.","가능성을 탐색하는 게 너무 즐거워서 업무 목록표를 상상 속 여행지 안내 책자로 바꿔 놓았어요.","사내 공지입니다. 회의 발언은 5분 이내입니다. 당신은 첫 4분을 회의를 다른 곳에서 해야 하는 이유를 설명하는 데 쓰셨군요.","워크숍 요약을 부탁했더니 국제회의 계획과 열정적인 슬로건 세 개를 들고 돌아오셨군요.","사무실에 국제 시간대 지도가 걸렸습니다. 동료들은 당신이 지난주와 같은 시간대에 있는 날이 없다는 걸 알게 됐죠.","'현실적인 날짜를 약속할 수 있나요?' '물론이죠!' 어떤 연도를 말씀하시는지는 깜빡하셨지만요."],"love":["자유를 향한 당신의 낭만은 저녁 초대장에도 목적지 미정이라는 선택지를 넣어요.","사랑을 고백한 바로 다음 순간 이번 주말 다른 대륙으로 가 보자고 제안합니다.","둘만의 저녁을 제안한 뒤 각자 언제든 일정을 바꿀 수 있다는 조항을 추가하셨군요. 낭만도 편한 운동화를 신었습니다.","즉흥적으로 하자고 말하면 가까운 사람들이 몰래 여권 유효기간을 확인합니다.","계획 없는 연인과의 주말이 너무 좋으시군요. 상대방은 '계획 없음'에 귀가 시간도 없다는 뜻이 포함된 줄 몰랐습니다.","당신이 생각하는 튼튼한 관계에는 열쇠 두 개, 일정표 두 개, 언제나 열린 문이 있습니다. 어느 쪽으로 열리는지는 빠뜨리셨지만요.","식당에서 꿈꾸는 미래를 이야기합니다. 넓은 공간과 반복 없는 일상, 나눌 디저트가 포함돼요.","놀라움 없는 저녁을 약속하는 건 괜찮아요. 식사 뒤의 비밀 활동을 예약했을 뿐이니까요.","여유를 주는 관계를 좋아하십니다. 일정표에도 '둘만의 즉흥성'이라는 빈칸을 마련해 두셨네요.","커플 여행을 처음 계획하면서 따로 출발해 디저트 때 만나는 경로 두 개를 제안하셨군요. 기묘한 계획이지만 디저트만큼은 함께네요.","'언제나'라는 단어가 멋지게 들립니다. 다만 정해진 약속 시간이 따라붙으면 느낌이 달라지죠.","당신의 낭만적인 고백은 엽서 한 장입니다. '저는 당신을 선택했어요.' 뒷면에는 등산로 세 개가 그려져 있네요."],"wellbeing":["이상적인 휴식이 즉흥적인 등산처럼 보여요. 소파는 자기도 참여할 기회를 달라고 합니다.","10분 산책이 세 동네 탐험으로 변해요. 그 길이 흥미로워 보였다는 이유로 우회도 하죠.","낮잠은 너무 정적이에요. 기차 안에서 자면 한 번에 두 가지를 할 수 있다고 제안합니다.","속도를 늦추라는 말을 들으면 즉시 어느 방향으로요라고 묻습니다.","아침의 열정으로 창문을 활짝 열며 위대한 모험의 시작을 선포하는 듯해요.","탈출을 꿈꾸는 마음 뒤에는 단순한 진실이 있어요. 안락의자 위치만 바꿔도 기분이 달라질 수 있죠.","쉬려고 앉았다가 먼 나라 영상을 틀어요. 세 시간 뒤에는 여행 일정이 완성돼 있습니다.","바람을 쐬고 돌아오면 여행 아이디어는 여섯 개 생기지만 지금 몇 시인지는 몰라요.","여행 가방은 '혹시 몰라서' 늘 반쯤 열려 있습니다. 물통과 스웨터, 도시를 걸어서 가로지를 마음을 넣어 두셨죠.","야외의 벤치에서 쉬기로 했지만 언덕 너머로 이어지는 길이 더 마음에 들었습니다.","집에서 조용한 하루를 보내려 했습니다. 정오에는 이미 동네를 한 바퀴 돌고 기차역 두 곳에 인사까지 했군요.","당신이 좋아하는 날씨에는 바람과 긴 거리, 신발을 갈아 신을 좋은 핑계가 포함됩니다."],"wisdom":["세계 최고의 철학은 때로 단순한 질문 하나에 담깁니다. 시작한 일을 끝내셨나요?","약속은 떠나기 전에 적어 둬야 잃어버리지 않는 추억이에요.","진실은 뛰어들지 않고 들어올 때 더 아름답게 들려요.","모든 지평선은 방문할 가치가 있죠. 빨랫감도 자기 차례를 기다립니다.","당신의 낙관은 산도 옮길 수 있지만 열쇠를 찾아 주지는 못해요.","세상 탐험은 고귀해요. 충전기를 찾는 일도 마찬가지죠.","모험은 가끔 약속 시간을 읽는 데서 시작됩니다.","열린 일정표가 즉흥성을 막는 법은 없어요.","큰 아이디어도 첫 번째 사소한 세부사항을 통과해야 가치가 있습니다.","현명한 사람은 멀리 봅니다. 그리고 떠나기 전에 신발 끈도 확인하죠.","인생에는 가능성이 가득합니다. 그중에는 '마무리할 것'이라는 작은 표시가 붙은 것들도 있죠.","당신의 철학은 문을 엽니다. 가끔 그 문이 실제 방으로 통하는지도 확인해 보세요."],"roast":["같은 금요일에 저녁, 공연, 게임 모임을 모두 수락하셨군요. 일정표가 마지막 장이 빠진 소설 같습니다.","정확한 시간이 적힌 초대장은 이미 너무 권위적으로 느껴져요.","주말 계획을 너무 자신 있게 설명해서 친구들이 벌써 '우주가 바뀌면 변경될 수 있음'이라고 메모하고 있군요.","5분이면 된다고 말하면 모두 이번 분기 안에는 되겠지라고 이해합니다.","새로운 초대마다 이전 세 가지 약속을 확인하기도 전에 승낙합니다. 달력이 소설 모드로 전환됐군요.","반복을 거부하는 마음 뒤에는 아주 규칙적인 습관 하나가 있어요. 반복을 피하는 반복이죠.","즐겨 하시는 말은 '다시 알려 드릴게요'입니다. 그 소식은 등산을 떠나 아직 돌아오지 않았습니다.","어디로 가는지 몰라도 떠나는 걸 좋아해요. 장을 보지 않고 돌아오는 건 다른 사람들에겐 덜 즐겁죠.","'잠깐 들를게요'라고 약속하셨군요. 바람은 이미 다녀가서 메시지까지 남겼는데 당신보다 시간을 잘 지켰습니다.","친구들은 더 이상 초대 참석 여부를 묻지 않습니다. 그날 저녁 어떤 새로운 모험이 당선되는지 기다릴 뿐이죠.","간단한 간식 모임이 한 시간으로 끝나기로 했습니다. 산책과 즉흥 방문이 추가되더니 간식에게 사과 문자까지 보내게 됐군요.","약속 장소는 잊으면서 그 약속 대신 떠오른 멋진 아이디어는 완벽히 기억하시는군요."]},"piquant":{"career":["회의에서 결정을 속보 진행자처럼 발표합니다. 회의록은 인쇄되는 순간에야 그 결과를 알아차리네요.","정확한 지시를 받으면 부서를 혁명하고 싶어져요. 파일 이름만 바꾸면 됐는데 파일은 망명을 신청했습니다.","솔직함이 특기라 프로젝트 첫 장을 읽기도 전에 터무니없다고 선언해요. 첫 장은 공식 답변을 준비합니다.","문서 하나를 맡으면 열정이 즉시 다른 문서를 찾으러 떠나요. 첫 문서는 작전 중 실종 처리됐습니다.","장엄한 결과물을 약속하셨군요. 그러고는 '실제로 할 일' 항목을 읽고 개막식부터 한 번 더 하자고 제안하십니다.","어떤 문제에도 원격 근무를 해결책으로 내세우시는군요. 팀에서는 당신의 시간대가 매일 바뀌는 깜짝 이벤트라는 걸 알게 됐습니다.","첫 회의록을 보자마자 책상 독립을 선언합니다. 문구용품들은 주민투표를 요구해요.","끝내는 것보다 탐색하는 일이 고상하다고 생각해요. 반짝이는 아이디어 폴더는 미완성 결론 박물관을 열었습니다.","속보입니다. '간단하고 빠른' 프로젝트를 약속하셨군요. 요구사항 문서는 그 두 표현이 허구의 등장인물이라는 걸 이제 알았습니다.","기차에서 원격 근무를 하며 유연하다고 주장합니다. 인터넷 연결은 여행에 동행하지만 돌아오는 표는 없군요.","'계획이 승인됐나요?' '마음속으로는요.' 실행할 사람에게도 알려야 한다는 사실은 마음이 잊은 모양이군요.","회의에 들어가 진실을 가감 없이 말하고 예정에 없던 업무 다섯 개를 안고 나옵니다. 당신의 솔직함은 후속 과제 제조기군요."],"love":["자유는 언제나 약속보다 우선입니다. 달력조차 당신에게 접근하려면 예약해야 해요.","낭만적인 약속은 공식 연설처럼 자연스럽게 쏟아져요. 약속관리부는 당신의 주소를 찾고 있습니다.","당신에게 연인 관계의 독점성은 선택 가능한 기능 같군요. 정작 상대방은 동의 버튼을 누르기 전에 약관부터 읽고 싶어 합니다.","관계에서 만날 시간을 정하자고 하면 국제 조약처럼 받아들여요. 협상은 아직 목요일이라는 단어에 머물러 있습니다.","낭만적인 외출을 예약하고 혹시 모를 출구 세 개를 남겨 두셨군요. 데이트라기보다 대피 훈련처럼 보입니다.","모험가다운 매력 뒤에는 깨알 같은 조항이 있어요. 날씨와 당일 기분에 따라 이용 가능.","습관이라는 말만 들어도 비상대책반을 떠올립니다. 이야기는 함께 아침을 먹자는 것이었는데요.","5분만 예측 가능하게 행동하겠다는 약속조차 힘들어요. 타이머는 3분이 되기 전에 도망쳤습니다.","당신이 생각하는 이상적인 관계에는 애정이 넘치고 의무는 적으며 멋지게 장식된 비상구가 있습니다. 대피 안내도 낭만적이군요.","커다란 사랑의 표현으로 변경 가능한 항공권을 선물하십니다. '변경 불가'라는 말은 개인적인 모욕처럼 들리겠군요.","공식 안내입니다. 당신의 마음은 가까워지는 일을 허용합니다. 다만 위성조차 지나치다고 느낄 수준의 자율성을 유지해야 합니다.","'우리'라는 말은 좋지만 '나는 내 마음대로 할 거야'를 밀어내면 안 된다고 생각하시네요. 이제 관계가 아니라 국경 협상이 됐군요."],"wellbeing":["가만히 있지 못해 쉬는 시간도 정찰 임무로 바꿉니다. 공원 벤치는 방해 배상을 청구해요.","일정 없는 하루는 수상하죠. 자유로운지 확인하려고 별도의 동선을 짭니다.","휴식은 다른 장소에서 할 때만 흥미로워요. 안락의자는 주인을 찾으려고 탐정을 고용했습니다.","평온하게 걸으라는 제안에 가장 먼 길로 돌진해요. 평온하다는 단어가 배지를 반납했습니다.","쉬려고 걷기 시작했다가 소풍이 되고 결국 기차역에서 끝났습니다. 휴식은 환승을 놓쳤군요.","먼 곳만 찾는 마음 뒤에서는 열린 창문 하나도 영토 확장 작전처럼 보입니다.","잠자리에 들어서 지도를 보며 머리를 식힌다고 해요. 베개는 여권을 신청했습니다.","속도를 늦추면 체면이 상하니 휴식을 수평 탐험이라 부릅니다. 소파는 공식 성명을 거부해요.","가방에 즉흥적인 결정을 위한 특별 수납칸이 있습니다. 그 수납칸이 집의 절반을 차지하네요.","교통수단을 세 번이나 갈아타야 하는 원정을 '자연 속 휴식'이라 부르시는군요. 정원 벤치는 공식적으로 퇴역했습니다.","마음속 날씨는 여전한 분주함에 전망 좋은 우회로가 나타날 가능성이 높습니다. 안락의자는 지도에서 사라졌군요.","마음을 가라앉히는 산책 안내서를 샀습니다. 세 쪽을 넘기자 전국 종주 계획부터 세우고 계시네요."],"wisdom":["당신의 철학은 늘 컵이 반쯤 찼다고 말합니다. 특히 누가 컵을 채워야 했는지 잊었을 때요.","크게 생각한다고 작은 일을 끝내지 않아도 되는 건 아닙니다. 당신의 이론에는 멋진 대문만 있고 정원은 없군요.","뉘앙스 없는 낙관은 아직 공사 중인 현장에서 보낸 그림엽서 같습니다.","철학적 확신은 증거가 아닙니다. 당신의 열정은 이미 결론에 액자를 씌웠군요.","당신의 낙관은 세계지도는 있지만 돌아올 주소는 없어요.","끝내지 않고 탐험하는 것은 시작만 유리 진열장에 모으는 일이에요.","모험은 당신을 피하지 않아요. 약속 시간만 확인해 달라고 기다립니다.","당신을 가장 옭아매는 것은 시간표를 극적으로 거부하는 습관입니다.","당신의 낙관은 모든 벽에서 지평선을 찾습니다. 하지만 창문과 포스터 정도는 구별하는 게 좋겠죠.","아이디어의 위대함은 느낌표 수로 정해지지 않습니다. 그런데 당신의 철학에는 사이렌까지 달렸군요.","백지 상태의 지도를 든 안내원처럼 확신에 차서 인생의 의미를 찾고 계시는군요.","희망은 소중합니다. 그것을 보장으로 바꾸는 일은 당신의 신념 홍보팀이 할 일이겠죠."],"roast":["엄청난 열정으로 참석을 확인하셨지만 두 시간 뒤 '어떤 특별한 일'이 부른다며 사라지셨군요. 친구들은 당신의 상상력에 휴대전화가 있는지 의심합니다.","예약 하나도 기본권 침해로 받아들여요. 식당은 사건을 상상 속 당국에 넘겼습니다.","이번에는 아무것도 잊지 않겠다고 약속하셨군요. 그 문장은 이미 버려진 초대장 네 장에 적혀 있습니다.","제가 갈게요라고 말하면 시계도 웃음을 터뜨려요. 시간대는 감정을 요청했습니다.","일정표에는 실제로 지킨 약속보다 말줄임표가 더 많습니다. 세 개의 점은 정규직 자리를 얻었군요.","토요일마다 기발한 아이디어가 하나씩 있습니다. 지난 토요일의 아이디어는 아직 비를 맞으며 케이크를 들고 기다립니다.","서식 하나만 봐도 행정 독재라고 외칩니다. 이름만 쓰면 되는 서식이었는데요.","떠나는 건 좋고 머무는 건 불안하고 돌아오는 건 지루하죠. 현관 매트마저 주인을 알아보지 못합니다.","'일생일대의 기회'라며 저녁 약속을 취소하셨군요. 이번 주에만 세 번째 일생일대의 기회입니다. 사전이 새 판을 준비하네요.","당신의 '제가 처리할게요'는 입에서 입으로 전해지는 전설입니다. 역사가들은 아직 확인 가능한 사례를 찾고 있습니다.","아주 작은 새로움도 일정을 밀어냅니다. 당신에게 달력이란 토요일 주연을 뽑는 상설 오디션장이군요.","다섯 가지 모험을 시작하고 각각의 소식을 약속했습니다. 단체 대화방은 첫 사진들의 박물관이 됐군요."]},"roastMy":["사수자리인 당신은 자유를 너무 사랑해서 알람 시계조차 허가를 받아야 해요. 초대장 세 장에 역사적인 열정으로 답합니다. 정작 당일에는 직감이 이끈다며 다른 곳으로 떠나죠. 초대장들이 당신의 일정표에 버림받은 이들의 협회를 만들었습니다.","당신의 여행가방은 언제든 준비됐는데 장보기 목록은 늘 미완성이에요. 누군가 빵을 사 오라고 하면 상상 속 여행을 계획하죠. 돌아올 때는 샛길에 관한 이야기만 가져옵니다. 빵집이 수배 전단을 만들고 있어요.","당신의 솔직함은 예약 없이 들이닥치는 이삿짐 트럭 같아요. 생각을 그대로 말한 뒤 20분 동안 그게 얼마나 용감했는지 설명합니다. 다른 사람들은 식탁보가 어떤지만 물었는데요. 식탁보는 반론권을 요구합니다.","사수자리인 당신은 역사적인 연설처럼 진심으로 약속해요. 두 시간 뒤 새로운 열정을 발견하고 방향을 바꾸죠. 당신의 약속들은 매달 모여 당신의 위치를 찾으려 합니다. 최근 출석은 선택 사항으로 바꿨어요.","당신의 낙관이라면 닫힌 문 앞에서도 좋은 소식이라고 선언할 거예요. 창문과 다른 길, 새로운 모험을 찾겠죠. 하지만 문에는 당기세요라고 적혀 있을 뿐입니다. 당신의 실용성에 관한 조사위원회가 열렸어요.","당신은 특히 어제 스스로 만든 규칙을 싫어해요. 오늘 계획은 영감을 따르기 한 줄뿐이죠. 정오가 되자 영감은 말도 없이 떠났습니다. 할 일 목록은 이제 실종 일정표를 발행합니다.","자유를 향한 욕구는 작은 약속도 외교 사건으로 만들어요. 저녁 참석을 확인해 달라는 말에 정신의 독립을 이야기하죠. 아무도 당신을 가두려는 게 아닙니다. 네 명이 먹을 식당을 예약하려는 것뿐이에요.","오븐에서 알림음이 울리는 동안 인생의 의미를 철학적으로 설명해요. 자유와 운명, 잊힌 문명까지 강연이 이어집니다. 식사는 30분째 기다리고 있죠. 방금 비자발적 청중 자격을 얻었습니다.","당신은 새로운 출발과 낯선 길, 거대한 아이디어를 사랑해요. 무언가를 끝내는 일은 훨씬 덜 낭만적이죠. 책장에는 쓰다 만 노트 스무 권과 다 써 버린 펜 하나가 있습니다. 펜은 공로 훈장을 요구합니다.","사수자리인 당신의 즉흥성에는 공식 구호가 있어요. 아무것도 계획하지 않았고 모든 게 가능하다. 늦게 도착해 다른 장소를 제안하고 멋진 우회로까지 발표하죠. 친구들에게 필요한 건 가이드가 아닙니다. 이동 조정 본부예요.","신발도 찾기 전에 거대한 모험부터 발표하십니다. 직장에서는 짧은 회의를 먼 지평선을 향한 선언문으로 바꿉니다. 사랑에서는 아무 제약 없는 동행을 약속하죠. 변하지 않는 유일한 것은 초대장 이름 옆의 물음표입니다.","열정이 너무 넘쳐서 날짜도 정하기 전에 활동 세 개를 예약하셨군요. 연인과는 각자 다른 나라로 가도 괜찮은 낭만 여행을 제안합니다. 쉬려고 거리도 확인하지 않고 길을 떠나죠. 이제 내비게이션은 도착 시간 대신 '개인적인 모험'이라고 표시합니다.","세계 순회 강연을 하는 철학자처럼 자신 있게 인생을 설명하십니다. 그런데 기념 연설까지 했던 프로젝트의 기념일은 잊어버리셨군요. 친구들은 일정이 바뀌어도 더는 놀라지 않습니다. 연락처에서 당신 이름을 '아마도'로 바꿔 놓았으니까요.","사무실에서는 남들이 생각을 마치기도 전에 있는 말을 다 하십니다. 연인에게는 일요일마다 독립권을 협상하죠. 당신식 휴식은 새로운 길을 발견하는 것입니다. 이렇게 많이 움직이면서 신청서 한 장은 끝내 작성하지 않을 수 있다는 걸 몸소 보여 주시는군요.","조용한 외출을 약속하고 '선택 사항'인 우회 경로 목록을 준비했습니다. 당신의 에너지는 이동을 대서사시로 바꾸고, 그 대서사시를 또 다른 제안의 핑계로 만듭니다. 현재를 붙잡는 기술에 관한 철학까지 갖고 계시죠. 희한하게도 약속을 확인해야 했던 그 순간만은 찾을 수 없네요."]},"capricorn":{"classic":{"career":["당신의 끈기는 복잡한 프로젝트에 모두가 의지할 수 있는 구조를 만들어 줘요.","큰 목표일수록 현실적인 단계로 나누고 함께하는 사람들에게 분명히 알려 주세요.","철저한 태도는 중요한 것과 일시적인 급한 일을 구별하는 데 도움이 돼요.","성과가 늦게 나타날 때는 지금까지 걸어온 길의 가치도 떠올려 보세요.","책임감은 신뢰를 불러오지만 다른 사람의 제안이 들어올 자리도 남겨 두세요.","진지한 모습 아래에는 오래 남을 무언가를 만들겠다는 깊은 포부가 있어요.","업무에서 세부 사항 일부를 맡기면 중요한 결정을 위한 여유가 생길 수 있어요.","프로젝트를 차근차근 세우는 데는 규율만큼 유연함도 필요할 수 있어요."],"love":["절제된 감정 표현 뒤에는 일상에서 오래 이어지는 성실함이 숨어 있어요.","튼튼한 관계도 목표 없이 즐기는 즉흥적인 순간들로 풍요로워집니다.","약속을 지키는 마음은 소중한 관계에 깊이를 더해요.","말로 다 전하기 어렵다면 진심 어린 작은 배려가 많은 것을 전달할 수 있어요.","안정감이 필요하더라도 상대의 새로운 면을 발견하는 즐거움을 함께 누릴 수 있어요.","겉으로 조용해 보여도 감정에는 숫자로 잴 수 없는 자리가 필요합니다.","가까운 사람이 고민을 말할 때 항상 해결책을 내놓아야 하는 건 아니에요.","계획 없이 함께 보내는 시간이 곁에 있는 사람과 더 가까워지게 할 수 있어요."],"wellbeing":["의무감이 강한 당신에게 휴식은 얻어야 하는 보상이 아니에요.","눈에 보이는 성과가 없어도 평온한 순간은 소중합니다.","규칙적인 태도가 도움이 되지만 하루의 모든 순간을 채워야 하는 것은 아니에요.","마음속에서 일주일을 미리 계산할 때는 지금의 호흡으로 천천히 돌아와 보세요.","정리하는 능력을 활용해 진짜 휴식 시간을 지켜 보세요.","야망을 품은 당신에게도 특별한 쓸모 없는 즐거움을 누릴 권리가 있어요.","할 일 사이에 시계 없이 걷는 산책을 마련해 보면 시간의 다른 모습이 보여요.","속도를 늦춰도 결의는 사라지지 않아요. 오히려 더 차분하게 이어질 수 있어요."],"wisdom":["당신의 가치는 성취 목록만으로 설명할 수 없습니다.","정상에 오르는 기쁨은 경치를 바라볼 때 더 깊어집니다.","튼튼한 계획은 변화할 수 있을 때 더욱 견고합니다.","모든 일에는 자기 자리가 필요해요. 휴식도 마찬가지입니다.","야망은 삶의 모든 지평선을 차지하지 않고도 자랄 수 있어요.","미래를 만든다고 현재를 놓칠 필요는 없습니다.","신뢰는 끊임없는 점검이 아닌 다른 방식으로도 자라납니다.","함께 걷는 사람을 잊은 채 오래갈 것을 만들 수는 없어요."],"roast":["모든 것을 관리하고 싶은 마음이 작은 돌발 상황까지 긴급한 문제로 만들 때가 있어요.","개인적인 목표가 삶을 즐길 공간까지 차지할 수 있어요.","철저함은 강점이지만 작은 오차를 받아들이기가 어려워질 때가 있죠.","누군가 즉흥적인 외출을 제안하면 가장 먼저 달력을 확인합니다.","효율성을 따지는 습관 때문에 취미까지 업무처럼 평가할 수 있어요.","진지한 모습 뒤에서 언제 정말 쉬는지 알기 어려울 때가 있어요.","계획이 조금만 바뀌어도 누가 일정표를 수정할지부터 찾습니다.","모든 세부 사항을 정리하면 마음은 놓이지만 즐거운 우연이 들어올 자리는 줄어들어요."]},"funny":{"career":["진로 계획에는 다음 직책과 그다음 직책, 감사 인사까지 적혀 있습니다. 아직 고민 중인 건 파일철 색깔이군요.","동료가 즉흥적인 아이디어를 냈습니다. 당신이 너무 상세한 역산 일정표를 건네서 즉흥성마저 납기일을 배정받았군요.","회의에는 목표가 세 개였는데 당신은 목표를 추적할 표와 그 표를 추적할 표까지 준비했어요.","사무실에 펜이 부족하면 분기별 소모량 조사를 시작합니다. 파란 펜은 증언을 거부해요.","업무 보고서가 너무 좋아서 손님에게 보여 주려고 제본할까 고민합니다.","모니터 아래 메모지들은 우선순위대로 정렬돼 있어요. 긴급이라는 단어조차 일련번호를 가집니다.","모두가 프로젝트 완료를 축하하는 순간 파티 개선 회의를 제안합니다.","진로를 계획하면 마음이 편안해져요. 10년 뒤 목표 직책이 이미 즐겨찾기에 있거든요.","당신의 야망은 표 다섯 칸과 회의 세 번에 담겨 있습니다. 마지막 칸에 누군가 '검토 필요'라고 쓰자 그 표현을 논의하는 워크숍을 열었군요.","연례 평가 면담을 우주선 발사만큼 철저하게 준비합니다. 그런데 로켓에 해당하는 건 역량 관리표 한 장이군요.","'내일 계획이 있나요?' '앞으로 7년간 계획은 있어요.' 질문이 너무 짧게 느껴지셨겠군요.","발표를 '다음 단계'로 끝냈습니다. 그런데 그 단계가 마지막이 아닌 이유를 설명하려고 슬라이드 열 장을 추가하셨네요."],"love":["당신의 낭만은 확인된 예약과 예비 우산, 최적화된 이동 경로로 표현됩니다.","깜짝 이벤트가 좋아요. 최소 사흘 전에 달력 초대를 받는다면요.","사랑하는 마음이 커서 선물 후보들의 보증 조건까지 이미 비교했어요.","무슨 감정인지 물으면 일단 진지한 마음이라고 답합니다. 나머지는 승인 뒤에 나와요.","촛불 저녁에 영감을 받아 최적의 식당 비교표를 만듭니다. 디저트에도 독립된 열이 있어요.","차분한 모습 뒤에서 감동적인 고백을 준비 중이에요. 파일 이름은 최종본 7이에요.","새로운 관계가 시작되자마자 주말 일정을 고민합니다. 상대는 그냥 외투를 찾고 있었는데요.","소파를 나눠 쓰는 건 큰 신뢰의 표시예요. 팔걸이에 자리를 하나 비워 줬거든요.","미래의 작은 부분까지 생각하며 애정을 표현합니다. 상대방은 벌써 당신의 장기 소풍 계획에 자기가 등장한다는 걸 알게 됐군요.","첫 만남이 너무 마음에 들어 앞으로의 기념일에 쓸 그릇까지 머릿속으로 고르셨군요. 품질보증서도 챙기셨고요.","당신이 가장 좋아하는 다정한 말은 '믿음직해요'입니다. 그 말을 작은 꽃 두 송이가 그려진 카드에 적기까지 한참 걸렸군요.","즉흥적인 사랑 고백이 감동적입니다. 그러고는 그 아름다운 생각이 오래갈 계획인지 다정하게 물으시는군요."],"wellbeing":["당신의 휴식은 오후 2시 정각에 시작됩니다. 2시 3분에는 계획대로 진행되는지 점검하죠.","목적 없는 산책은 수상해요. 결국 앱으로 이동 성과를 측정합니다.","낮잠을 자고 싶지만 효율을 위해 15분과 20분 중 어느 쪽이 나을지 아직 비교 중이에요.","쉴 때도 할 일 목록에 휴식 완료라는 항목을 뿌듯하게 체크합니다.","휴식을 위해 알림 두 개와 체크박스 하나가 필요해요. 쿠션은 그냥 앉아 달라고 합니다.","의무가 없는 저녁을 준비했습니다. 저녁 8시가 되자 프로젝트 관리자처럼 '아무것도 하지 않기'에 체크하시네요.","공원에서 똑같은 길이의 감상 휴식 세 번을 계획했습니다. 비둘기들은 시간표를 전혀 지키지 않네요.","속도를 늦추는 일이 너무 힘들어서 주간 보고서에 칭찬 한 줄을 넣을까 생각해요.","시골 여행의 휴식 프로그램에 그림까지 들어 있습니다. 해 질 녘 풍경은 아직 워크숍 신청을 하지 않았군요.","휴가를 더 잘 즐기는 방법을 찾으셨습니다. 시간 재지 않는 시간을 직접 재는 것이죠.","편안한 산책에는 세 단계와 선택 가능한 휴식 한 번이 있습니다. 당신만 진행 관리표를 들고 걷는군요.","오후 4시부터 4시 20분까지 안락의자를 예약해 뒀습니다. 의자가 드디어 행정적인 존재가 됐다며 기뻐하네요."],"wisdom":["대시보드는 마음껏 웃는 순간의 품질을 측정하지 못해요.","성과 없는 일요일도 완벽한 일요일입니다.","인내심을 가지고 쌓아 올린 것은 거대한 리본을 달아 자축한 것보다 오래 버티는 경우가 많습니다.","정상은 간식을 다 먹을 때까지 기다려 줄 수 있어요.","당신의 야망은 셈을 잘하죠. 안락의자는 품어 주는 법을 알아요.","튼튼한 미래를 만든다고 양말 하나 잃는 일이 금지되지는 않아요.","점심 식사마다 공식 회의록이 필요한 건 아닙니다.","휴식이 증빙 서류를 제출해야 한다는 증거는 어디에도 없어요.","정상은 한 걸음씩 올라갑니다. 가는 길에 꽃 한 송이를 감상해도 괜찮습니다.","인내는 재능입니다. 그렇다고 현관 계단 하나하나를 등반할 필요는 없죠.","인내는 다리를 만듭니다. 그 중간에 통행료 징수소만 세우지 않도록 조심하세요.","산조차 서두르지 않습니다. 그렇다고 성장 실적 보고서를 쓰지도 않죠."],"roast":["산책 한 번의 비용을 공짜 걸음 수로 계산하셨군요. 아무것도 사지 않는다는 조건하에 경제성이 입증됐습니다.","예상 못 한 선물을 받으면 웃으며 보증 양도가 가능한지 묻습니다.","어떻게든 되겠지라는 말은 당신에게 스릴러 영화보다 무서워요.","지금을 즐기라는 말을 들으면 평가 기간이 언제부터 언제까지인지 묻습니다.","장보기 예산에는 과자 가격도 한 푼까지 계산돼 있어요. 과자는 협상을 원합니다.","책임감 있는 사람이라는 외투 아래에서 마음속 아이는 아직 회계팀 승인을 기다려요.","연말 파티에서 즐거움에 관한 연례 결산을 제안합니다. 손님들은 못 들은 척해요.","당신 집에서는 즉흥성이 예정된 날에만 작동합니다.","펜의 개당 가격과 묶음 가격, 10년간의 비용까지 알고 계십니다. 공짜 펜은 영원한 존경을 받았군요.","시장에서 사과 가격을 1원 단위까지 비교합니다. 상인은 장바구니 대신 계산기를 건네줬군요.","3% 할인만으로 하루가 환해집니다. 영수증을 액자에 넣어 둘까 고민하셨군요.","당신에게 좋은 거래는 서사시로 남길 만한 사건입니다. 친구들은 아직 절약한 2유로를 설명하는 장을 기다리고 있습니다."]},"piquant":{"career":["당신의 야망에는 아이디어가 생기기도 전에 조직도가 있어요. 아이디어들은 이제 사전 면접을 봐야 합니다.","동료가 주말 이야기를 꺼내자 즉시 생산성을 물어요. 토요일은 사직서를 냈습니다.","팀원도 만나기 전에 5개년 계획부터 작성하셨군요. 동료들은 '확정되지 않은 자원'이라는 부록에 실렸습니다.","간단한 업무 하나를 맡아도 운영위원회를 만듭니다. 업무는 보석을 신청해 풀려나고 싶어 해요.","5개년 계획에는 즉흥적인 행동까지 예정돼 있어요. 즉흥성은 명예훼손으로 이의를 제기했습니다.","진지함 뒤에서 커피 시간은 삭감할 비용 항목이에요. 커피는 희망퇴직을 준비합니다.","예상 밖의 일이 생기면 책임자를 찾습니다. 우연은 인사팀 면담을 기다리고 있어요.","회사를 정리하는 일을 너무 좋아해서 미소까지 사용 빈도별로 분류했어요. 행복은 접속 권한을 잃었습니다.","당신의 5개년 계획에는 우수상과 비상 절차가 있습니다. 현재는 잠시 계약직으로 배정됐군요.","15분짜리 회의를 전략위원회로 바꿨습니다. '안녕하세요' 안건도 의견 수렴 단계에 들어갔군요.","가상의 부서 설문입니다. 목표 100%에 일정이 지정돼 있습니다. 정작 동료들은 조직도에서 자기 이름을 찾는 중이네요.","야망이 자체 시상식부터 계획했습니다. 결과는 아직 없지만 행사 순서만큼은 흠잡을 데 없군요."],"love":["당신의 로맨스는 타당성 검토부터 시작해요. 상상 속 설렘조차 추천서 세 장을 제출해야 합니다.","사랑을 오래갈 건축물처럼 생각하십니다. 첫 데이트마저 공사 현장 점검처럼 대하는 건 조금 아쉽군요.","당신의 다정함은 신중하게 협상된 제안서 같아요. 꽃다발은 법무팀 면담을 요청했습니다.","예상 못 한 저녁 초대를 받으면 의사일정부터 요구해요. 촛불들이 파업에 들어갔습니다.","조심스러운 마음은 문을 여는 대신 입찰을 진행해요. 지원서 접수는 지난 화요일에 끝났습니다.","조용한 감정 뒤에는 신뢰 계약서 열두 조항이 있어요. 즉흥성은 자격 기준에 미달합니다.","다정한 말을 받으면 감동하시네요. 그리고 그 말을 '진지함의 증거' 폴더에 넣어 저녁 예약과 향후 5년 계획 사이에 보관합니다.","함께할 미래를 나누는 일이 자연스럽죠. 디저트를 고르기도 전에 예측 자료를 출력했으니까요.","당신의 연애 방식은 등대 건설 같습니다. 튼튼하고 앞날을 내다보지만 저녁 식사 하나 고르기엔 조금 거창하죠.","세 번째 데이트에서 도시계획가처럼 엄숙하게 미래를 이야기합니다. 상대방은 영화 한 편 보러 가자고 하려던 참인데요.","당신의 낭만에는 서비스 지속성 조항이 있습니다. 첫날의 설렘조차 유지보수 일정표를 받았군요.","'우리 미래를 생각하세요?' '물론이죠. 폴더 이름까지 정했어요.' 다정함에는 좀 덜 사무적인 첫마디가 어울리겠네요."],"wellbeing":["주말 휴식에 필수 단계 네 개와 만족도 설문지가 있습니다. 쿠션은 두 번째 단계에서 포기했군요.","자유로운 산책은 비효율적이죠. 나무 두 그루 사이의 경로를 최적화하자고 제안합니다. 나무들은 합병을 거절해요.","당신 집의 휴식은 출입증과 엄격한 운영 시간을 가지고 도착합니다. 증빙 서류가 없으면 입장 불가예요.","휴식 시간이 시작되면 휴식 계획부터 확인합니다. 오후가 자기 평온함의 일정에도 지각하고 말았군요.","조용한 일요일도 분 단위로 계획돼 있어요. 하품마저 참석을 확인해야 합니다.","담요 밑에서 쉬는 시간을 제대로 쓰는지 평가합니다. 담요는 장기휴가를 신청했어요.","지루함이 찾아오자마자 휴식 개선 프로젝트를 시작합니다. 휴식은 단체 채팅방을 나갔습니다.","풍경을 감상할 시간을 따로 예약하셨군요. 3분째 되자 산이 체계적으로 움직이지 않는다고 의심하십니다.","이상적인 휴가를 위해 스프레드시트를 만들었습니다. 첫 결과는 '오류: 즉흥성 부족'이군요.","휴식 시간에 안건표와 종료 시각을 지정했습니다. 침묵은 참석하지 않기로 했군요.","취미 활동 기상 예보입니다. 하늘은 맑지만 계획 압력이 높습니다. 낮잠은 달력 뒤에 숨어 있군요.","산책을 검증 가능한 과제 세 개로 바꾸셨군요. 공원에서 가장 오래된 나무도 이런 감사를 본 적이 없습니다."],"wisdom":["당신의 야망은 산을 오른 뒤 정상에서 승진을 요구해요.","인내는 제국도 세웁니다. 그렇다고 돌멩이 하나마다 이사회를 열 필요는 없어요.","신중함이 당신 머릿속에 컨설팅 회사를 차렸어요.","정상은 노력 끝에 얻는다고 당신의 철학은 말합니다. 그런데 오르는 동안에도 경치가 있다는 걸 잊었군요.","꾸준함을 신발 끈을 절대로 느슨하게 풀지 말라는 의무와 혼동하셨군요.","미래를 만드는 건 고귀해요. 미래에 청구서까지 보내는 건 조금 덜 고귀합니다.","즉흥성도 있긴 해요. 예상 못 한 사고라는 폴더에 넣어 뒀죠.","오래도록 무언가를 세우는 일은 멋집니다. 하지만 휴식마다 기초 공사를 하는 건 걱정 많은 건축가의 취향이겠죠.","정상은 전망이 좋은 사무실이 아닙니다. 그런데 당신의 야망은 벌써 명패를 달았군요.","인내를 정원처럼 가꾸면서 잎 하나하나를 자로 재고 계시네요.","오래가는 것에는 튼튼한 기초가 필요합니다. 미소 하나마다 콘크리트를 부을 필요는 없어요.","당신의 진보 철학은 돌아가는 길의 기쁨을 잊었습니다. 길은 곧지만 이야기는 짧군요."],"roast":["당신의 달력에서 생일은 기념일이 아니라 계약상 마감일이에요. 촛불은 청구서를 기다립니다.","친구들이 커피까지 고른 동안 디저트 두 개의 가격을 비교하셨군요. 최종 결론은 집에서 먹는 편이 이득이었다는 것입니다.","소파를 산 뒤로는 사용 시간 대비 수익성을 걱정합니다. 소파는 초과근무 수당을 요구해요.","즉흥적으로 하자는 말에 비상대책위원회가 소집됩니다. 돌발 상황은 비상구로 도망쳤어요.","조심스러운 마음에는 은행망보다 방화벽이 많아요. 칭찬은 수상한 활동으로 차단됩니다.","진지함 속에 품질관리 담당자가 숨어 있어 깜짝 이벤트도 평가합니다. 깜짝 이벤트들은 부서 이동을 신청해요.","무언가를 축하하기도 전에 촛불 하나당 비용을 계산하셨군요. 케이크 대신 절약액 막대그래프가 등장했습니다.","행복을 표로 관리하는 게 합리적이라고 생각했죠. 기쁨이라는 셀에서 수식 오류가 발생했습니다.","저녁 모임의 비용과 거기서 생길 추억의 가치를 비교합니다. 영수증 없는 추억은 수익성이 떨어진다고 보시는군요.","속보입니다. 선물값을 아낄 방법을 찾으셨군요. 가까운 사람들은 이를 '아주 아름다운 설명'이라고 부릅니다.","저금통에 저금통용 저금통이 있습니다. 세 번째 저금통은 지출 관리 책임자로 임명됐군요.","'무료'라는 말에 행진곡보다 더 신나십니다. 그래도 작은 글씨의 조건은 꼼꼼히 확인하시죠."]},"roastMy":["염소자리인 당신은 휴가를 떠나는 게 아닙니다. 작전 계획을 실행하는 거죠. 이동과 휴식, 낮잠까지 모두 색상 코드가 있어요. 가족이 바다를 바라보자고 합니다. 당신은 그 활동의 전략적 목표가 무엇인지 묻습니다.","당신의 야망은 자서전 제목까지 이미 정해 놨어요. 장과 부록, 출간일도 계획했죠. 빠진 부분은 즐겁게 놀았던 순간이라는 장이에요. 편집부는 당신의 일정이 비기를 기다립니다.","당신은 안전과 숫자, 확실한 결정을 좋아해요. 누군가 즉흥적인 저녁을 제안하면 기쁨에 숨은 비용을 분석합니다. 일행은 당신 없이 출발해요. 당신은 나중에 사고 보고서를 요청합니다.","염소자리인 당신의 달력엔 빈칸이 없어요. 빈칸마저 예약돼 있죠. 두 개의 결산 사이에 즉흥성을 위한 시간을 잡았습니다. 즉흥성은 참석을 확인하지 않았어요. 마지막 독촉장을 보내는 중입니다.","당신의 돈에 대한 태도는 모든 물건과 끊임없이 협상하는 모습 같아요. 마음에 드는 램프를 발견하고 사용 횟수당 미소가 몇 번 생길지 계산합니다. 직원이 색깔을 고르라고 하죠. 당신은 5개년 전망표를 요구합니다.","당신은 코미디를 보면서도 진지해 보여요. 장면 구성과 시간 운영을 분석하거든요. 다른 사람들은 웃고 있어요. 당신은 유머 생산성을 개선할 여지가 있다고 기록합니다.","당신의 로맨스는 믿음직하지만 행정적인 구조를 갖고 있어요. 예약과 비교, 확인과 시간 검증을 모두 마치죠. 상대가 다정하다고 말합니다. 당신은 수령 확인 서명을 해 줄 수 있느냐고 물어요.","염소자리인 당신은 휴식을 최고 수준의 규율로 바꿨어요. 산책 시간과 주말 목표를 정합니다. 돌아와서는 결과 보고서를 작성해요. 의자는 당신과 떨어진 곳으로 휴가를 가고 싶어 합니다.","당신의 끈기는 존경스럽지만 일을 절반만 하고 멈추지 않아요. 문제는 끝난 일도 끝났다고 인정하지 않는다는 거죠. 장보기 목록마저 위원회 승인을 받아야 합니다. 위원회는 장보러 갈 시간이 없어요.","생일에도 회의록이 필요하다고 믿는 사람은 당신뿐일 거예요. 장식은 승인됐고 일정은 지켜졌으며 과자는 정확히 배분됐죠. 손님들이 생일 노래를 불러 줍니다. 당신은 종료 보고서에 예정에 없던 열정이라고 적습니다.","이미 성공을 기념할 발표 자료와 부록 세 개를 준비했습니다. 사랑에서는 전채요리도 끝내기 전에 장기 계획을 세웁니다. 쉬는 날에는 여가 시간 그래프를 만드시죠. 가족들은 당신의 달력을 '가족의 네 번째 구성원'이라고 부릅니다.","염소자리인 당신의 목표는 너무 정확해서 미래의 즉흥적인 행동에도 내부 참조번호가 붙어 있습니다. 사랑을 보여 주려고 우산 두 개와 정시 도착 보증을 준비하죠. 쉬는 시간에는 그 휴식이 제 기능을 하는지도 확인합니다. 베개는 독립을 고려하고 있군요.","당신은 성당을 짓듯 프로젝트를 쌓아 올립니다. 천천히, 완벽한 기술 서류와 함께요. 그러다 어떤 아이디어에 반하면 곧장 무기한 계약을 제안합니다. 휴가가 끝나면 휴식 보고서를 제출하죠. 석양은 '기준 충족' 판정을 받았습니다.","당신에게 작은 절약도 자세히 이야기할 승리입니다. 사무실에서는 야망을 5년치 이정표로 정리하죠. 사랑에서는 화려한 놀라움보다 신뢰가 더 애틋합니다. 너무나 한결같아서 손목시계가 당신의 일정표를 보고 시간을 맞출 정도군요.","당신의 휴식 계획은 새 부서 출범 계획과 비슷합니다. 산책 코스를 고르고 시간을 계산하고 귀가 후 결산도 준비했죠. 한편 큰 직장 프로젝트는 예정된 칸만큼 정확히 전진합니다. 즉흥적인 기쁨은 '흥미로운 제안, 추후 재검토'로 분류됐군요."]},"aquarius":{"classic":{"career":["기존 습관이 가능성을 가로막을 때 당신의 독창성은 새로운 길을 열어 줍니다.","대담한 아이디어도 다른 사람이 따라올 수 있는 단계로 구체화할 때 힘을 얻어요.","관습에서 한 걸음 떨어져 보는 태도는 당연한 것에도 질문하게 합니다.","불필요해 보이는 규칙이 있다면 그 배경을 이해할수록 더 나은 변화를 제안할 수 있어요.","독립적인 정신은 모두가 자유롭게 기여하는 협력 속에서 더 강해집니다.","남다른 관점 뒤에는 공동체를 발전시키고 싶은 진심이 있어요.","직장에서 다르게 생각하는 능력은 막힌 상황을 풀어내는 데 귀중해요.","새로운 직감을 인내심 있게 공유하면 독특한 생각도 자리를 찾을 수 있어요."],"love":["독립성을 바라는 마음과 스스로 선택한 다정한 관계는 함께할 수 있어요.","뜻밖의 대화에서 서로의 공통점을 발견하며 관계가 자라기도 해요.","다른 사람을 향한 호기심에 세심한 관심을 더하면 대화가 더욱 깊어져요.","감정을 잘 드러내지 않을 때는 소박한 말 몇 마디가 애정을 알아보기 쉽게 해 줍니다.","차이를 좋아하는 태도는 상대방을 습관으로만 판단하지 않고 발견하게 합니다.","겉으로는 거리를 두는 듯해도 당신의 성실함은 독특한 방식으로 나타나요.","관계의 중심에는 정해진 틀보다 진정한 모습이 중요해요.","서로 다른 속도를 존중하면 각자가 자유롭고 인정받는 공간이 만들어져요."],"wellbeing":["새로운 것을 만들어 내는 정신에도 아무 아이디어도 요구받지 않는 시간이 필요해요.","익숙한 장소를 산책하는 일도 일상을 새로운 시선으로 바라보게 할 수 있어요.","탐험할 자유만큼 속도를 늦출 자유도 당신에게 있어요.","생각이 많아질 때 단순한 활동 하나가 현재로 시선을 되돌려 줍니다.","새로움을 향한 마음과 스스로 선택한 편안한 휴식 습관은 균형을 이룰 수 있어요.","지적인 움직임을 좋아하는 마음 뒤에도 고요함이 들어올 자리가 있어요.","바쁜 하루에는 화면에서 떨어져 있을 시간을 지키는 것도 좋아요.","혼자만의 시간과 진심 어린 대화 중 무엇이 힘이 되는지 자신의 마음에 따라 선택해 보세요."],"wisdom":["다름의 가치는 다른 사람의 다름도 받아들일 때 완성됩니다.","규칙은 바꾸기 전에 이해해 볼 가치가 있어요.","새로움은 삶을 더 풍요롭게 할 때 소중합니다.","자유로운 정신도 자신을 잃지 않고 경청할 줄 알아야 합니다.","독립적이라고 다른 사람을 멀리해야 하는 건 아니에요.","다르게 생각한다고 잘 작동하는 것까지 버릴 필요는 없습니다.","미래는 현재를 돌보는 사람들의 것이기도 해요.","독창성 때문에 소박함을 잊을 필요는 없습니다."],"roast":["관습을 싫어하다 보면 사실 불편하지도 않았던 습관에 반대할 수 있어요.","빛나는 아이디어도 새 생각 세 개가 바로 뒤따르면 다른 사람들이 따라오기 어려워져요.","감정적 거리를 두면 편할 수 있지만 가까운 사람들은 혼란스러울 수 있어요.","모두가 같은 해결책을 고르면 그 해법의 문제부터 찾으려 해요.","반항심이 제안을 끝까지 듣기도 전에 일어날 때가 있어요.","독창성에 대한 애착 뒤에서 단순한 해법들은 검토받기를 기다립니다.","어떤 유행이 널리 알려지는 순간 갑자기 관심을 잃을 때가 있어요.","다른 사람을 따르지 않는 것을 너무 좋아해서 자기 조언까지 거부하기도 해요."]},"funny":{"career":["당신의 상상력은 회의를 연결된 수족관으로 대체하자고 제안해요. 동료들은 그냥 커피 휴식을 원했는데요.","부서에서 커피 머신을 간단하게 만들자고 하자 날씨를 보고 음료를 고르는 기계를 제안하셨군요. 이제 커피는 비가 오길 기다립니다.","상사가 절차를 따르라고 하자 정중히 묻습니다. 그 절차는 누가 허가했나요?","사무실 의자가 바뀌면 자율주행 가구를 제안해요. 의자는 벌써 제자리에서 빙빙 돌고 있습니다.","미래의 일하는 방식을 상상하는 건 즐겁죠. 오늘 해야 할 일은 아직 받은 편지함에서 기다립니다.","회의 중 조용히 있는 건 키보드를 새롭게 발명할 생각을 하기 때문이에요. 정상이라는 키는 이미 삭제했습니다.","아이디어 회의에서 의자를 이동식 플랫폼으로 바꾸자고 제안하셨군요. 첫 지원자는 복도까지 굴러갔습니다.","발견한 것을 공유하기 좋아해서 동료들은 존재하는 줄도 몰랐던 주제의 강연을 듣습니다.","음성 명령으로 클립을 나눠 주는 기계를 설계하셨군요. 부서는 결국 테이블 위의 그릇을 골랐습니다. 훨씬 조용했거든요.","회의에서 서류 양식을 공동 그림으로 바꾸자고 제안합니다. 회계 담당자는 아직 '합계' 칸을 찾고 있군요.","지침에는 '제공된 양식을 사용하세요'라고 적혀 있습니다. 그런데 완전히 재설계한 실험용 양식을 내놓으셨네요. 지침에는 단수형으로 적혀 있었는데요.","창의성을 키우려면 키보드 없는 날이 필요하다고 제안하셨군요. IT 지원팀은 벌써 연필 상자를 준비 중입니다."],"love":["당신만의 애정 표현은 특별해요. 평범한 다정한 문자 대신 해파리에 관한 놀라운 기사를 보내죠.","낭만적인 저녁으로 미래형 가구 전시회를 제안해요. 상대방은 스마트 의자를 처음 만납니다.","거리를 유지하는 게 자연스러워요. 단체 메시지엔 열정적으로 답하면서 개인 메시지는 잊어버립니다.","즉흥적인 애정 표현을 부탁받으면 맞춤형 칭찬을 나눠 주는 기계를 만듭니다.","독립심이 강해도 진심 어린 관계를 좋아해요. 소파에 리모컨 두 개가 각각 있어야 한다는 조건으로요.","무심한 표정 뒤에는 사랑스러운 깜짝 이벤트가 준비돼 있어요. 다만 작은 로봇을 조립해야만 즐길 수 있죠.","식당에서 메뉴 선택도 식생활의 미래에 관한 토론으로 바꿉니다. 감자튀김은 자기 차례를 기다려요.","함께 드라마를 보는 게 즐거웠다가 모두가 그 드라마를 좋아한다고 하자 갑자기 생소한 다큐멘터리를 추천합니다.","기발한 발견을 공유하며 애정을 표현합니다. '당신 생각이 났어요'라는 메시지에는 문어의 생활 습성에 관한 링크가 들어 있군요.","이상적인 데이트는 깊은 우정과 서로 다른 산책 경로 두 개로 시작합니다. 나중에 만나 각자 걸은 길을 이야기하죠.","멀리 떨어져 보내는 저녁이 너무 편해서 자신의 디저트 사진 대신 그림을 보내셨군요.","'곧 만날까요?' '물론이죠, 늘 만나던 공간에서요.' 상대방은 온라인 채팅방이 아니라 집 거실을 말한 거였는데요."],"wellbeing":["이상적인 휴식은 화면을 끄는 일이에요. 먼저 화면을 끄라고 알려 주는 앱부터 개발합니다.","공원 산책이 비둘기의 사회생활에 관한 연구로 변해요. 가설도 이미 세 개나 있어요.","혼자 있는 시간이 힘이 되지만 휴대전화에는 자유의 의미를 논하는 단체 채팅방이 여덟 개나 있습니다.","아무것도 하지 않기로 결정하면 더 효율적으로 아무것도 하지 않는 새로운 방법을 설계합니다.","발명가다운 정신이 차 한 잔도 최적의 음용 온도를 찾는 실험으로 바꿔요.","연구자 같은 호기심 뒤에서 쿠션은 원래 기능을 시험해 주기만을 기다립니다.","잠들려는 순간 혁명적인 아이디어가 떠오릅니다. 베개는 내일 특허를 신청하자고 제안해요.","속도를 늦추는 것도 스마트워치로 효과를 측정할 수 있다면 매력적이에요. 시계는 휴식을 요청합니다.","천천히 쉬려고 스마트 조약돌을 샀습니다. 조약돌은 하루 종일 와이파이를 찾고 있군요.","앱에서 평온한 순간을 세어 준다고 합니다. 당신은 측정 앱들을 비교하느라 한 시간을 쓰셨네요.","새 휴식 실험은 로봇이 녹음한 숲 소리를 듣는 것입니다. 진짜 공원은 집에서 한 블록 거리에 있는데요.","새벽빛을 재현하는 램프를 시험합니다. 정오에 켜졌지만 당신의 실험 일정과는 완벽히 조화를 이루는군요."],"wisdom":["미래는 대담한 사람의 것입니다. 그렇다고 매일 아침 양말을 새로 발명할 필요는 없습니다.","미래의 아이디어도 리모컨을 찾는 일에서 시작할 수 있어요.","남들보다 내일을 먼저 보는 건 좋습니다. 단, 오늘의 약속을 잊지 않는다면요.","모든 사람은 독특해요. 매 식사마다 입증할 필요는 없지만요.","자유는 잘 작동하는 요리법을 받아들인다고 줄어들지 않아요.","혁신이 반드시 숟가락을 바꾸는 걸 뜻하지는 않습니다.","미래는 내일 시작돼요. 빨랫감은 어제부터 기다립니다.","다른 사람이 옳다면 그들과 똑같이 행동해도 괜찮아요.","다음 위대한 발견도 차 한 잔을 다 마실 때까지는 기다려 줄 수 있습니다.","다른 시각으로 보는 건 마음을 넓힙니다. 가끔은 한 번쯤 평범하게 살펴봐야 불필요한 우회를 피할 수 있죠.","미래는 발명하는 사람들의 것입니다. 현재는 시제품을 정리하는 사람들에게 고마워하겠죠.","남보다 앞선 아이디어가 있다고 해서 모두가 달력을 읽지 않았다는 뜻은 아닙니다."],"roast":["평범함을 거부하는 일이 너무 규칙적이어서 가족 전통처럼 보이기 시작했어요.","잘 작동하는 아이디어라도 두 번째 사람이 쓰기 시작하면 지루해해요. 즉시 이해할 수 없는 버전을 만듭니다.","날씨를 이야기하던 중 당신은 떠다니는 도시 이론을 발표합니다.","아무도 나를 이해하지 못한다고 말하면 모두가 그림을 다시 설명해 달라고 합니다.","반항심에 가장 독특한 길을 골라요. 청소도구 보관실로 이어지는 길일지라도요.","무심한 태도 뒤에서는 멀리서 사랑하는 친구들의 알림 마흔 개가 쌓여 있습니다.","식당에서 가장 신기한 음식을 주문하고는 진짜 신기해서 놀랍니다.","꼬리표를 싫어하는 게 특기라 새 꼬리표를 만들었어요. 꼬리표 거부 전문가라는 꼬리표죠.","아무도 모르는 음악을 발견했다고 자랑하셨군요. 이제 어디서나 나오자 '실망스럽다'고 하십니다.","'저는 남들과 똑같은 건 싫어요'라고 말하며 신비한 음료를 고르셨군요. 삼각형 잔에 담긴 물이었습니다.","친구들이 새로운 유행을 받아들이자마자 벌써 낡았다고 설명하십니다. 당신의 열정은 유통기한이 아주 짧군요.","질문을 받게 만드는 옷차림을 제일 좋아하십니다. 아무도 반응하지 않자 직접 그 콘셉트를 설명하시네요."]},"piquant":{"career":["다르고 싶은 욕구로 잘 작동하는 도구를 다시 발명해요. 새 도구는 교육 세 번과 개막식이 필요합니다.","사무실 지침을 열두 쪽짜리 선언문으로 바꿔 버리셨군요. 마지막 문단에서는 원래 지침을 그대로 다시 발명합니다.","아무도 안 쓸 때만 새로움에 끌려요. 팀이 당신의 아이디어를 채택하자 곧바로 구식이라고 선언합니다. 팀은 중재자를 요구해요.","상사가 절차를 설명하면 절차를 허가하는 절차부터 보여 달라고 해요. 법무팀은 커튼을 닫았습니다.","선견지명이 뛰어나서 10년 뒤의 일을 하고 있어요. 금요일 마감 문서는 실종 신고를 했습니다.","공동체를 사랑한다는 연설 뒤에는 조건이 있어요. 공동체가 먼저 당신이 옳다고 인정해야 합니다. 민주주의는 점검 중이에요.","합의가 이뤄지면 바로 반대파가 됩니다. 방금 낸 자신의 제안까지 스스로 반대했어요.","직원들의 아이디어를 수집하는 커피 머신을 제안하셨군요. 기계는 방금 그 계획을 '에스프레소 한 잔에 너무 복잡함'으로 분류했습니다.","투표 알고리즘으로 커피 머신을 민주화하려 하시는군요. 이제 에스프레소 한 잔도 총회 참석 없이는 받을 수 없습니다.","상사가 간단한 해결책을 허락했습니다. 당신은 간단함에 반대하는 선언문과 부록, 혁명 도표를 발표하셨군요.","종이 없는 사무실 시제품이 문서를 읽을 수 없는 QR 코드로 바꿨습니다. 현대화에는 성공했지만 유용성은 그대로군요.","이미 잘 작동하는 절차를 혁신하셨군요. 똑같이 작동하지만 충전할 배터리가 세 개 늘었습니다."],"love":["당신의 독립성은 감정용 방 두 개와 비상구, 제한된 감정 접근 권한을 예약했어요. 다정함은 출입증을 기다립니다.","사랑 고백보다 평범한 질문이 더 당황스러워요. 저 생각해 봤어요라는 물음에 머릿속이 강연을 준비합니다.","감정적 거리는 매력적으로 보일 수 있어요. 그러다 사람들이 가끔은 메시지 답장을 더 원한다는 걸 깨닫죠.","당신에게 우정은 최고의 낭만입니다. 상대방은 데이트 약속 대신 회원증을 받은 기분이군요.","둘만의 만남을 위해 서로 다른 장소 두 곳을 골라 멀리서 메시지를 주고받자고 합니다. 물리적으로 가까워지는 건 유료 옵션이군요.","신비로운 미소 뒤에는 평범한 이유가 숨어 있어요. 발명품을 생각하고 있었죠. 로맨스는 알지 못했어요.","늘 하던 대로 하자는 말이 나오자 가정 혁명을 소집합니다. 저녁에 접시를 쓰자는 이야기였는데요.","감정을 나누려면 개념 발표 자료부터 준비하고 싶어 해요. 마음은 슬라이드 없는 버전을 요구합니다.","사랑하는 사람에게 특별한 자리를 남겨 둡니다. '최고의 친구'와 '흥미로운 대화 상대' 사이쯤이죠. 실제 일상에서는 50킬로미터 떨어진 곳이고요.","거리감을 강요하지 않는 관계를 좋아하십니다. 그런데 메시지는 다른 은하에서 보낸 엽서처럼 도착하네요.","고백은 두 문장입니다. '당신은 제게 소중해요.' 그리고 각자 따로 사는 장점에 관한 완전한 강의가 이어집니다.","당신에게 가까워지는 일은 이론적으로 토론할 주제입니다. 상대방은 그냥 손을 잡고 싶었는데요."],"wellbeing":["쉬고 있는지 확인하려고 센서를 설치하셨군요. 기계에는 설정하는 데 쓴 시간만 기록되고 있습니다.","조용한 산책도 너무 관습적이라 평소 경로를 거꾸로 걸어요. 지도는 감정을 요청합니다.","휴식용 기기가 소리 열 가지, 진동 세 가지, 보정 신호 하나를 냅니다. 결국 끄고 나서야 조용해졌군요.","다른 사람들이 휴대전화를 끄면 당신은 다시 켤 새로운 이유를 발명합니다. 비행기 모드는 사표를 냈어요.","미래지향적인 정신이 수면을 개선할 혁신을 찾고 있어요. 스탠드는 그냥 불을 끄라고 제안합니다.","무심한 태도 뒤에서는 집단을 따르지 않는 법을 논하는 모임 세 곳을 감시하고 있어요. 모순이 정기 구독을 신청했습니다.","신선한 공기를 마시려다가 공원의 환기 이론부터 제시합니다. 나무들은 기밀 유지를 요청해요.","스마트 낮잠 앱을 시험합니다. 잠들지도 않았는데 잘했다고 축하하려고 깨우네요.","휴식용 팔찌 설명서가 한 주보다 길군요. 설정 세 번 만에 서랍에 넣어 버리고서야 편안해지셨습니다.","가상의 기술 보고서입니다. 새 스마트 헤드셋 때문에 휴식 실험이 실패했습니다. 헤드셋은 애초에 쉴 생각이 없었군요.","센서와 알림, 대시보드를 갖춘 휴식 시스템을 만들었습니다. 모든 기능이 있지만 '정지' 버튼만 없네요.","원격 조종 미니 분수를 시험합니다. 물이 흐른다는 사실을 알리려고 알림을 서른 개나 보내는군요."],"wisdom":["너무 먼 미래를 바라봐서 현재가 잊힌 첨부파일처럼 보이는군요.","이해할 수 없는 생각이라고 자동으로 시대를 앞선 건 아니에요.","열린 문을 향한 반란은 꽤 극적인 입장 방식이군요.","모두가 당신을 따라 하는 건 아니에요. 어떤 사람은 그냥 의자를 샀어요.","당신의 독립성은 관계를 거부하면서도 단체 채팅방은 즐겨찾기에 넣습니다.","지시를 피하려고 혁신하다가 그 지시를 위한 궁전까지 지었군요.","미래가 궁금하겠지만 현재는 아직도 당신의 답장을 기다립니다.","시대를 앞서 간다고 문이 어디 있는지까지 안다는 보장은 없습니다.","당신은 시대보다 100년 앞서 계십니다. 시대는 정중하게 시연을 기다리는 중이죠.","미래가 새롭다고 반드시 복잡해야 하는 건 아닙니다. 당신의 나침반은 아직 이해하려고 애쓰는군요.","뛰어난 아이디어는 내일을 밝힙니다. 당신의 아이디어에는 가끔 스위치 설치가 빠져 있군요.","내일을 너무 자신 있게 바라봐서 현재가 실종 신고서를 접수하러 갔습니다."],"roast":["당신의 차별성은 너무 중요해서 공식 독창성 증명서를 요구해요. 신청서는 모두에게 똑같습니다.","평범한 발명도 당신에게는 패러다임 전환이에요. 상자에 라벨 하나 붙였을 뿐인데요.","감정적으로 가까워지는 건 수상해요. 인류 전체를 사랑하지만 대화할 때는 2미터 거리 유지가 조건이죠.","다른 사람들이 좋아하는 음악을 발견하면 그 곡을 바로 버립니다. 재생기는 안정적인 정체성을 요구해요.","당신의 남다름이 개인 브랜드가 됐군요. 유행이 따라잡는 순간 이름이 끝나기도 전에 취향을 바꿉니다.","별난 아이디어 사랑 뒤에서는 단순함에 대한 개인적인 전쟁이 벌어지고 있어요. 숟가락은 이웃집으로 피신했습니다.","모두가 동의하자 즉시 반대편으로 이동합니다. 옛 의견들은 공식 야당을 결성했어요.","소파에서 세계를 혁명하는 일로 바빠요. 소파는 먼저 리모컨부터 찾아 달라고 합니다.","첫 팬이 나타난 날 가장 좋아하던 취미를 그만두셨군요. 이쯤 되면 취향보다 추격전 같습니다.","당신의 개성은 '아무와도 닮지 않음'이라는 특허를 신청했습니다. 신규성이 부족하다는 이유로 거절됐군요.","속보입니다. 어제까지 당신이 옹호하던 유행이 대중화됐습니다. 벌써 세 쪽짜리 비판 글을 발표하셨네요.","아무도 모르는 유행을 찾았습니다. 발견하자마자 떠났습니다. 이제 그것을 아는 사람이 한 명 생겼거든요."]},"roastMy":["물병자리인 당신은 단순히 남다른 게 아닙니다. 남다름을 정기 구독 서비스로 만들었죠. 인기 있는 취향을 거부하고 자기 취향까지 유행하면 버립니다. 당신의 정체성은 매주 목요일 진열장을 바꿔요. 독창성마저 계약을 해지했습니다.","당신의 머릿속은 아무도 겪지 않는 문제의 해결책을 발명해요. 스위치를 앱으로 바꾸고 앱을 실험용 시제품으로 다시 바꿉니다. 방은 계속 어두워요. 그런데도 역사적인 기술 성공을 선언합니다.","당신은 모두를 좋아하지만 법정 거리만큼 떨어져서 좋아해요. 친구가 하루 이야기를 하면 사회의 진화에 관한 링크로 답합니다. 친구는 다정한 한마디를 기다려요. 당신은 수정된 링크를 또 보냅니다.","물병자리인 당신은 규칙을 읽기도 전에 반대해요. 자유롭고 혁신적이며 완전히 새로운 체계를 제안합니다. 세 쪽 뒤에는 규칙 열일곱 개와 감독 위원회가 생겨 있어요. 옛 규칙이 복권을 요구합니다.","당신의 미래는 놀라운 발명품으로 가득해요. 현재는 잃어버린 충전기와 쌓인 서류뿐이죠. 물질적인 물건은 낡은 개념이라고 설명합니다. 서류들은 기록관리자를 요구해요.","당신은 독립성을 거의 의식처럼 선언해요. 커피를 권받으면 모두가 마신다는 이유로 거절합니다. 그러고는 이상한 컵에 똑같은 음료를 만들어 마셔요. 커피는 평범함에 지원서를 내고 싶어 합니다.","당신의 무심한 눈빛은 우주의 비밀을 아는 것처럼 보여요. 사실 냉장고에 미니 정원을 만드는 생각을 하고 있죠. 괜찮냐는 질문에 수직 농업에 관한 강연으로 답합니다.","물병자리인 당신은 분류당하는 걸 싫어해요. 그런데 평범한 사람과 대담한 사람, 당신을 이해하지 못하는 사람을 구분하는 체계를 이미 만들었죠. 누구도 천재라는 정의에 맞지 않아요. 신기하죠. 그 칸은 자신을 위해 비워 뒀거든요.","당신은 시대보다 늘 5년 앞서 있다고 믿어요. 아무도 이해하지 못하는 프로젝트를 제시하고 쉽게 설명하길 거부한 뒤 남들이 뒤처졌다고 말하죠. 하지만 프로젝트는 혁명적인 게 아니에요. 내비게이션 화면이 달린 토스터입니다.","새로움을 향한 욕구는 저녁 식사를 미래에 관한 강연으로 바꿉니다. 아이디어 여덟 개와 시제품 세 개, 습관 없는 세상을 발표하죠. 손님들은 그냥 소금을 찾고 있어요. 당신은 소금이 월요일부터 탈중앙화된다고 선언합니다.","물병자리인 당신은 평범한 일을 쉽게 해 주는 기계를 설계했습니다. 콘센트 세 개와 이웃의 동의가 필요하군요. 감정적인 관계에서는 우주만큼 깊은 우정부터 시작하려 합니다. 기계도 데이트도 첫 사용을 기다리고 있습니다.","당신의 호기심은 아무도 상상하지 못한 발명으로 멋진 미래를 만듭니다. 가까운 사람에게 좋은 하루를 보내라며 스마트 기기를 선물하셨군요. 기기는 저녁 내내 업데이트를 설치합니다. 애정은 분명하지만 케이블을 빠뜨리셨네요.","직장에서는 절차를 급진적인 새 아이디어로 바꾸자고 합니다. 퇴근 후에는 여가를 개선한다는 기계를 시험하죠. 다음 날 누군가 당신이 좋아하던 발견을 채택하자 곧바로 다른 취미로 옮겨 갑니다. 성공을 포기의 이유로 삼는 사람은 당신뿐이겠군요.","미래에 관한 공식 프로그램을 미리 받은 사람처럼 내일을 이야기하십니다. 연애에서는 평범한 저녁보다 지적인 대화를 선호하죠. 쉬려고는 아무도 시험하지 않은 방법을 골라 봅니다. 이 모든 것에서 유일하게 안정적인 건 시대를 앞서 있다는 확신입니다.","당신의 창의성은 커피 머신 하나를 문명 프로젝트로 바꿉니다. 사랑에는 공간이 필요하고 휴식에는 기계가 필요하죠. 새 유행이 남들에게 퍼지는 순간 흥미를 잃습니다. 당신의 머릿속은 개막일에 작품을 철거하는 상설 전시회 같군요."]},"pisces":{"classic":{"career":["풍부한 상상력은 지나치게 딱딱한 방식이 놓치는 가능성을 보여 줄 수 있어요.","직감도 함께 결정하기 전에 차분히 살펴볼 가치가 있어요.","대화 속에서 보여 주는 섬세함은 팀의 기대를 더 잘 이해하는 데 도움이 됩니다.","아이디어가 여러 개 떠오를 때 현실적인 첫걸음을 정하면 창의력이 형태를 갖추기 시작해요.","분위기를 알아차리는 능력 덕분에 상황을 부드럽게 다룰 수 있어요.","몽상적인 모습 뒤에는 멀리 떨어진 생각들을 특별하게 연결하는 능력이 숨어 있기도 해요.","업무에서 명확한 경계를 세우면 중요한 프로젝트에 쓸 여유를 지킬 수 있어요.","영감을 행동으로 옮기려면 약간의 시간과 구조가 필요해요."],"love":["당신의 섬세함은 대화 속 미묘한 감정을 따뜻한 마음으로 받아들이게 해 줍니다.","조용한 배려도 거창한 낭만적인 행동만큼 많은 것을 전할 수 있어요.","다른 사람에게 베푸는 다정함에 자신의 필요를 듣는 마음도 함께해 주세요.","상상력이 너무 커질 때는 실제로 오간 말들을 되짚으면 생각을 분명히 할 수 있어요.","풍부한 애정은 각자가 자기 모습으로 자유롭게 지낼 수 있는 관계를 만들게 합니다.","조화를 꿈꾸는 마음 뒤에서도 소박하고 진실한 관계의 아름다움을 발견할 수 있어요.","친밀한 관계에서 두려움 없이 질문하는 일도 신뢰를 키워요.","상대의 감정을 받아들인다고 모든 문제의 해결책까지 찾아야 하는 건 아니에요."],"wellbeing":["섬세한 당신에게는 생각을 부담 없이 내려놓을 수 있는 조용한 장소가 잘 어울려요.","부드러운 음악이나 잠깐의 침묵은 자기 리듬을 되찾는 데 도움이 됩니다.","꿈꾸는 시간도 소중하지만 지금의 순간을 즐길 자리는 남겨 두세요.","주변의 요청이 많아질 때 소박한 휴식이 자신만의 공간을 되찾아 줄 수 있어요.","풍부한 상상력은 노트 한 권이나 산책, 익숙한 풍경에서도 자라납니다.","다른 사람에게 쏟는 관심만큼 자신을 기쁘게 하는 일에도 시간을 주세요.","하루 중 따뜻한 대화 하나가 마음을 편안하게 붙잡아 줄 수 있어요.","쉬고 싶은 마음에 귀 기울여도 너그러움이 줄어드는 건 아니에요."],"wisdom":["섬세함은 자신의 경계도 존중할 때 강점이 됩니다.","꿈은 현실의 작은 행동을 만날 때 더 깊어집니다.","부드러운 마음으로 모두의 걱정을 짊어질 필요는 없어요.","모든 느낌은 귀 기울일 가치가 있지만 긴 이야기까지 만들 필요는 없습니다.","직관은 몇 가지 질문도 받아들일 때 더욱 명확해집니다.","곁을 지켜 준다는 것이 모든 어려움을 해결한다는 뜻은 아닙니다.","상상력은 문을 열고 현실은 걸어갈 길을 보여 줍니다.","다정하다는 이유로 다른 사람을 위해 자신을 잊을 필요는 없습니다."],"roast":["상상력이 평범한 대화를 실제 사실보다 훨씬 복잡한 이야기로 바꿀 수 있어요.","사소한 도움을 부탁받아도 자신의 필요를 뒤로 미루곤 해요.","몽상에 자주 빠져서 현실적인 일들은 당신이 돌아오기를 기다릴 때가 있어요.","감정 하나가 찾아오면 마음의 모든 자리를 내어 주는 경우가 있어요.","모두를 이해하고 싶은 마음 때문에 다른 사람의 서툰 행동을 너무 쉽게 용서할 수 있어요.","아름다운 직감 뒤에서도 몇몇 세부 사항은 실제로 확인해야 해요.","간단한 결정을 할 때조차 상상력이 수많은 가능성을 보여 줍니다.","머릿속에서 이미 이야기가 시작됐다면 대화의 흐름을 다시 찾기 어려울 때가 있어요."]},"funny":{"career":["당신의 창의력은 공지문을 소설 첫 장으로 바꿉니다. 공지문에는 창문을 닫으라고만 적혀 있었는데요.","회의가 세 가지 주제로 진행 중인데 당신은 네 번째 주제에서 돌아오셨군요. 아무도 꺼내지 않았지만 직감이 흥미롭다고 판단한 주제였죠.","착한 마음으로 동료 세 명을 동시에 돕습니다. 자기 업무 파일은 조심스럽게 알림을 보냅니다.","모니터 앞에서 멍하니 있을 때 천재적인 프로젝트를 구상 중일 수도 있어요. 아니면 상상 속 왕국의 이름을 짓고 있겠죠.","분위기가 바뀔 거라는 직감이 찾아옵니다. 바뀐 건 동료가 과자 상자를 연 것뿐이에요.","모든 걸 고쳐 주고 싶어서 아무 부탁도 하지 않은 사람의 책상까지 재정리하기로 동의했어요.","업무 지시에서 창의적인 해결책을 떠올리고 또 다른 해결책과 냅킨 위의 스케치까지 그렸습니다. 제출 시간은 화면 밖으로 사라졌군요.","토론 전에 최선의 해결책을 직감으로 알아채십니다. 동료들은 그 중간 과정도 알고 싶어 할 텐데요.","회의 중 직감이 해결책을 속삭입니다. 당신은 종이에 적어 놓는데, 그 종이는 즉시 찾을 수 없는 아이디어 수집품에 합류하네요.","달력에는 확정된 마감일이 적혀 있습니다. 당신에게는 창의적인 분위기에서 일하라는 초대장처럼 보이는군요.","아름다운 그림과 섬세한 설명으로 발표 자료를 준비합니다. 그런데 누군가 무서운 질문 하나를 던지네요. '그래서 뭘 먼저 하죠?'","진행 상황을 점검하는 회의에서 바닷물의 흐름에 관한 비유가 떠오릅니다. 책임자는 납품 항목에 '유연한 아이디어'라고 적었군요."],"love":["당신의 로맨스는 단순한 안녕하세요 한마디로 영화 한 편을 씁니다. 상대는 올바른 버스 정류장을 찾고 있었어요.","라디오에서 노래가 나오면 소중한 추억이 떠올라요. 그 기억에 이미 영화음악 전체를 붙였죠.","메시지에 평소와 다른 마침표가 있다는 사실을 알아차립니다. 문장부호 조사가 시작돼요.","누군가 우산을 빌려주면 너무 감동해서 시를 써 줄까 고민합니다.","넘치는 다정함은 베란다의 화분들에게도 향해요. 행복해 보이면 잘했다고 칭찬하죠.","꿈꾸는 눈빛 뒤에서는 아름다운 로맨스 장면이 펼쳐집니다. 현실에서는 직원이 주문을 기다리고 있어요.","첫 저녁에 다정한 눈빛 하나만 받아도 머릿속에서는 장대한 이야기와 엔딩곡이 흐릅니다. 상대방은 아직 전채요리 메뉴를 읽고 있군요.","함께 걷는 것만으로도 동네의 불 켜진 창문마다 이야기를 만들어 냅니다.","카페에서 눈빛 한 번 나누자 머릿속에 3막짜리 사랑 이야기가 펼쳐집니다. 음료가 나오기도 전에 1막이 끝났군요.","아직 제안하지도 않은 첫 데이트의 음악을 마음속으로 골랐습니다. 지휘자는 초대장이 오기를 기다리고 있습니다.","포장지에 그려진 하트 하나가 로맨틱한 장면을 떠올리게 합니다. 제조사는 그냥 과자를 팔 생각이었는데요.","최근 둘이 만난 일을 대서사시처럼 들려주십니다. 상대방은 버스를 타고 갔던 것만 기억합니다."],"wellbeing":["슬리퍼를 찾는 동안 당신의 정신은 벌써 휴가를 떠났어요. 슬리퍼들은 묵묵히 기다립니다.","개울 옆에 앉아 물소리에 맞춰 쉬고 있습니다. 시계는 이 시간을 어떤 활동으로 분류해야 할지 모르겠군요.","휴식 재생목록이 파도 소리로 시작해 빗소리를 지나 분수 소리로 끝납니다. 욕실이 경쟁심을 느끼겠어요.","한 시간 동안 평온한 선율 하나를 들으셨군요. 이제 노래보다 음표 사이의 침묵을 더 잘 아시겠네요.","남을 돌보고 싶은 마음으로 안락의자에게 쿠션까지 권합니다. 의자는 이미 편안해 보이는데요.","평온한 모습 뒤에는 거대한 서사시가 숨어 있어요. 물을 두 모금 마시는 사이 왕국 세 곳을 통과했죠.","잠자리에 들자 애니메이션의 감동적인 장면이 떠오릅니다. 베개는 긴 밤을 예상해요.","현재로 돌아오려면 가끔 표지판이 필요해요. 10분째 찾고 있는 열쇠 바로 옆에 있습니다.","창문을 열고 빗소리를 듣습니다. 휴대전화는 지금 듣고 있는 소리를 똑같이 흉내 내는 앱을 추천하네요.","잔잔한 노래로 쉬기 시작했다가 발이 물에 잠긴 채 끝납니다. 양탄자는 이 선택을 체념하며 받아들이는군요.","공원의 분수 하나만으로도 짧은 평온을 얻습니다. 옆의 오리도 같은 공연을 예약한 모양이군요.","고요한 선율을 들으며 눈을 감습니다. 세상은 다음 음표가 올 때까지 기다려도 괜찮습니다."],"wisdom":["당신의 직감은 때로 빛납니다. 다만 화장실 방향 표시를 신비한 징조로 착각할 수도 있죠.","일상의 모든 신호가 메시지는 아닙니다. 어떤 표지판은 정말로 출구만 가리킵니다.","우주에서 영감을 받을 수는 있지만 냉장고에서 나는 모든 소리까지 우주의 뜻이라고 할 필요는 없어요.","신비로운 눈빛마다 특별한 이야기가 시작되는 건 아니에요.","직관도 가끔 받은 편지함을 확인해야 해요.","위로한다고 슬퍼 보이는 토스터를 입양할 필요는 없어요.","영감은 자유롭게 여행하지만 약속 시간은 그대로예요.","구름이 당신에게 개인적인 메시지를 보냈다는 증거는 없어요.","직감은 호기심 많은 안내자입니다. 하지만 길가의 화살표를 늘 대신할 수 있는 건 아닙니다.","하늘의 징조가 보인다고 모든 표지판에 직접 질문해야 하는 것은 아닙니다.","당신의 본능은 가끔 정확합니다. 다만 작은 글씨도 읽는 연습을 해야겠죠.","우연에는 재능이 많습니다. 그렇다고 하루의 모든 질문을 맡길 필요는 없어요."],"roast":["세 사람의 열쇠를 찾아주는 동안 자신의 열쇠를 잃어버리셨군요. 열쇠 꾸러미가 상담 센터 개설을 고민합니다.","살짝 기운 화분을 보고 위로의 대화를 시작해요. 화분은 햇빛이 필요했을 뿐인데요.","몽상에 너무 멀리 떠나서 식어 버린 차에도 버림받은 사연이 생깁니다.","서점에 들어가면 책을 펼치기도 전에 등장인물에게 정이 들어요.","빈 가방을 들고 있던 사람을 도와주셨군요. 그 사람은 추천 경로와 당신의 전화번호까지 챙겨서 집에 돌아갔습니다.","펜을 찾으러 나갔다가 한 동료에게 물을 가져다주고 다른 동료에게 조언을 하고 돌아왔습니다. 펜은 잊으셨군요.","지하철에서 누군가와 눈이 마주치자 과거와 비밀, 마지막 반전까지 만들어 냅니다. 상대는 노선도를 보고 있었어요.","안경이 책상 위에 있는데 온 집 안에서 찾고 계시네요. 그동안 슬퍼하지도 않은 사람을 위로하셨습니다.","친구의 우산을 찾아 주다가 직접 가져다주러 가는 길에 자기 우산을 잃어버리셨군요. 물건들이 의자 뺏기 놀이를 시작했습니다.","집중해서 십자말풀이를 푸는 이웃을 위로하려고 하셨군요. 이웃은 오히려 퍼즐 힌트 하나를 내줬습니다.","누군가에게 찻잔을 가져다주려고 방을 나섰습니다. 수건 세 장과 정리 아이디어 두 개를 들고 돌아왔지만 찻잔은 없네요.","친구가 '괜찮을 거예요'라고 말하자 지원팀을 꾸리려 하십니다. 그는 책장을 조립하는 이야기를 하고 있었는데요."]},"piquant":{"career":["당신의 직감이 업무 지시를 연필로 그린 화살표 하나로 바꿨군요. 화살표가 가리키는 곳은 프로젝트가 아니라 창작실입니다.","사소한 의견 하나로 열두 가지 해석을 만듭니다. 회의록은 소설 분야로 분류됐어요.","너무 착해서 팀 전체의 문제를 떠안아요. 당신의 원래 업무는 공식적으로 주인이 바뀌었습니다.","정확한 결정을 기다리는 사람들이 있는데 시적인 아이디어와 색깔 세 가지를 들고 돌아오셨군요. 결정은 의제에서 빠졌습니다.","회의에서 직감에 따라 사실을 확인하기도 전에 좋은 아이디어를 발표합니다. 그래프는 박수치다가 수치를 바꾸네요.","간단한 일에 창의적인 길 열 개를 제시하셨군요. 달력은 이제 투표권 없는 참관인으로만 참여합니다.","사무실의 모든 고민을 주인 잃은 물건처럼 모읍니다. 분실물 센터는 당신의 입사지원을 거절했어요.","꿈을 일정표로 바꾸는 건 지나치게 단순하다고 생각해요. 달력은 그저 월요일에 출근할지 알고 싶을 뿐입니다.","직감으로 업무 지시를 읽지도 않고 프로젝트를 승인하셨군요. 관리표에는 '영감 있음, 근거 추후 확인'이라고 적혔습니다.","일정에 관한 질문에 예술적인 도식으로 답합니다. 날짜는 추상적인 파도로 표현됐군요.","사내 공지입니다. 창의성 덕분에 아이디어 열네 개가 나왔습니다. 정작 어디로 파일을 보내야 하는지는 하나도 적혀 있지 않네요.","지각하면서도 시간 관리에 관한 훌륭한 아이디어를 들고 오셨군요. 시계는 그 발표에 참석하지 않기로 했습니다."],"love":["당신의 로맨스는 2초간 마주친 눈빛을 여덟 시즌짜리 드라마로 바꿉니다. 주연 배우는 촬영 사실도 몰라요.","짧은 답장을 받으면 비극적 대본을 쓰고 이어서 행복한 속편까지 만듭니다. 메시지는 고작 알겠어였는데요.","다정한 마음 때문에 친절한 사람 모두와 감정적으로 가족이 됩니다. 배달 기사도 머릿속 소설에 등장해요.","누군가 예의상 웃기만 해도 상상력이 예고편을 제작합니다. 미소는 초상권료를 요구해요.","메시지 끝에 찍힌 마침표 하나가 거대한 사랑 이야기의 신호가 됩니다. 마침표는 그냥 문장을 끝내려 했을 뿐인데요.","소박한 사랑을 약속하는 말 뒤에는 시나리오 작가팀이 숨어 있어요. 화요일의 반전 세 개까지 이미 준비했습니다.","침묵이 찾아오면 머릿속에 대화 전체를 써 내려갑니다. 상대는 그냥 파스타를 만들고 있었어요.","감정을 나누는 건 전문이죠. 목차가 필요할 만큼 미묘한 메시지를 보냅니다. 마침표는 길을 잃었어요.","엘리베이터에서 눈빛 한 번 나눈 일이 머릿속에서 로맨틱한 대작으로 변합니다. 상대방은 4층에 가려던 것뿐인데요.","짧은 '곧 봐요'를 장엄한 마지막 장면에 어울리는 약속으로 바꿉니다. 원래 대화는 지하철 승차권 한 장보다 짧았는데요.","당신의 마음은 이미 음악과 무대, 결말까지 써 두었습니다. 상대방은 1막 초대장조차 받지 못했군요.","비스듬히 놓인 컵에서도 사랑의 상징을 읽습니다. 커피가 흘렀을 뿐인데 무슨 서사적 의도가 있었겠어요."],"wellbeing":["쉬려고 파도 음악을 틀었습니다. 세 시간이 지나 전 세계 바다의 배경음악은 꿰뚫었지만 일시정지 버튼은 어디 있는지 모르겠군요.","물가에 앉아 평온을 찾다가 너무 오래 머물렀군요. 오리들이 당신을 풍경의 일부로 여기기 시작했습니다.","휴식 재생목록에 물소리 여덟 가지가 있습니다. 아홉 번째부터는 스피커가 조수간만의 차까지 관리한다고 착각하겠어요.","조용해지고 싶어 구름의 기분부터 분석합니다. 하늘은 당신의 알림을 차단했어요.","마음속 안식처에는 폭포와 잔잔한 음악, 비밀 입구가 있습니다. 현실의 거실은 아직도 당신이 돌아와 앉기를 기다리네요.","평온한 표정 뒤에서 감정 법정이 화요일의 대화를 심판하고 있어요. 화요일은 궐석 상태로 무죄 판결을 받았습니다.","잠들려는 순간 정신이 따뜻한 추억들의 감독판을 틀어요. 베개는 정식 민원을 제기합니다.","선율에 너무 오래 몸을 맡긴 나머지 다음 곡은 시작하려고 예약까지 잡아야 할 처지입니다.","빗소리 앱에는 모드가 서른 개 있습니다. 당신은 '아무 의무 없는 화요일'의 정확한 소리를 계속 찾고 있군요.","사무실에 작은 분수를 설치해 안식처를 만들었습니다. 그런데 분수가 아파트 주민회의보다 더 시끄럽군요.","마음속 평온 기상 예보입니다. 부드러운 구름과 끝없는 재생목록. 정지 버튼은 쿠션 아래 숨었네요.","개울의 속삭임에서 고요함을 찾습니다. 하지만 개울은 당신만의 개인 라디오 방송국이 되기를 거절하네요."],"wisdom":["당신의 직관은 세 단어짜리 메시지에서 장편소설을 읽어 냅니다.","우주의 징조라면 눈여겨볼 수 있습니다. 하지만 초록 보행 신호는 개인에게 내린 계시가 아닙니다.","연민 때문에 쿠션의 권리까지 변호할 의무는 없어요.","모든 침묵이 비극을 숨긴 건 아니에요. 가끔은 누군가 밥을 먹고 있죠.","당신의 몽상에는 영화관이 있어요. 현실은 입장권을 기다립니다.","우주 전체를 돕겠다고 나서면 일정표에는 주인이 없어져요.","당신의 직감에는 멋진 안테나가 달렸군요. 운명의 광고 방송까지 수신하는 게 문제입니다.","단순한 고맙다는 말을 당신처럼 장엄하게 해석하는 사람도 드물 거예요.","당신의 본능은 어디서나 숨은 메시지를 읽어 냅니다. 하지만 우주에는 등기우편 서비스가 없답니다.","우연의 일치는 무한한 우주가 보낸 공식 성명이 아닙니다. 당신의 공책은 이미 기자회견을 준비했지만요.","구름 하나하나를 개인적인 신호로 여기십니다. 하늘은 수신인 없는 방송도 송출하거든요.","당신의 직감은 우주 신문을 정기 구독한다고 믿습니다. 그런데 날씨 면을 사설로 착각할 때도 있군요."],"roast":["멀쩡한 선인장의 기분을 고쳐 주겠다고 하셨군요. 선인장은 아주 분명한 침묵으로 답했습니다.","애니메이션을 보고 눈물 흘리는 것은 아주 자연스럽다고 생각해요. 이제 조연에게 사과 편지를 준비합니다.","연민이 넘쳐서 잘못 놓인 쿠션까지 도우려고 합니다. 쿠션은 독립을 요청했어요.","누군가 휴지 한 장을 찾고 있습니다. 당신은 위로의 연설과 지원 계획, 마지막 우산까지 건네시는군요.","섬세함 때문에 날짜도 모르는 추억들을 수집해요. 식당 냅킨 하나가 역사적 유물로 지정됐습니다.","멍한 눈빛 뒤에서는 허가 없이 촬영 중인 내면의 감독이 있어요. 일상은 이의 신청을 준비합니다.","한숨 하나가 들리면 방 전체의 감정에 대한 조사가 시작됩니다. 의자는 단지 삐걱거렸다고 자백했어요.","이웃의 일정표를 정리해 주다가 자신의 일정표를 잃어버리셨군요. 오늘의 약속은 이제 '희미한 추억'으로 분류됐습니다.","이웃의 강아지를 찾아 주고는 물을 챙겨 주려다 자기 가방을 잃어버리셨군요. 선행에는 분실물 센터 계획이 빠져 있었네요.","혼자 가구를 조립할 수 있다는 사람에게 격려와 여분의 나사, 응원 행사까지 준비해 가셨군요.","속보입니다. 필요하지도 않은 사람에게 충전기를 빌려주셨군요. 당신의 휴대전화는 배터리 1%로 그 장면을 지켜봅니다.","동네의 모든 작은 고민을 해결해 주겠다며 나섭니다. 아직 뜯지 않은 자기 우편물은 이사를 결심했군요."]},"roastMy":["물고기자리인 당신에게 이모지 없는 메시지는 여러 막으로 된 비극의 시작이에요. 문장부호를 다시 읽고 설명을 지어내고 화해 장면의 음악까지 고릅니다. 상대는 단지 손이 바빴던 거예요. 당신의 시나리오는 투자금을 잃었습니다.","당신의 상상력은 사실과 영화 예고편의 차이를 몰라요. 버스에서 누군가 쳐다보면 이야기를 한 편 통째로 만들죠. 그 사람이 시간을 묻습니다. 당신은 즉시 결말을 새로 씁니다.","당신은 아무도 도움을 부탁하지 않은 사람들까지 모두 구하고 싶어 해요. 살짝 기운 화분에 마음의 위로를 건넵니다. 창문을 열자 화분이 바로 섭니다. 당신은 공감 능력의 승리라고 선언해요.","물고기자리인 당신은 허구의 이야기를 너무 몰입해서 소파가 드라마 등장인물들을 모두 알 지경이에요. 오해받는 악당을 변호하고 상상 속 영웅을 위로하죠. 소파는 그 회차를 보지도 못했어요. 당신은 40분간 줄거리를 설명합니다.","당신은 열쇠와 컵, 때로는 왜 어디로 가려 했는지도 잃어버려요. 여기저기 찾으면서 멋진 이유를 상상합니다. 열쇠는 주머니에 있었어요. 당신은 운명이 숨겨 둔 거라고 결론 내립니다.","직관은 언제나 미묘한 차이를 해석할 준비가 돼 있어요. 동료가 정말 고맙습니다 대신 고맙습니다라고 쓰면 머릿속 비상대책반이 소집됩니다. 동료는 기차를 타러 급하게 가던 중이었어요.","당신은 추억을 너무 좋아해서 버스표 하나를 감정의 유물로 만들어요. 모든 물건에 사연과 분위기, 대략적인 날짜가 있죠. 낡은 종이 한 장도 버리지 않습니다. 그 종이는 당신을 기억하지도 못하는데요.","물고기자리인 당신은 쉬겠다고 약속한 뒤 누군가 사소한 걱정 하나를 말하면 곧바로 상담가와 중재자, 해결책 기획자가 됩니다. 상대는 우산에 관한 이야기를 하려던 것뿐이에요. 우산은 이제 자기계발 계획서를 가졌습니다.","당신의 정신은 말없이 대화에서 떠나 상상 속 도시를 지을 수 있어요. 돌아와서는 시적인 생각과 감정만 있고 원래 질문의 답은 없죠. 사람들이 뭘 마실지 묻습니다. 당신은 분수의 역사를 이야기해요.","당신은 지나가는 구름 하나에도 거대한 의미를 부여해요. 바라보며 여행을 상상하고 무슨 메시지를 싣고 있는지 궁금해하죠. 구름은 답 없이 흘러갑니다. 하늘 통역 담당 부서는 그래도 조사에 착수해요.","물고기자리인 당신의 창의성은 업무 지시를 시적인 산책으로 바꿉니다. 사랑에서는 미소 하나가 마음속 장편소설을 엽니다. 물소리에서 평화를 찾고 행복한 식물에게 위로를 건네죠. 식물은 여전히 식물인 채로 감사 인사를 대신합니다.","직감을 안고 회의에 들어갔다가 정해진 칸에 들어가지 않는 아이디어 여덟 개를 들고 나옵니다. 다정한 메시지는 마음속 영화의 한 장면이 되죠. 잔잔한 음악에는 몇 시간씩 빠져듭니다. 그동안 일정표는 자신을 읽어 줄 담당자를 여전히 찾고 있습니다.","부탁받지 않아도 사람들을 도울 만큼 너그럽습니다. 일상 속 징조는 별을 연구하는 사람처럼 진지하게 해석하죠. 그러다 거실로 가는 길에 찻잔을 잊어버립니다. 찻잔은 도움 요청 신호를 보낸 적도 없는데요.","직장에서 가장 좋은 아이디어는 안건이 끝나자마자 떠오릅니다. 사랑에서는 아직 시작하지 않은 이야기의 음악부터 정하죠. 휴식에는 파도 소리를 듣습니다. 일상이 늦은 게 아닙니다. 당신의 배경음악이 끝나기를 기다리는 것뿐입니다.","작은 디테일을 감동적인 이야기로 바꾸는 특별한 재능이 있습니다. 그다음에는 장만 보던 사람 세 명에게 도움을 제안하죠. 당신의 안식처는 시간표가 들어올 수 없는 마음속 바다 같습니다. 장보기 목록은 아직도 자기 주인을 찾고 있네요."]}},"events":{"newMoon":{"classic":["새달은 소박한 바람 하나를 품고, 아직 결과를 재촉하지 않은 채 새로운 시작을 맞이하라고 권합니다.","새달 아래에서는 여린 생각 하나를 위한 자리를 마련하는 것만으로도 새로운 길이 열릴 수 있습니다.","이번 새달은 백지 한 장을 상징합니다. 서두르지 말고 무엇을 키워 갈지 직접 골라 보세요."],"funny":["새달, 새 출발입니다. 그런데 이미 3년 묵은 아이디어를 적으려고 반짝이는 새 공책부터 고르셨군요.","새달이 빈 페이지를 내밉니다. 당신은 제목에 쓸 글꼴을 고르는 데 20분을 쓰시네요.","새달이 떴습니다. 새해 결심들이 다시 출근했는데, 전부 비밀번호를 잊어버렸습니다."],"piquant":["새달이 처음부터 다시 시작해 보라고 권합니다. 걱정 마세요. 늘 하던 즉흥적인 방식은 벌써 준비됐으니까요.","새달 아래서 거창한 변화를 꿈꾸시네요. 지금까지 한 일은 화면의 아이콘 세 개를 옮긴 게 전부지만요.","새달이 빈 페이지를 펼칩니다. 당신의 특기는 표지만 바꿔 똑같은 변명을 다시 베껴 쓰는 것이군요."]},"firstQuarter":{"classic":["상현달은 첫 장애물이 나타나더라도 계획을 다듬으며 의도에 구체적인 형태를 부여하라고 권합니다.","상현달 무렵에는 행동으로 옮기는 과정에서 무엇을 서두르기보다 보완해야 하는지 알 수 있습니다.","이번 상현달은 의욕이 현실과 부딪힐 때 유연하게 꾸준히 나아가는 자세의 중요성을 일깨웁니다."],"funny":["상현달이 말합니다. 계획에는 이제 행동이 필요하다고요. 그러자 일정표가 갑자기 모르는 사이라고 우깁니다.","상현달이 행동을 재촉합니다. 할 일 목록을 너무 완벽하게 만들어서 목록 전담 비서가 따로 필요하겠네요.","상현달을 맞아 드디어 첫걸음을 떼셨군요. 그런데 알고 보니 첫걸음은 열쇠를 찾는 일이었습니다."],"piquant":["상현달은 말뿐 아닌 실천을 요구합니다. 지금의 전략은 설명서 없이 조립한 가구 같네요. 자신감은 넘치고 나사는 세 개 남았습니다.","상현달이 행동하라고 권합니다. 행동할지 회의를 열어 혼자 토론하라는 뜻은 아니에요.","상현달과 함께 첫 장애물이 찾아왔습니다. 가구가 당신을 개인적으로 공격한 것처럼 바라보고 계시네요."]},"fullMoon":{"classic":["보름달은 무르익은 한 단계를 비추며 감정을 맑은 시선으로 돌아보라고 권합니다.","보름달 아래에서는 보이지 않던 것이 더 선명해질 수 있습니다. 그 빛을 받아들이며 자신을 돌아보세요.","보름달은 결실의 가능성을 상징합니다. 앞으로의 길만큼 지금껏 걸어온 길을 인정하는 일도 중요합니다."],"funny":["보름달이 뜨자 감정이 초고화질로 바뀌었습니다. 동료의 '알겠습니다'라는 답장마저 정밀 분석 대상이네요.","보름달이 작은 진실까지 밝혀 줍니다. 서랍이 안 닫히는 이유를 드디어 찾았군요. 정체불명의 충전기 여섯 개였습니다.","보름달 아래서는 모든 것이 극적으로 느껴집니다. 누가 마지막 커피를 마셨는지조차 대형 미스터리죠."],"piquant":["보름달이 외면하던 현실을 비춥니다. 당신의 은밀한 계획은 도서관 한복판의 전광판만큼 눈에 띕니다.","보름달이 뜨니 결산할 시간입니다. 전략이라고 부르셨지만, 사실은 보도자료까지 갖춘 즉흥극에 가깝네요.","보름달이 모든 것을 밝힙니다. 우아한 순간을 꿈꾸셨겠지만, 지난 결정들의 기록이 비공개 상영회를 신청했군요."]},"lastQuarter":{"classic":["하현달은 계속 마음을 쓸 가치가 있는 것을 추리고 나머지는 놓아주라고 권합니다.","하현달 무렵에는 지난 단계를 되돌아보며 더는 필요하지 않은 약속들을 덜어낼 수 있습니다.","하현달은 잠시 물러서서 생각해 보라고 상징적으로 권합니다. 우선순위를 단순하게 하면 다음을 위한 공간이 생깁니다."],"funny":["하현달이 정리를 권합니다. 메일함은 즉시 기한 연장을 신청하네요.","하현달이 내려놓으라고 합니다. 흐릿한 사진 하나를 지운 뒤 박수갈채를 기다리고 계시군요.","하현달을 맞아 드디어 서랍 하나를 정리했습니다. 그리고 정리해야 할 나머지 목록을 발견하셨군요."],"piquant":["하현달이 마음속 대청소를 요구합니다. 변명은 색깔별로 정리했는데 결정은 여전히 양탄자 밑에 있군요.","하현달이 불필요한 것을 버리라고 말합니다. '언젠가 쓸지도 몰라' 수집품 때문에 창고부터 빌려야겠어요.","달이 기울며 단순해지라고 권합니다. 당신은 골칫거리만 만드는 습관과 아직도 협상 중이시네요."]},"moonInSign":{"classic":["달이 당신의 별자리를 지나갑니다. 감정의 소리를 듣되 감정에게 결정권까지 맡기지는 마세요.","달이 당신의 별자리에 있을 때는 직감에 더 많은 공간이 생길 수 있습니다. 순간적인 느낌과 구별해 보세요.","달이 당신의 별자리를 지나는 동안 감정이 상징적으로 전면에 나섭니다. 잠시 시간을 내어 마음을 이해해 보세요."],"funny":["달이 당신의 별자리를 지납니다. 방 분위기를 들어가자마자 알아차리셨는데, 정작 잘못 들어온 방이었군요.","달이 당신의 별자리에 있으니 감정의 볼륨이 커집니다. 컵 하나 고르는 일도 신념의 문제가 되었네요.","달이 당신의 별자리를 지납니다. 뭔가 이상하다는 걸 느끼셨는데, 알고 보니 의자가 삐걱거리는 소리였군요."],"piquant":["달이 당신의 별자리를 지나며 감각을 키웁니다. 그런데 직감은 사실 하나 확인하지 않고 보고서를 완성했네요.","달이 당신의 별자리에 있으니 모든 사소한 것이 메시지가 됩니다. 공유기 표시등까지 비밀 성명을 발표하는 것 같겠어요.","달이 당신의 별자리를 방문합니다. 당신의 내면세계가 아주 작은 불만 하나를 발표하려고 기자회견을 여는군요."]},"sunInSign":{"classic":["태양이 당신의 별자리를 지나갑니다. 이 시기는 자신을 움직이는 힘과 앞으로 계획에 더하고 싶은 추진력을 돌아보라고 권합니다.","당신의 태양 시즌은 지금껏 걸어온 길을 상징적으로 비춥니다. 성장을 인정하면 차분한 자신감을 얻을 수 있습니다.","태양이 당신의 별자리에 있을 때 새로운 자신을 향한 기운이 찾아옵니다. 빛나고 싶은 마음과 깊은 필요를 조화시켜 보세요."],"funny":["태양이 당신의 별자리를 지납니다. 드라마 주제가가 흘러나올 듯 방에 들어서셨는데, 그건 전자레인지 소리였어요.","당신의 태양 시즌입니다. 인생을 크게 돌아볼 계획이지만 일단 새 배경화면부터 고르시는군요.","태양이 당신의 별자리에 있습니다. 생일이 다가오거나 막 지났군요. 달력은 개막식을 요구합니다."],"piquant":["태양이 당신의 별자리를 지나며 당신을 상징적으로 주인공으로 만듭니다. 벌써 본인 시상식의 순서지를 나눠 주셨군요.","태양 시즌을 맞아 자신을 돌아봅니다. 자아는 벌써 대형 강당을 예약해 눈부신 그래프를 발표하려고 하네요.","태양이 당신의 별자리에 있으니 빛나고 싶으시군요. 모든 대화를 '나, 위대한 서사시'라는 강연으로 바꿀 필요는 없습니다."]},"venusInSign":{"classic":["금성이 당신의 별자리를 지나갑니다. 작은 즐거움과 우아한 몸짓, 좋은 대화를 가꾸라고 권합니다.","금성이 당신의 별자리에 있을 때 아름다움을 향한 취향이 일상과 나눔의 방식에 영감을 줄 수 있습니다.","금성이 당신의 별자리를 지나는 동안 부드러움과 조화에 시선이 머뭅니다. 관계를 억지로 진전시킬 필요는 없습니다."],"funny":["금성이 당신의 별자리를 지납니다. 근사한 밤을 위해 촛불을 켰는데, 불빛이 가장 잘 비추는 건 접어야 할 빨랫더미네요.","금성이 당신의 별자리에 있습니다. 구경만 하러 가게에 들어갔다가 '분위기를 완전히 바꿔 줄' 쿠션을 사서 나오셨군요.","금성이 당신의 별자리에 있으니 미적 감각이 깨어납니다. 간식을 먹는 시간보다 예쁘게 차리는 시간이 더 길겠어요."],"piquant":["금성이 당신의 별자리를 지나며 취향을 돋보이게 합니다. 인조 식물도 당신의 심사를 통과하려면 채용 면접을 봐야겠군요.","금성이 당신의 별자리에 있습니다. 완벽한 조화를 원하시지만, 정작 우선순위들은 한집에서 억지로 동거 중이네요.","금성이 당신의 별자리에 있으니 어디서든 매력을 찾으십니다. 열쇠 꾸러미까지 부드러운 조명 아래 사진 촬영을 요구하네요."]},"marsInSign":{"classic":["화성이 당신의 별자리를 지납니다. 행동하고 싶은 마음이 강해질 수 있습니다. 방향을 정하면 그 힘을 현명하게 쓸 수 있습니다.","화성이 당신의 별자리를 지날 때 주도성이 상징적으로 부각됩니다. 대담함에는 인내도 좋은 동반자입니다.","화성이 당신의 별자리에 있을 때는 의지를 드러내되 다른 사람의 속도도 기억하세요. 잘 다스린 추진력이 더 멀리 갑니다."],"funny":["화성이 당신의 별자리를 지납니다. 당장 모든 것을 해결하고 싶으시군요. 알림이 뜨는 순서까지 말이에요.","화성이 당신의 별자리에 있으니 할 일 목록을 경기처럼 공략합니다. 볼펜이 심판을 불렀어요.","화성이 당신의 별자리를 지납니다. 어디로 가야 하는지도 모르면서 벌써 '지금 갑니다'라고 답하셨네요."],"piquant":["화성이 당신의 별자리를 지납니다. 인내심이 이제 봉투 하나에 들어갈 정도인데, 그 봉투마저 잃어버리셨군요.","화성이 당신의 별자리에 있으니 모든 지연이 권위에 대한 도전처럼 느껴집니다. 빨간 신호등조차 당신의 직급을 인정하지 않네요.","화성이 당신의 별자리에서 추진력을 줍니다. 그런데 목적 없는 회의처럼 빠르고 시끄럽게 달리면서 이유는 모르시네요."]},"jupiterInSign":{"classic":["목성이 당신의 별자리를 지나며 시야를 넓히라고 권합니다. 분별력을 잃지 않을 때 자신감도 자랄 수 있습니다.","목성이 당신의 별자리를 지나는 때는 확장의 시기를 상징합니다. 성공을 장담하지 않으면서 새로운 가능성을 살펴보세요.","목성이 당신의 별자리에 있을 때 큰 포부가 힘을 얻습니다. 적절한 균형을 지키면 더 멀리 갈 수 있습니다."],"funny":["목성이 당신의 별자리를 지납니다. 일요일 전까지 외국어 세 개를 배우고 새 사업을 시작하고 지하실까지 정리할 계획이시군요.","목성이 당신의 별자리에 있습니다. 아이디어가 끝없이 커져서 화이트보드가 벽 하나를 더 달라고 하네요.","목성이 당신의 별자리에 있으니 꿈이 큽니다. 장보기 목록에도 '전략적 비전' 항목이 있군요."],"piquant":["목성이 당신의 별자리를 지나며 야망을 키웁니다. 적당히 하라는 감각은 다른 은하로 편도 여행을 떠났군요.","목성이 당신의 별자리에서 자신감을 줍니다. 두 줄짜리 초안을 제국 건설의 마스터플랜처럼 발표하시네요.","목성이 당신의 별자리에 있으니 뭐든 가능해 보입니다. 미루는 습관마저 이제 국제 진출을 꿈꾸는군요."]},"saturnInSign":{"classic":["토성이 당신의 별자리를 지납니다. 차근차근 쌓아 가세요. 꾸준한 노력이 선택의 토대를 튼튼하게 할 수 있습니다.","토성이 당신의 별자리를 지나는 때는 스스로 선택한 책임과 오래가는 약속의 가치를 강조합니다.","토성이 당신의 별자리에 있을 때는 자신의 경계를 분명히 하면 완벽을 강요하지 않고도 성숙해질 수 있습니다."],"funny":["토성이 당신의 별자리를 지납니다. 인생을 정리하려고 파일철을 펼쳤더니 다른 파일철 목록부터 나오네요.","토성이 당신의 별자리에 있으니 책임이 늘어납니다. 이제 달력조차 모든 약속 아래에 서명을 요구합니다.","토성이 당신의 별자리에 있습니다. 규칙을 자랑스럽게 지키시지만, 정작 일곱 번째 규칙을 아는 사람은 아무도 없네요."],"piquant":["토성이 당신의 별자리를 지나며 규율을 무대에 올립니다. 이제 일정표가 당신보다 권위가 높군요.","토성이 당신의 별자리에 있으니 꾸준함이 중요합니다. 첫 일을 시작하지 않으려고 엄격한 규정 열두 쪽부터 쓰셨네요.","토성이 당신의 별자리를 지납니다. 때로는 성숙함과 산책 한 번의 품질 검사를 혼동하시는군요."]},"venusRx":{"classic":["금성 역행은 마음을 움직이는 것과 달라진 취향, 관계에 가치를 부여하는 방식을 다시 살펴보라고 권합니다.","금성이 거꾸로 움직이는 듯 보일 때는 예전의 감정적 기억이 상징적으로 떠오릅니다. 현재와 혼동하지 말고 받아들이세요.","금성이 뒤로 가는 듯 보일 때는 욕구를 잠시 돌아보세요. 자신의 가치관에 더 가까운 즐거움을 찾을 수 있습니다."],"funny":["금성 역행입니다. 옛 재생목록을 발견하자 노래마다 과거 선택의 경위서를 요구하네요.","금성 역행이 오래된 즐겨찾기를 다시 열게 합니다. 예전에 질색하던 장식품을 이제 다시 발견하셨군요.","금성 역행 중에 오래된 메시지 초안을 읽고, 끝내 전송하지 않은 휴대전화에 감사하셨군요."],"piquant":["금성 역행이 지난 취향을 다시 꺼냅니다. 당신은 향수라고 부르지만 검색 기록은 증거라고 부르네요.","금성 역행이 기준을 다시 점검하라고 합니다. 요구 조건 목록이 이미 텅 빈 궁전의 내부 규정집 같군요.","금성 역행이 과거를 진열대에 올립니다. 나쁜 아이디어 코너에 할인 딱지라도 붙은 듯 달려가시네요."]},"marsRx":{"classic":["화성 역행은 에너지를 쓰는 방식을 다시 돌아보라고 권합니다. 생각한 뒤 돌아가는 길이 억지로 밀어붙이는 것보다 유익할 수 있습니다.","화성이 뒤로 가는 듯 보일 때는 느려진 추진력 덕분에 진짜 긴급한 일과 조급함을 구별할 수 있습니다.","화성의 역행은 목표를 조정하고 더 차분한 행동 방식을 되찾으라고 권합니다."],"funny":["화성 역행입니다. 엘리베이터 버튼을 세 번 눌렀군요. 엘리베이터는 아직 당신의 일정표를 읽지 않았답니다.","화성 역행이 추진력을 늦춥니다. 아이디어를 뒤쫓아 달리려는데 아이디어들이 조율 회의를 요청하네요.","화성 역행입니다. 프린터조차 페이지마다 숙고하는 듯합니다. 당신은 격려 연설까지 준비 중이군요."],"piquant":["화성 역행으로 속도가 늦춰졌습니다. '당기시오'라고 쓰인 문을 더 세게 미는 게 당신의 전략이군요.","화성 역행 중에는 조급함이 운전대를 잡습니다. 방향 감각은 집에 두고 왔지만요.","화성 역행은 계획을 다시 보라고 권합니다. 그런데 메트로놈이 박자를 정확히 센다고 혼내는 지휘자처럼 속도를 더 올리려 하시네요."]},"jupiterRx":{"classic":["목성 역행은 진정으로 중요한 것에 비추어 포부를 헤아리라고 권합니다. 성장에는 내면의 확장도 있습니다.","목성이 뒤로 가는 듯 보일 때는 프로젝트를 다시 살펴보며 눈앞의 성과 뒤에 숨은 자원을 발견할 수 있습니다.","목성의 역행은 자신의 신념과 더 넓은 가능성을 향한 계획을 상징적으로 되돌아보게 합니다."],"funny":["목성 역행입니다. 거창한 확장 계획이 잊고 지낸 폴더 탐방으로 바뀌었군요. '나중에 정리'라는 폴더도 있네요.","목성 역행이 내면세계를 탐험하라고 합니다. 사색 공책을 펼쳤더니 오래전에 포기한 정리 계획이 나오네요.","목성 역행 중 목표를 다시 살펴봅니다. '세계 정복' 계획이 드디어 최우선 과제에서 내려왔군요."],"piquant":["목성 역행이 거대한 쇼를 줄입니다. 당신의 야망은 비행선이었는데, 세부 검토가 그 비행선을 붙잡던 줄을 발견했네요.","목성 역행이 성장 전에 생각하라고 합니다. 자아는 아직 상상 속인 사업의 네온 간판부터 주문했군요.","목성 역행이 계획을 현실로 데려옵니다. 거대한 구상은 냅킨 한 장에 적혀 있었고, 냅킨조차 이견이 있었네요."]},"saturnRx":{"classic":["토성 역행은 자신이 따르는 규칙을 다시 살펴보라고 권합니다. 어떤 규칙은 도움이 되지만 어떤 규칙은 바뀔 때가 됐습니다.","토성이 뒤로 가는 듯 보일 때는 약속의 수보다 그 약속의 의미가 더 중요해질 수 있습니다.","토성의 역행은 스스로 택한 책임과 습관 때문에 붙잡고 있는 의무를 구별하라고 권합니다."],"funny":["토성 역행입니다. 자기 규칙을 다시 읽다가 일을 전부 끝내기 전에는 즐기면 안 된다는 조항을 발견하셨군요.","토성 역행이 약속을 돌아보라고 합니다. 매주 화요일 키보드를 닦겠다는 엄숙한 맹세를 찾으셨네요.","토성 역행 중에 자기 절제를 감사하고 있습니다. 추적 관리표가 스스로 휴가를 신청하네요."],"piquant":["토성 역행으로 규칙이 재검토에 들어갑니다. 자잘한 지침으로 요새를 지어 놓고 출구 지도를 잃으셨군요.","토성 역행이 왜 자신의 규칙에 복종하느냐고 묻습니다. 그런데 답변에도 서면 허가가 필요하다는 규정이 있네요.","토성 역행이 약속을 되묻습니다. 책임을 트로피처럼 모으고는 선반이 무겁다고 놀라시네요."]},"eclipseSolar":{"classic":["일식이 다가옵니다. 전통에서는 이를 한 주기의 마무리와 새로운 시작의 가능성을 상징하는 현상으로 봅니다.","일식이 가까워지면 관점을 바꾸는 경험이 오래된 습관을 다시 생각하게 할 수 있습니다.","다가오는 일식은 상징적으로 전환을 떠올리게 합니다. 예상 밖의 일을 받아들이면 새 길이 열릴 수 있습니다."],"funny":["일식이 다가옵니다. 당신도 대변화를 준비 중이군요. 소파를 15센티미터 옮기는 일 말이에요.","일식이 곧 찾아옵니다. 우주는 드문 장면을 준비하는데, 당신은 아직 리모컨을 찾고 계시네요.","일식이 다가옵니다. 새 장을 열겠다고 장엄하게 선언하셨군요. 첫 회의 내용은 양말 찾기입니다."],"piquant":["일식이 전환점을 상징한다고 하니 생활을 바꾸겠다면서 습관은 그대로 두려 하시는군요. 참 대담한 발상이네요.","일식이 다가옵니다. 새로운 시작 계획이 너무 모호해서 '초안의 초안'조차 지나치게 구체적으로 보입니다.","일식은 배경이 달라질 수 있음을 일깨웁니다. 당신은 거창한 징조를 바라면서 몇 주째 작은 명백한 사실을 외면했군요."]},"eclipseLunar":{"classic":["월식이 다가옵니다. 끝을 미리 단정하지 않고 한 장을 더 분명하게 바라보라는 상징으로 볼 수 있습니다.","월식이 가까워지면 오래된 감정을 인정하고 더 잘 이해해야 할 필요가 생길 수 있습니다.","다가오는 월식은 부드럽게 한 단계를 마무리하고 새로운 기준을 맞이하라고 상징적으로 권합니다."],"funny":["월식이 다가옵니다. 한 페이지를 넘기려는데 책갈피 고르는 데 한 시간을 쓰셨군요.","월식이 가까워집니다. 감정들이 대대적인 정리 행사를 준비하는데 정작 상자를 어디에 뒀는지 못 찾으시네요.","월식이 다가오자 추억을 정리합니다. 영수증 서랍은 증언을 거부하고 있군요."],"piquant":["월식이 한 장을 마무리하라고 합니다. 당신은 마지막 말을 하려고 50쪽짜리 부록을 쓰는 편을 택하셨군요.","월식이 다가옵니다. 말하지 못한 마음들이 회의실과 명찰, 발표회까지 예약했지만 솔직함은 초대받지 못했네요.","월식이 감정을 상징적으로 비춥니다. 당신은 감정 앞에 미로를 지은 뒤 길 안내도를 팔 재주가 있으시군요."]},"meteors":{"classic":["밤하늘을 가로지르는 {shower}의 모습은 잠깐 눈길을 주는 것만으로도 감탄할 수 있음을 일깨웁니다.","밤하늘에서 펼쳐지는 {shower}의 빛을 올려다보면 잠시 속도를 늦추고 순간의 아름다움을 맞이할 수 있습니다.","{shower}의 불빛이 순간순간 밤을 밝힙니다. 그 모습은 이루어질 거란 보장 없이도 소박한 소망을 떠올리게 합니다."],"funny":["{shower}의 유성이 하늘을 지나갑니다. 멋진 소원을 준비했지만 막상 빌 때 가장 중요한 내용을 잊으셨군요.","{shower} 관측을 위해 편하게 자리를 잡았습니다. 바로 그 순간 이웃이 정원 조명을 시험하기로 했네요.","{shower}에서 이어지는 불빛이 밤의 장관을 선사합니다. 별똥별을 찾는데 날씨 앱은 업데이트 다섯 번을 요구하네요."],"piquant":["{shower}의 궤적이 밤하늘을 가릅니다. 별들조차 힘차게 움직이는데, 당신은 아직도 '나중에' 버튼과 협상 중이군요.","{shower}의 빛이 궤적을 그립니다. 당신의 소원은 너무 상세해서 심사위원회가 필요할 지경이네요.","밤하늘의 {shower} 앞에서 극적인 징조를 기다립니다. 하늘은 유성을 선물하는데 당신은 시시한 알림부터 확인하시는군요."]}}});
